# semver.py
import re
from typing import List, Tuple, Union, Optional

# --- Internal Utility Functions and Constants ---

# Regex for a SemVer identifier (dot-separated sequence of identifiers)
# Identifiers must be non-empty, composed of [0-9A-Za-z-].
IDENTIFIER_RE = re.compile(r'[0-9A-Za-z-]+')

# Regex for a full SemVer string: MAJOR.MINOR.PATCH-PRERELEASE+BUILD
# Allows for strict validation of components.
SEMVER_RE = re.compile(
    r'^(?P<major>0|[1-9]\d*)\.'
    r'(?P<minor>0|[1-9]\d*)\.'
    r'(?P<patch>0|[1-9]\d*)'
    r'(?:-(?P<prerelease>[\dA-Za-z-]+(?:\.[\dA-Za-z-]+)*))?'
    r'(?:\+(?P<build>[\dA-Za-z-]+(?:\.[\dA-Za-z-]+)*))?$'
)

# --- Version Class Implementation ---

class Version:
    """
    Represents a Semantic Version (MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]).
    """

    def __init__(self, major: int, minor: int, patch: int, prerelease: Tuple[str, ...] = (), build: Tuple[str, ...] = ()):
        self.major = major
        self.minor = minor
        self.patch = patch
        # Store identifiers as tuples of strings
        self.prerelease = prerelease
        self.build = build

    @classmethod
    def parse(cls, text: str) -> 'Version':
        """
        Parses a full SemVer 2.0.0 string.
        Raises ValueError on strict format violations.
        """
        match = SEMVER_RE.match(text)
        if not match:
            raise ValueError(f"Invalid SemVer format: {text}")

        data = match.groupdict()

        # Parse numeric components
        try:
            major = int(data['major'])
            minor = int(data['minor'])
            patch = int(data['patch'])
        except ValueError:
            # Should not happen if regex is correct, but safety check
            raise ValueError("Invalid numeric component in SemVer.")

        # Parse prerelease identifiers
        prerelease_ident = data.get('prerelease')
        prerelease_list = tuple()
        if prerelease_ident:
            identifiers = [i for i in prerelease_ident.split('.') if i]
            if not identifiers:
                raise ValueError("Empty prerelease identifiers.")

            prerelease_list = tuple(identifiers)

            # Check for numeric leading zeros constraint
            for i, identifier in enumerate(identifiers):
                if identifier.isdigit() and len(identifier) > 1 and identifier.startswith('0'):
                    raise ValueError("Numeric identifier in prerelease must not have leading zeros.")

        # Parse build identifiers
        build_ident = data.get('build')
        build_list = tuple()
        if build_ident:
            identifiers = [i for i in build_ident.split('.') if i]
            if not identifiers:
                raise ValueError("Empty build identifiers.")
            build_list = tuple(identifiers)

        return cls(
            major=major,
            minor=minor,
            patch=patch,
            prerelease=prerelease_list,
            build=build_list
        )

    def __str__(self) -> str:
        """Returns the canonical SemVer string."""
        parts = [f"{self.major}.{self.minor}.{self.patch}"]

        prerelease_str = f"-{'.'.join(self.prerelease)}" if self.prerelease else ""
        build_str = f"+{'.'.join(self.build)}" if self.build else ""

        return "".join(parts + [prerelease_str, build_str]).replace("++", "+")

    def __repr__(self) -> str:
        return f"Version('{self.major}.{self.minor}.{self.patch}', prerelease={self.prerelease}, build={self.build})"

    def __hash__(self) -> int:
        # Hash must agree with equality. Since build metadata is ignored for comparison,
        # we must only hash based on components relevant to comparison (major, minor, patch, prerelease).
        return hash((self.major, self.minor, self.patch, self.prerelease))

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented

        # Equality ignores build metadata
        return (self.major == other.major and
                self.minor == other.minor and
                self.patch == other.patch and
                self.prerelease == other.prerelease)

    def _compare_identifiers(self, a_id: str, b_id: str) -> int:
        """Compares two identifiers based on SemVer rules."""
        try:
            # Attempt numeric comparison
            num_a = int(a_id)
            num_b = int(b_id)
            if num_a < num_b: return -1
            if num_a > num_b: return 1
            return 0
        except ValueError:
            # Fallback to ASCII string comparison
            if a_id < b_id: return -1
            if a_id > b_id: return 1
            return 0

    def _compare_prereleases(self, self_pr: Tuple[str, ...], other_pr: Tuple[str, ...]) -> int:
        """Compares two pre-release tuples."""
        len_self = len(self_pr)
        len_other = len(other_pr)

        for i in range(min(len_self, len_other)):
            cmp = self._compare_identifiers(self_pr[i], other_pr[i])
            if cmp != 0:
                return cmp

        # If all matched, the shorter list loses (is lower)
        if len_self < len_other:
            return -1
        if len_self > len_other:
            return 1
        return 0

    def __lt__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented

        # 1. Compare numeric components
        if self.major != other.major: return self.major < other.major
        if self.minor != other.minor: return self.minor < other.minor
        if self.patch != other.patch: return self.patch < other.patch

        # Major.Minor.Patch are equal. Now compare pre-releases.

        self_pr = self.prerelease
        other_pr = other.prerelease

        # 2. Presence of pre-release: Non-prerelease > Pre-release
        has_pr_self = bool(self_pr)
        has_pr_other = bool(other_pr)

        if has_pr_self and not has_pr_other:
            return True  # Self is prerelease, Other is stable -> Self < Other
        if not has_pr_self and has_pr_other:
            return False # Self is stable, Other is prerelease -> Self > Other

        if not has_pr_self and not has_pr_other:
            return False # Both stable, equal so far

        # 3. Both are pre-release: Compare identifier by identifier
        return self._compare_prereleases(self_pr, other_pr) < 0

    # Define other comparison operators based on __lt__
    def __le__(self, other: object) -> bool:
        if not isinstance(other, Version): return NotImplemented
        return self < other or self == other

    def __ge__(self, other: object) -> bool:
        if not isinstance(other, Version): return NotImplemented
        return self > other or self == other

    def __gt__(self, other: object) -> bool:
        if not isinstance(other, Version): return NotImplemented
        return not (self <= other)

    def __ne__(self, other: object) -> bool:
        return not self.__eq__(other)

    def bump(self, kind: str) -> 'Version':
        """Returns a new version bumped by the specified kind."""
        kind = kind.lower()

        if kind == 'major':
            return Version(self.major + 1, 0, 0)
        elif kind == 'minor':
            return Version(self.major, self.minor + 1, 0)
        elif kind == 'patch':
            return Version(self.major, self.minor, self.patch + 1)
        else:
            raise ValueError(f"Invalid bump kind: '{kind}'. Must be 'major', 'minor', or 'patch'.")

# --- Range Satisfiability Implementation ---

def _normalize_partial_version(text: str) -> Version:
    """
    Converts a potentially partial version string (e.g., '1.2' or '1')
    into a full Version object (e.g., 1.2.0).
    Requires no pre-release or build components.
    """
    match = re.match(r'^(\d+)(?:\.(\d+))?(?:\.(\d+))?$', text)
    if not match:
        raise ValueError(f"Invalid partial version format: {text}")

    try:
        parts = [int(p) for p in match.groups() if p is not None]

        if not parts:
             raise ValueError("Empty version string.")

        major = parts[0]
        minor = parts[1] if len(parts) > 1 else 0
        patch = parts[2] if len(parts) > 2 else 0

        return Version(major, minor, patch)
    except ValueError as e:
        raise ValueError(f"Failed to normalize version '{text}': {e}")


def satisfies(version: Union[Version, str], spec: str) -> bool:
    """
    Checks if a given version (or version string) satisfies a specification string.
    """

    # Ensure we are working with a Version object
    if isinstance(version, str):
        try:
            v = Version.parse(version)
        except ValueError:
            raise ValueError(f"Invalid version string provided for satisfaction check: {version}")
    else:
        v = version

    if not spec:
        # An empty spec technically satisfies nothing, but based on prompt requirements,
        # we assume malformed spec raises error.
        raise ValueError("Specification string cannot be empty.")

    spec_parts = spec.split()

    for part in spec_parts:
        if not part:
            continue

        operator = ''
        version_text = part

        # Check for operators
        if part.startswith('>='):
            operator = '>='
            version_text = part[2:]
        elif part.startswith('<='):
            operator = '<='
            version_text = part[2:]
        elif part.startswith('=='):
            operator = '=='
            version_text = part[2:]
        elif part.startswith('>'):
            operator = '>'
            version_text = part[1:]
        elif part.startswith('<'):
            operator = '<'
            version_text = part[1:]
        elif part.startswith('^'):
            operator = '^'
            version_text = part[1:]
        elif part.startswith('~'):
            operator = '~'
            version_text = part[1:]
        elif part == '=':
            operator = '='
            version_text = part[1:]
        else:
            # Bare version implies equality
            operator = '='

        try:
            # Convert the version text (which might be partial) into a concrete Version object
            target_version = _normalize_partial_version(version_text)
        except ValueError as e:
            raise ValueError(f"Malformed version in specification '{part}': {e}")

        # --- Apply Logic Based on Operator ---

        if operator == '=':
            if v != target_version:
                return False

        elif operator == '>=':
            if v < target_version:
                return False

        elif operator == '<=':
            if v > target_version:
                return False

        elif operator == '>':
            if v <= target_version:
                return False

        elif operator == '<':
            if v >= target_version:
                return False

        # Handle caret (^) operator: >=V <MAJOR.0.0 (where MAJOR is the next major version)
        elif operator == '^':
            v_major = target_version.major
            v_minor = target_version.minor
            v_patch = target_version.patch

            if v_major == 0 and v_minor == 0 and v_patch == 0:
                 # ^0.0.0 is undefined in SemVer, treat it as exact match if encountered
                 if v != target_version:
                     return False
            elif v_major == 0 and v_minor == 0:
                 # ^0.0.X: allows minor changes within 0.x.0
                 upper_bound = Version(0, v_patch + 1, 0) if v_patch < 9 else Version(0, 1, 0)
                 lower_bound = target_version
            elif v_major == 0:
                 # ^0.X.Y: allows minor changes within 0.x.0
                 upper_bound = Version(0, v_minor + 1, 0)
                 lower_bound = target_version
            else:
                 # ^X.Y.Z: allows minor and patch changes within X.0.0 to X.(Y+1).0
                 upper_bound = Version(v_major + 1, 0, 0)
                 lower_bound = target_version

            # Check lower bound (must be >= target) AND upper bound (must be < next major)
            if v < lower_bound or v >= upper_bound:
                return False

        # Handle tilde (~) operator: >=V <MINOR+1.0.0
        elif operator == '~':
            v_major = target_version.major
            v_minor = target_version.minor
            v_patch = target_version.patch

            # Upper bound is MAJOR.MINOR+1.0.0
            upper_bound = Version(v_major, v_minor + 1, 0)
            lower_bound = target_version

            # Check lower bound (must be >= target) AND upper bound (must be < next minor)
            if v < lower_bound or v >= upper_bound:
                return False

    return True
