        self.cycle = cycle
        super().__init__(f"Cycle detected: {' -> '.join(cycle + [cycle[0]])}")

def toposort(graph: Mapping[str, Iterable[str]]) -> List[str]:
    """
    Performs a topological sort on the given dependency graph.

    Args:
        graph: A mapping where keys are nodes, and values are iterables 
               of nodes the key depends on.

    Returns:
        A list of nodes ordered such that every node appears after its dependencies.

    Raises:
        CycleError: If the dependencies contain a cycle.
    """

    # 1. Identify all nodes
    all_nodes: Set[str] = set(graph.keys())
    for dependencies in graph.values():
        all_nodes.update(dependencies)

    if not all_nodes:
        return []

    # 2. Initialize data structures for Kahn's Algorithm

    # in_degree: Counts how many prerequisites each node has
    in_degree: Mapping[str, int] = {node: 0 for node in all_nodes}

    # adj: Adjacency list (Dependency -> Dependents). 
    # adj[D] lists all nodes V such that V depends on D.
    adj: Mapping[str, List[str]] = {node: [] for node in all_nodes}

    # 3. Build the graph structure (adj and in_degree)

    # Iterate through the input graph: Key (Dependent) depends on Values (Dependencies)
    for dependent_node, dependencies in graph.items():
        for dependency_node in dependencies:
            # Edge goes from Dependency -> Dependent

            # Ensure nodes exist in the structures, although step 1 should cover this
            if dependency_node not in all_nodes:
                continue
            if dependent_node not in all_nodes:
                continue

            # Increment in_degree of the dependent node
            in_degree[dependent_node] += 1

            # Build the adjacency list: Dependency points to Dependent
            adj[dependency_node].append(dependent_node)

    # 4. Initialize Priority Queue

    # The priority queue (min-heap) holds nodes ready to be sorted (in_degree == 0)
    # We use a min-heap to ensure lexicographical tie-breaking.
    pq: List[str] = []
    for node in all_nodes:
        if in_degree[node] == 0:
            heapq.heappush(pq, node)

    # 5. Perform Topological Sort
    result: List[str] = []

    while pq:
        u = heapq.heappop(pq)
        result.append(u)

        # For every node v that depends on u
        for v in adj[u]:
            in_degree[v] -= 1

            # If v now has no remaining dependencies, it is ready
            if in_degree[v] == 0:
                heapq.heappush(pq, v)

    # 6. Cycle Detection
    if len(result) != len(all_nodes):
