            state = {node: 0 for node in all_nodes}
            path_stack: List[str] = [] # Current path being explored

            # The search needs to respect the dependencies (Dependency -> Dependent)

            def dfs(u: str) -> List[str]:
                state[u] = 1  # Mark as visiting
                path_stack.append(u)

