    """
    Helper function to build in_degree and adjacency list (Dependency -> Dependents).
    """
    in_degree: Dict[str, int] = {node: 0 for node in all_nodes}
    adj: Dict[str, List[str]] = {node: [] for node in all_nodes}

    for dependent_node, dependencies in graph.items():
        for dependency_node in dependencies:
            if dependency_node not in all_nodes or dependent_node not in all_nodes:
                continue

            # Edge goes from Dependency -> Dependent
            in_degree[dependent_node] += 1
            adj[dependency_node].append(dependent_node)

    return in_degree, adj

