def levels(graph: Mapping[str, Iterable[str]]) -> List[List[str]]:
    """
    Groups nodes into layers based on the length of the longest dependency chain.
    """

    all_nodes: Set[str] = set(graph.keys())
    for dependencies in graph.values():
