    queue: List[str] = list(targets_set)

    while queue:
        node = queue.pop(0)

        if node in required_nodes:
            continue

        # Check if the target itself is a recognized node
        if node not in set(graph.keys()) and not any(node in deps for deps in graph.values()):
            raise KeyError(f"Target node '{node}' is not defined in the graph.")

        required_nodes.add(node)

        # Add dependencies (ancestors) to the queue
        if node in graph:
            for dependency in graph[node]:
                if dependency not in required_nodes:
                    queue.append(dependency)

    # 2. Build the induced subgraph structures

    # We only care about edges where both source and destination are in required_nodes.

    # Build temporary graph structures (in_degree and adj) for the subgraph
    subgraph_graph: Mapping[str, Iterable[str]] = {}
    subgraph_nodes: Set[str] = required_nodes

    for node in subgraph_nodes:
        subgraph_graph[node] = []

    for dependent_node in subgraph_nodes:
        original_dependencies = graph.get(dependent_node, [])
        required_deps = [dep for dep in original_dependencies if dep in subgraph_nodes]
        subgraph_graph[dependent_node] = required_deps


    # 3. Run topological sort on the subgraph

    # We reuse the core logic of toposort, but constrained to the subgraph

    sub_all_nodes = subgraph_nodes
    sub_in_degree, sub_adj = _build_graph_structures(subgraph_graph, sub_all_nodes)

    pq: List[str] = []
    for node in sub_all_nodes:
        if sub_in_degree[node] == 0:
            heapq.heappush(pq, node)

    result: List[str] = []

    while pq:
        u = heapq.heappop(pq)
        result.append(u)

        for v in sub_adj[u]:
            sub_in_degree[v] -= 1

            if sub_in_degree[v] == 0:
                heapq.heappush(pq, v)

    # 4. Cycle Detection for the subgraph
    if len(result) != len(sub_all_nodes):

        # Since we already verified the nodes exist and dependencies are limited to the subgraph, 
        # a failure here means a cycle exists within the required nodes.

        def find_cycle_path(start_node: str) -> List[str]:
            """DFS implementation to find a back edge (a cycle)."""
            state: Dict[str, int] = {node: 0 for node in sub_all_nodes}
            path_stack: List[str] = []

            def dfs(u: str) -> List[str]:
                state[u] = 1
                path_stack.append(u)

                for v in sub_adj[u]:
                    if state[v] == 1:
                        try:
                            cycle_start_index = path_stack.index(v)
                            return path_stack[cycle_start_index:]
                        except ValueError:
                            pass

                    if state[v] == 0:
                        cycle = dfs(v)
                        if cycle:
                            return cycle

                state[u] = 2
                path_stack.pop()
                return []

            return dfs(start_node)

        cycle_nodes = [node for node in sub_all_nodes if sub_in_degree[node] > 0]

        for node in cycle_nodes:
            cycle_path = find_cycle_path(node)
            if cycle_path:
                 raise CycleError(cycle_path)

        # Fallback, though theoretically unreachable if length check fails
        raise CycleError(["Cycle detected in subgraph"]) 


    return result


