import re
from dataclasses import dataclass, field
from typing import List, Dict, Any, Optional
from datetime import date as date_type, datetime

# Regex patterns
TAG_PATTERN = re.compile(r"^[a-z0-9][a-z0-9_-]*$")
PRIORITY_PATTERN = re.compile(r"^(high|normal|low)$")

def normalize_title(title: str) -> str:
    """Strips surrounding whitespace and ensures the result is not empty."""
    normalized = title.strip()
    if not normalized:
        raise ValueError("Title cannot be empty.")
    return normalized

def normalize_tag(tag: str) -> str:
    """Strips surrounding whitespace, lowercases, and validates the tag format."""
    normalized = tag.strip().lower()
    if not TAG_PATTERN.fullmatch(normalized):
        raise ValueError(f"Invalid tag format: '{tag}'. Tags must contain only alphanumeric characters, hyphens, or underscores, and cannot start with a hyphen or underscore.")
    return normalized

def normalize_priority(p: str) -> str:
    """Strips and lowercases priority, validating it is 'high', 'normal', or 'low'."""
    normalized = p.strip().lower()
    if not PRIORITY_PATTERN.fullmatch(normalized):
        raise ValueError(f"Invalid priority: '{p}'. Priority must be 'high', 'normal', or 'low'.")
    return normalized

def parse_date(s: str) -> date_type:
    """Parses a string into a date object, strictly requiring YYYY-MM-DD format."""
    try:
        return datetime.strptime(s, "%Y-%m-%d").date()
    except ValueError:
        raise ValueError(f"Invalid date format or value: '{s}'. Must be YYYY-MM-DD and a valid calendar date.")

@dataclass(frozen=True)
class Task:
    """Represents a single todo task with priority and due date."""
    id: int
    title: str
    tags: List[str] = field(default_factory=list)
    done: bool = False
    priority: str = field(default="normal")
    due: Optional[date_type] = field(default=None)

    def to_dict(self) -> Dict[str, Any]:
        """Returns a dictionary representation of the Task, ensuring key order."""
        return {
            "id": self.id,
            "title": self.title,
            "tags": self.tags,
            "done": self.done,
            "priority": self.priority,
            "due": self.due.isoformat() if self.due else None,
        }

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> 'Task':
        """Builds a Task instance from a dictionary, performing validation and normalization."""
        required_keys = ["id", "title", "tags", "done"]

        if not all(key in d for key in required_keys):
            raise ValueError("Missing required keys in task dictionary.")

        try:
            task_id = int(d["id"])
            title = d["title"]
            tags_input = d["tags"]
            done = bool(d["done"])

            # Optional fields
            priority = d.get("priority", "normal")
            due_str = d.get("due")

            if not isinstance(tags_input, list):
                raise ValueError("Tags field must be a list.")

        except (TypeError, ValueError) as e:
            raise ValueError(f"Invalid type found in task dictionary: {e}")

        # Validate Title
        try:
            title = normalize_title(title)
        except ValueError as e:
            raise ValueError(f"Task validation failed: {e}")

        # Validate Tags
        normalized_tags = []
        try:
            for tag in tags_input:
                normalized_tags.append(normalize_tag(tag))
        except ValueError as e:
            raise ValueError(f"Task validation failed: {e}")

        unique_sorted_tags = sorted(list(set(normalized_tags)))

        # Validate Priority
        try:
            priority = normalize_priority(priority)
        except ValueError as e:
            raise ValueError(f"Task validation failed: {e}")

        # Validate Due Date
        due_date: Optional[date_type] = None
        if due_str is not None:
            try:
                due_date = parse_date(due_str)
            except ValueError as e:
                raise ValueError(f"Task validation failed: {e}")

        return cls(
            id=task_id,
            title=title,
            tags=unique_sorted_tags,
            done=done,
            priority=priority,
            due=due_date,
        )
