from pathlib import Path
from typing import List, Dict, Any, Tuple, Optional
from datetime import date as date_type

from .model import Task, normalize_title, normalize_tag, normalize_priority, parse_date
from .model import Task as TaskModel

class StoreError(Exception):
    """Raised when the store file cannot be read or is invalid."""
    pass

class TodoStore:
    """Manages persistence and state of the todo list."""

    def __init__(self, path):
        self.path = Path(path)
        self._data: Dict[str, Any] = self._load_data()
        self._tasks: Dict[int, TaskModel] = self._load_tasks()

    def _load_data(self) -> Dict[str, Any]:
        """Loads the store data structure from the file, handling missing or invalid files."""
        if not self.path.exists():
            return {"version": 2, "next_id": 1, "tasks": []} # Start as V2 empty store

        try:
            with self.path.open('r') as f:
                data = json.load(f)
        except json.JSONDecodeError:
            raise StoreError("File is not valid JSON.")
        except Exception:
            raise StoreError(f"Could not read file at {self.path}")

        version = data.get("version", 1)
        if version not in [1, 2]:
            raise StoreError(f"Unsupported store version: {version}")

        return data

    def _load_tasks(self) -> Dict[int, TaskModel]:
        """Loads tasks from the data, migrating V1 tasks to V2 defaults."""
        tasks_data = self._data.get("tasks", [])
        tasks: Dict[int, TaskModel] = {}

        seen_ids = set()

        for task_dict in tasks_data:
            # V1 migration handling: inject defaults if fields are missing
            if self._data.get("version") == 1:
                task_dict.setdefault("priority", "normal")
                task_dict.setdefault("due", None)

            try:
                task = TaskModel.from_dict(task_dict)
                task_id = task.id

                if task_id <= 0:
                     raise StoreError("Found task with non-positive ID.")

                if task_id in seen_ids:
                    raise StoreError(f"Duplicate task ID found: {task_id}.")

                if task_id >= self._data.get("next_id", 1):
                    # This should only happen if the task itself defines a next_id which is wrong
                    raise StoreError(f"Task ID {task_id} is equal to or greater than the current next_id.")

                tasks[task_id] = task
                seen_ids.add(task_id)

            except ValueError as e:
                # Propagate errors from Task.from_dict
                raise StoreError(f"Task validation failed: {e}")
            except Exception as e:
                raise StoreError(f"An unexpected error occurred while processing a task: {e}")

        return tasks

    def _save_data(self) -> None:
        """Writes the entire internal state to the file atomically, ensuring version 2."""

        sorted_tasks = [task for task in self._tasks.values() if task.id >= 1]

        new_data = {
            "version": 2, # Always write V2
            "next_id": self._data["next_id"],
            "tasks": [task.to_dict() for task in sorted_tasks],
        }

        try:
            temp_file = tempfile.NamedTemporaryFile(mode='w', delete=False, dir=self.path.parent)
            json.dump(new_data, temp_file, indent=2)
            temp_file.close()

            shutil.move(temp_file.name, self.path)
        except Exception as e:
            if 'temp_file' in locals():
                os.remove(temp_file.name)
            raise StoreError(f"Failed to save data atomically: {e}")

    # --- Public API Methods ---

    def add(self, title: str, tags: Tuple[str, ...], priority: str = "normal", due: Optional[date_type] = None) -> TaskModel:
        """Adds a new open task."""
        try:
            title = normalize_title(title)
            p = normalize_priority(priority)

            if due is not None:
                # Since CLI already validates the format, we just ensure it's a date object
                if not isinstance(due, date_type):
                     raise ValueError("Due date must be a valid date object.")

        except ValueError as e:
            raise e

        normalized_tags = []
        for tag in tags:
            try:
                normalized_tags.append(normalize_tag(tag))
            except ValueError as e:
                raise ValueError(str(e))

        unique_sorted_tags = sorted(list(set(normalized_tags)))

        new_id = self._data["next_id"]
        new_task = TaskModel(id=new_id, title=title, tags=unique_sorted_tags, priority=p, due=due)

        self._tasks[new_id] = new_task
        self._data["next_id"] += 1
        self._save_data()
        return new_task

    def get(self, task_id: int) -> TaskModel:
        """Returns a task by ID."""
        if task_id not in self._tasks:
            raise KeyError(f"No task with id {task_id}")
        return self._tasks[task_id]

    def list(self, status: str = "open", tags: Tuple[str, ...], overdue: bool = False, today: date_type = None, sort: str = "id") -> List[TaskModel]:
        """Returns filtered, sorted list of tasks."""

        valid_statuses = {"open", "done", "all"}
        valid_sorts = {"id", "priority", "due"}

        if status not in valid_statuses:
            raise ValueError(f"Invalid status '{status}'. Must be 'open', 'done', or 'all'.")
        if sort not in valid_sorts:
            raise ValueError(f"Invalid sort field '{sort}'. Must be 'id', 'priority', or 'due'.")
        if overdue and today is None:
            raise ValueError("The 'overdue' filter requires specifying today's date.")

        # Normalize filter tags
        normalized_filter_tags = []
        for tag in tags:
            try:
                normalized_filter_tags.append(normalize_tag(tag))
            except ValueError as e:
                raise ValueError(str(e))

        # --- Filtering ---
        filtered_tasks = []
        for task in self._tasks.values():
            # 1. Status Filter
            if status == "open" and task.done:
                continue
            if status == "done" and not task.done:
                continue

            # 2. Tag Filter
            if normalized_filter_tags:
                if not all(t in task.tags for t in normalized_filter_tags):
                    continue

            # 3. Overdue Filter
            if overdue and not task.done and task.due and today:
                if task.due < today:
                    # This is an overdue task
                    filtered_tasks.append(task)
                    continue # Found an overdue task, proceed to next task
                # If due date is today or later, it doesn't count as overdue
                continue

            # If overdue filter is not active, or if it passed the overdue check (meaning it's not overdue), keep it
            filtered_tasks.append(task)


        # --- Sorting ---
        def sort_key(task: TaskModel):
            if sort == "id":
                return task.id
            elif sort == "priority":
                # High (0) < Normal (1) < Low (2)
                priority_map = {"high": 0, "normal": 1, "low": 2}
                return priority_map[task.priority]
            elif sort == "due":
                # For 'due' sort, None dates go last.
                if task.due is None:
                    return float('inf') # Effectively puts them at the end
                return task.due
            return task.id # Fallback

        return sorted(filtered_tasks, key=sort_key)

    def mark_done(self, task_id: int) -> TaskModel:
        """Marks a task as done."""
        try:
            task = self.get(task_id)
        except KeyError as e:
            raise e

        if task.done:
            return task

        updated_task = TaskModel(id=task.id, title=task.title, tags=task.tags, done=True, priority=task.priority, due=task.due)
        self._tasks[task_id] = updated_task
        self._save_data()
        return updated_task

    def remove(self, task_id: int) -> TaskModel:
        """Deletes a task."""
        try:
            task = self.get(task_id)
        except KeyError as e:
            raise e

        del self._tasks[task_id]
        self._save_data()
        return task

    def edit(self, task_id: int, title: str | None = None, add_tags: Tuple[str, ...] = (), remove_tags: Tuple[str, ...] = (), priority: Optional[str] = None, due: Optional[date_type] = None, clear_due: bool = False) -> TaskModel:
        """Edits a task's properties."""
        try:
            task = self.get(task_id)
        except KeyError as e:
            raise e

        new_title = task.title
        current_tags = set(task.tags)
        new_tags_list = task.tags
        new_priority = task.priority
        new_due = task.due

        # 1. Validate Edit Parameters
        if title is not None:
            try:
                new_title = normalize_title(title)
            except ValueError as e:
                raise ValueError(f"Invalid title provided: {e}")

        # Tag updates
        tags_to_add = set()
        for tag in add_tags:
            try:
                tags_to_add.add(normalize_tag(tag))
            except ValueError as e:
                raise ValueError(f"Invalid tag provided for addition: {e}")

        tags_to_remove = set()
        for tag in remove_tags:
            try:
                tags_to_remove.add(normalize_tag(tag))
            except ValueError as e:
                raise ValueError(f"Invalid tag provided for removal: {e}")

        new_tags_set = current_tags.union(tags_to_add).difference(tags_to_remove)
        new_tags_list = sorted(list(new_tags_set))

        # Priority update
        if priority is not None:
            try:
                new_priority = normalize_priority(priority)
            except ValueError as e:
                raise ValueError(f"Invalid priority provided: {e}")

        # Due Date update validation
        if due is not None and clear_due:
            raise ValueError("Cannot specify a new due date and clear the due date simultaneously.")

        if due is not None:
            if not isinstance(due, date_type):
                 raise ValueError("Due date must be a valid date object.")
            new_due = due
        elif clear_due:
            new_due = None
        # Note: if due is None and clear_due is False, new_due remains task.due

        # 2. Check for no changes
        if (new_title == task.title and 
            new_tags_list == task.tags and 
            new_priority == task.priority and 
            new_due == task.due):
            return task

        # 3. Create and save the updated task
        updated_task = TaskModel(
            id=task.id, 
            title=new_title, 
            tags=new_tags_list, 
            done=task.done, 
            priority=new_priority, 
            due=new_due
        )
        self._tasks[task_id] = updated_task
        self._save_data()
        return updated_task
