import argparse
import sys
import datetime
from typing import List, Optional, Tuple

from .store import TodoStore, StoreError
from .model import normalize_tag, normalize_priority, parse_date

# --- Utility Functions ---

def format_task(task):
    """Formats a Task object into the required list line format."""

    # 1. Status and Title
    status_indicator = "[x]" if task.done else "[ ]"
    line = f"{task.id} {status_indicator} {task.title}"

    # 2. Priority
    if task.priority == "high":
        line += " !high"
    elif task.priority == "low":
        line += " !low"

    # 3. Due Date
    if task.due:
        line += f" due:{task.due.isoformat()}"

    # 4. Tags
    tags_string = " #".join(task.tags)
    line += tags_string

    return line

def report_error(message: str, exit_code: int):
    """Prints an error message to stderr and exits."""
    sys.stderr.write(f"error: {message}\n")
    sys.exit(exit_code)

def get_store(args, argv: Optional[List[str]] = None) -> TodoStore:
    """Initializes the TodoStore instance."""
    try:
        return TodoStore(args.file)
    except StoreError as e:
        report_error(str(e), 3)

# --- Command Handlers ---

def handle_add(store: TodoStore, args):
    """Handles the 'add' command."""
    try:
        new_task = store.add(args.title, args.tags, args.priority, args.due)
        print(f"added {new_task.id}")
        sys.exit(0)
    except ValueError as e:
        # Exit code 2 for invalid title, tag, priority, or date
        report_error(str(e), 2)

def handle_list(store: TodoStore, args):
    """Handles the 'list' command."""
    try:
        # The store handles all filtering (status, tags, overdue) and sorting.
        tasks = store.list(
            status=args.status, 
            tags=args.tags, 
            overdue=args.overdue, 
            today=args.today,
            sort=args.sort
        )
        for task in tasks:
            print(format_task(task))
        sys.exit(0)
    except ValueError as e:
        # Exit code 2 for invalid status, tag, sort, or missing date for overdue
        report_error(str(e), 2)


def handle_done(store: TodoStore, args):
    """Handles the 'done' command."""
    ids_to_process = [int(id_str) for id_str in args.ids]

    # Check if all IDs exist before making any changes
    for task_id in ids_to_process:
        try:
            store.get(task_id)
        except KeyError:
            # Exit code 1: naming the first missing ID
            report_error(f"no task with id {task_id}", 1)

    # If all exist, process them
    for task_id in ids_to_process:
        try:
            task = store.mark_done(task_id)
            print(f"done {task.id}")
        except Exception as e:
            # Should not happen, but fail safely
            report_error(f"Error marking task {task_id} done: {e}", 1)

    sys.exit(0)

def handle_remove(store: TodoStore, args):
    """Handles the 'remove' command."""
    try:
        task_id = int(args.id)
        task = store.remove(task_id)
        print(f"removed {task.id}")
        sys.exit(0)
    except KeyError as e:
        # Exit code 1: task id does not exist
        report_error(str(e), 1)


def handle_edit(store: TodoStore, args):
    """Handles the 'edit' command."""
    task_id = int(args.id)

    # Usage error check: must specify at least one field
    has_changes = bool(args.title or args.tags or args.untags or args.priority or args.due or args.no_due)
    if not has_changes:
        report_error("Must specify --title, or --tag, or --untag, or --priority, or --due, or --no-due.", 2)

    # Usage error check: --due AND --no-due
    if args.due is not None and args.no_due:
        report_error("Cannot specify a due date and use --no-due simultaneously.", 2)

    try:
        # Convert string date input to datetime.date object if provided
        due_date_obj = None
        if args.due:
            # This handles the validation and conversion to datetime.date
            due_date_obj = parse_date(args.due)

        store.edit(
            task_id=task_id, 
            title=args.title, 
            add_tags=args.tags, 
            remove_tags=args.untags,
            priority=args.priority, 
            due=due_date_obj, 
            clear_due=args.no_due
        )
        print(f"edited {task_id}")
        sys.exit(0)
    except KeyError as e:
        # Exit code 1: task id does not exist
        report_error(str(e), 1)
    except ValueError as e:
        # Exit code 2: invalid title, tag, priority, or date
        report_error(str(e), 2)


# --- Argument Parsing ---

def main(argv: Optional[List[str]] = None) -> int:
    """Main entry point for the CLI."""
    parser = argparse.ArgumentParser(description="Simple Todo Manager.")

    # Global option --file
    parser.add_argument('--file', default='todo.json', help='Path to the todo JSON file.')

    # Global option --today (must be parsed before subcommands)
    parser.add_argument('--today', type=str, help='Specify today\'s date (YYYY-MM-DD) for overdue checks.')

    # Subparsers for commands
    subparsers = parser.add_subparsers(dest='command', required=True)

    # 1. ADD command
    add_parser = subparsers.add_parser('add', help='Add a new task.')
    add_parser.add_argument('title', type=str, help='The title of the task.')
    add_parser.add_argument('--tag', nargs='*', action='append', default=[], help='Tags to add (can be repeated).')
    add_parser.add_argument('--priority', choices=['high', 'normal', 'low'], default='normal', help='Task priority.')
    add_parser.add_argument('--due', type=str, help='Due date in YYYY-MM-DD format.')
    add_parser.set_defaults(func=handle_add)

    # 2. LIST command
    list_parser = subparsers.add_parser('list', help='List tasks.')
    list_parser.add_argument('--status', choices=['open', 'done', 'all'], default='open', help='Filter by status.')
    list_parser.add_argument('--tag', nargs='*', action='append', default=[], help='Tags to filter by (must contain all).')
    list_parser.add_argument('--overdue', action='store_true', help='Only show open tasks strictly due before today.')
    list_parser.add_argument('--sort', choices=['id', 'priority', 'due'], default='id', help='How to sort the list.')
    list_parser.set_defaults(func=handle_list)

    # 3. DONE command
    done_parser = subparsers.add_parser('done', help='Mark tasks as done.')
    done_parser.add_argument('ids', nargs='+', type=str, help='IDs of tasks to mark as done.')
    done_parser.set_defaults(func=handle_done)

    # 4. REMOVE command
    remove_parser = subparsers.add_parser('remove', help='Remove a task by ID.')
    remove_parser.add_argument('id', type=str, help='ID of the task to remove.')
    remove_parser.set_defaults(func=handle_remove)

    # 5. EDIT command
    edit_parser = subparsers.add_parser('edit', help='Edit a task.')
    edit_parser.add_argument('id', type=str, help='ID of the task to edit.')
    edit_parser.add_argument('--title', type=str, help='New title for the task.')
    edit_parser.add_argument('--tag', nargs='*', action='append', default=[], help='Tags to add.')
    edit_parser.add_argument('--untag', nargs='*', action='append', default=[], help='Tags to remove.')
    edit_parser.add_argument('--priority', choices=['high', 'normal', 'low'], help='New priority for the task.')
    edit_parser.add_argument('--due', type=str, help='New due date in YYYY-MM-DD format.')
    edit_parser.add_argument('--no-due', action='store_true', help='Removes the due date.')
    edit_parser.set_defaults(func=handle_edit)

    # Parse arguments
    args = parser.parse_args(argv)

    # Pre-validation for global date option
    today_date = None
    if args.today:
        try:
            today_date = parse_date(args.today)
        except ValueError as e:
            report_error(f"Invalid date for --today: {e}", 2)
    else:
        today_date = datetime.date.today()


    # Initialize Store
    store = get_store(args, argv)

    # Attach today_date to args for handlers to use
    args.today = today_date 

    # Execute command
    try:
        args.func(store, args)
        return 0
    except Exception as e:
        # Catch any unexpected exceptions
        report_error(f"Internal error: {e}", 2)

if __name__ == '__main__':
    sys.exit(main())
