                    # Check for escaped quote (two single quotes)
                    if i < n and sql[i] == "'":
                        str_value.append("'")
                        i += 1
                    break
                elif sql[i] == '\\': # Simple escape handling (not strictly required by prompt, but robust)
                    i += 1
                    if i < n:
                        str_value.append(sql[i])
                else:
                    str_value.append(sql[i])
                    i += 1
            else:
                # Loop finished without finding closing quote
                raise SQLSyntaxError("Unterminated string literal", start_pos)

            tokens.append(Token('STRING', "".join(str_value), start_pos))
            continue

        # Numbers
        if char.isdigit() or (char == '-' and (i + 1 < n and sql[i+1].isdigit())):
            start_pos = pos
            is_negative = False
            if char == '-':
                is_negative = True
                i += 1

            start_digits = i

            # Integer part
            while i < n and sql[i].isdigit():
                i += 1

            value = 0.0
            is_float = False

            # Fractional part
            if i < n and sql[i] == '.':
                i += 1
                is_float = True
                start_frac = i
                while i < n and sql[i].isdigit():
                    i += 1

                if i == start_frac:
                    # Dot without digits on the right
                    raise SQLSyntaxError("Invalid number format (dot without digits)", start_pos)

                frac_str = sql[start_frac:i]
                value = float(sql[start_digits:i])
            else:
                # Pure integer
                int_str = sql[start_digits:i]
                value = int(int_str)

            if is_negative:
                value = -value

            tokens.append(Token('NUMBER', value, start_pos))
            continue

        # Identifiers and Keywords
        if char.isalpha() or char == '_':
            start_pos = pos
            current_word = []
            while i < n and (sql[i].isalnum() or sql[i] == '_'):
                current_word.append(sql[i])
                i += 1

            word = "".join(current_word)
            upper_word = word.upper()

            if upper_word in KEYWORDS:
                kind = 'KEYWORD'
                value = upper_word
            else:
                # Identifiers (names) are case-sensitive
                kind = 'IDENT'
                value = word

            tokens.append(Token(kind, value, start_pos))
            continue

        # Catchall error
        raise SQLSyntaxError(f"Unexpected character '{char}'", pos)

    # Append EOF token
    tokens.append(Token('EOF', None, n))
    return tokens
