```python
from dataclasses import dataclass
from typing import Any, List, Optional, Tuple
from minisql.tokens import Token, SQLSyntaxError

# --- AST Node Definitions ---

@dataclass(frozen=True)
class Column:
    name: str

@dataclass(frozen=True)
class Literal:
    value: Any  # int, float, str, bool, None

@dataclass(frozen=True)
class Compare:
    op: str  # =, !=, <, <=, >, >=
    left: Any
    right: Any

@dataclass(frozen=True)
class And:
    left: Any
    right: Any

@dataclass(frozen=True)
class Or:
    left: Any
    right: Any

@dataclass(frozen=True)
class Not:
    operand: Any

@dataclass(frozen=True)
class IsNull:
    operand: Any
    negated: bool  # True if IS NOT NULL

@dataclass(frozen=True)
class Select:
    columns: Optional[List[str]] # None for *, list of names otherwise
    table: str
    where: Optional[Any] # Condition AST node or None
    order_by: List[Tuple[str, bool]] # (name, descending)
    limit: Optional[int]

# --- Parser Implementation ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token:
        return self.tokens[self.pos]

    def advance(self) -> Token:
        token = self.current_token()
        self.pos += 1
        return token

    def eat(self, token_kind: str, expected_value: Optional[Any] = None) -> Token:
        token = self.current_token()
        if token.kind != token_kind:
            raise SQLSyntaxError(f"Expected {token_kind}, got {token.kind} ('{token.value}')", token.pos)
        if expected_value is not None and token.value != expected_value:
             raise SQLSyntaxError(f"Expected value '{expected_value}', got '{token.value}'", token.pos)
        self.advance()
        return token

    def parse(self) -> Select:
        # 1. SELECT clause
        self.eat('KEYWORD', 'SELECT')
        columns = self._parse_select_list()

        # 2. FROM clause
        self.eat('KEYWORD', 'FROM')
        table_name = self.eat('IDENT').value

        # 3. WHERE clause (Optional)
        where_condition = None
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'WHERE':
            self.advance() # Consume WHERE
            where_condition = self._parse_condition()

        # 4. ORDER BY clause (Optional)
        order_by_list = []
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'ORDER':
            self.advance() # Consume ORDER
            self.eat('KEYWORD', 'BY')

            order_by_list = self._parse_order_by()

        # 5. LIMIT clause (Optional)
        limit = None
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'LIMIT':
            self.advance() # Consume LIMIT
            limit_token = self.eat('NUMBER')
            limit = int(limit_token.value)

        # Check for EOF immediately after the last possible clause
        if self.current_token().kind != 'EOF':
            raise SQLSyntaxError(f"Unexpected token {self.current_token().kind} ('{self.current_token().value}')", self.current_token().pos)

        return Select(columns=columns, table=table_name, where=where_condition, order_by=order_by_list, limit=limit)

    def _parse_select_list(self) -> Optional[List[str]]:
        token = self.current_token()
        if token.value == '*':
            self.advance() # Consume *
            return None

        columns = []
        columns.append(self.eat('IDENT').value)

        while self.current_token().kind == 'COMMA':
            self.advance() # Consume comma
            column_name = self.eat('IDENT').value

            # Check for duplicate names
            if column_name in columns:
                raise SQLSyntaxError(f"Duplicate column name '{column_name}' in select list", token.pos)

            columns.append(column_name)

        return columns

    def _parse_order_by(self) -> List[Tuple[str, bool]]:
        order_items = []

        # Parse first item
        col_name = self.eat('IDENT').value
        descending = False
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'DESC':
            self.advance()
            descending = True
        elif self.current_token().kind == 'KEYWORD' and self.current_token().value == 'ASC':
            self.advance()
            # Default ASC, but consume it if present
            pass

        order_items.append((col_name, descending))

        # Parse subsequent items
        while self.current_token().kind == 'COMMA':
            self.advance() # Consume comma

            col_name = self.eat('IDENT').value
            descending = False

            if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'DESC':
                self.advance()
                descending = True
            elif self.current_token().kind == 'KEYWORD' and self.current_token().value == 'ASC':
                self.advance()
                pass

            order_items.append((col_name, descending))

        return order_items

    # --- Condition Parsing (Operator Precedence: NOT > AND > OR > Comparison/IS NULL) ---

    def _parse_condition(self) -> Any:
        # Start at the lowest precedence level: OR
        return self._parse_or()

    def _parse_or(self) -> Any:
        left = self._parse_and()
        while self.current_token().kind == 'KEYWORD' and self.current_token().value == 'OR':
            op_token = self.advance() # Consume OR
            right = self._parse_and()
            left = Or(left, right)
        return left

    def _parse_and(self) -> Any:
        left = self._parse_not()
        while self.current_token().kind == 'KEYWORD' and self.current_token().value == 'AND':
            op_token = self.advance() # Consume AND
            right = self._parse_not()
            left = And(left, right)
        return left

    def _parse_not(self) -> Any:
        token = self.current_token()
        if token.kind == 'KEYWORD' and token.value == 'NOT':
            self.advance() # Consume NOT
            # NOT applies to an entire condition/operand structure
            operand = self._parse_operand_or_is_null()
            return Not(operand)

        return self._parse_operand_or_is_null()

    def _parse_operand_or_is_null(self) -> Any:
        token = self.current_token()

        if token.kind == 'IDENT':
            self.advance()
            return Column(token.value)

        elif token.kind == 'NUMBER':
            self.advance()
            return Literal(token.value)

        elif token.kind == 'STRING':
            self.advance()
            return Literal(token.value)

        elif token.kind == 'KEYWORD':
            value = token.value
            self.advance()

            if value == 'NULL':
                return Literal(None)
            elif value == 'TRUE':
                return Literal(True)
            elif value == 'FALSE':
                return Literal(False)
            elif value == '(':
                # Parentheses grouping a condition
                self.eat('LPAREN')
                condition = self._parse_condition()
                self.eat('RPAREN')
                return condition
            else:
                # This should be caught by other parsers, but handle keywords here if needed
                raise SQLSyntaxError(f"Unexpected keyword '{value}'", token.pos)

        # Handle IS NULL checks
        if token.kind == 'IDENT':
            # Look ahead to check for IS
            temp_pos = self.pos
            self.advance() # Consume identifier (the operand)

            if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'IS':
                self.advance() # Consume IS

                is_token = self.current_token()
                if is_token.kind == 'KEYWORD' and is_token.value == 'NULL':
                    self.advance() # Consume NULL
                    # Check for NOT NULL
                    negated = False
                    if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'NOT':
                        self.advance() # Consume NOT
                        negated = True

                    return IsNull(Column(token.value), negated)

            # If it wasn't IS NULL, we backtrack and treat it as a regular column identifier
            self.pos = temp_pos
            return Column(token.value)


        # Handle Binary Comparisons
        if token.kind == 'IDENT':
            # Check if the next token is an operator
            temp_pos = self.pos
            self.advance() # Consume LHS identifier

            if self.current_token().kind == 'OP':
                op = self.current_token().value
                self.advance() # Consume operator

                # RHS can be a literal, column, or parenthesis condition
                rhs = self._parse_operand_or_is_null() 
                return Compare(op, Column(token.value), rhs)
            else:
                # Backtrack if it wasn't a comparison
                self.pos = temp_pos
                return Column(token.value)


        raise SQLSyntaxError(f"Expected operand (identifier, literal, or '('), got {token.kind} ('{token.value}')", token.pos)


def parse(sql: str) -> Select:
    tokens = tokenize(sql)
    parser = Parser(tokens)
    return parser.parse()

# Helper function definition (needs to be imported from tokens)
def tokenize(sql: str) -> List[Token]:
    from minisql.tokens import tokenize as token_func
    return token_func(sql)
```

### `minisql/execute.py`

```python
from dataclasses import dataclass
from typing import Any, List, Dict, Tuple, Union
from minisql.parser import Select, Column, Literal, Compare, And, Or, Not, IsNull
from minisql.tokens import SQLError, SQLSyntaxError

class SQLExecutionError(SQLError):
    """Raised during query execution due to data or logic issues."""
    pass

# --- Evaluation Logic ---

# Type mapping for comparison rules
def get_value_type(value: Any) -> str:
    """Determines the type category of a value (str, num, bool, null)."""
    if value is None:
        return 'null'
    if isinstance(value, bool):
        return 'bool'
    if isinstance(value, (int, float)):
        return 'num'
    if isinstance(value, str):
        return 'str'
    raise SQLExecutionError("Unknown value type")

def evaluate_compare(left_val: Any, right_val: Any, op: str) -> Union[bool, None]:
    """Evaluates a binary comparison using three-valued logic."""
    type_l = get_value_type(left_val)
    type_r = get_value_type(right_val)

    # Rule 4: If either side is NULL, comparison is Unknown (None)
    if type_l == 'null' or type_r == 'null':
        return None

    # Rule 4: Values of different kinds
    if type_l != type_r:
        if op == '=':
            return False
        if op == '!=':
            return True
        # Rule 4: All other comparisons between different kinds raise error
        raise SQLExecutionError(f"Cannot compare values of different kinds ({type_l} vs {type_r}) using operator {op}")

    # Values of same kind (Rule 4)
    if type_l == 'num':
        if op == '=': return left_val == right_val
        if op == '!=': return left_val != right_val
        if op == '<': return left_val < right_val
        if op == '<=': return left_val <= right_val
        if op == '>': return left_val > right_val
        if op == '>=': return left_val >= right_val

    elif type_l == 'str':
        # Strings case-sensitive
        if op == '=': return str(left_val) == str(right_val)
        if op == '!=': return str(left_val) != str(right_val)
        # Rule 4: All relational operators raise error for strings
        raise SQLExecutionError("Relational operators (<, >, <=, >=) are not supported for string comparisons.")

    elif type_l == 'bool':
        # Python comparison rules apply: False < True
        if op == '=': return left_val == right_val
        if op == '!=': return left_val != right_val
        if op == '<': return left_val < right_val
        if op == '<=': return left_val <= right_val
        if op == '>': return left_val > right_val
        if op == '>=': return left_val >= right_val

def evaluate_condition(condition: Any, row_values: Dict[str, Any], table_columns: List[str]) -> Union[bool, None]:
    """Recursively evaluates a condition AST node for a specific row."""

    def get_value(col: Column) -> Any:
        """Retrieves the value for a column, defaulting to None if missing (Rule 2)."""
        return row_values.get(col.name, None)

    if isinstance(condition, Literal):
        return condition.value

    elif isinstance(condition, Column):
        # A bare column is not a condition (should be prevented by parser, but safe guard)
        raise SQLExecutionError(f"Bare column {condition.name} provided as a condition.")

    elif isinstance(condition, Compare):
        left_val = get_value(condition.left) if isinstance(condition.left, Column) else condition.left.value
        right_val = get_value(condition.right) if isinstance(condition.right, Column) else condition.right.value
        return evaluate_compare(left_val, right_val, condition.op)

    elif isinstance(condition, IsNull):
        value = get_value(condition.operand) if isinstance(condition.operand, Column) else condition.operand.value
        is_null = value is None
        return not is_null if condition.negated else is_null

    elif isinstance(condition, Not):
        operand_result = evaluate_condition(condition.operand, row_values, table_columns)

        # Rule 5: NOT of unknown is unknown
        if operand_result is None:
            return None
        return not operand_result

    elif isinstance(condition, And):
        left_result = evaluate_condition(condition.left, row_values, table_columns)
        right_result = evaluate_condition(condition.right, row_values, table_columns)

        # Rule 5: AND logic
        if left_result is False or right_result is False:
            return False
        if left_result is None or right_result is None:
            return None
        return True

    elif isinstance(condition, Or):
        left_result = evaluate_condition(condition.left, row_values, table_columns)
        right_result = evaluate_condition(condition.right, row_values, table_columns)

        # Rule 5: OR logic
        if left_result is True or right_result is True:
            return True
        if left_result is None or right_result is None:
            return None
        return False

    else:
        raise SQLExecutionError("Unknown condition AST node encountered.")

# --- Executor ---

def execute(stmt: Select, tables: Dict[str, List[Dict]]) -> List[Dict]:
    """Runs a parsed SQL statement over the in-memory tables."""

    # 1. Table Validation
    if stmt.table not in tables:
        raise SQLExecutionError(f"Unknown table '{stmt.table}'")

    table_data = tables[stmt.table]

    # Determine all available columns in the table
    table_columns = set()
    for row in table_data:
        table_columns.update(row.keys())

    # 2. Apply WHERE filter (Rule 6)
    filtered_rows: List[Dict] = []
    if stmt.where is None:
        filtered_rows = table_data
    else:
        for row in table_data:
            # Map row dictionary to column names for easy access
            row_values = {k: v for k, v in row.items()}

            try:
                condition_result = evaluate_condition(stmt.where, row_values, list(table_columns))
            except SQLExecutionError as e:
                # If evaluation fails for a row (e.g., mixed types in comparison)
                # we treat the row as not matching the condition, or raise if critical
                # Since comparison errors are usually fatal, let's raise them immediately.
                raise e

            # Rule 6: WHERE keeps rows whose condition is True (not unknown)
            if condition_result is True:
                filtered_rows.append(row)

    # 3. Apply ORDER BY (Rule 7)
    def get_sort_key(row: Dict[str, Any], column_name: str) -> Tuple[Any, Any]:
        """
        Retrieves the value and its type for sorting.
        Returns (value, type_category)
        """
        # Rule 2: Unknown columns read as None
        value = row.get(column_name, None)
        type_category = get_value_type(value)
        return value, type_category

    def stable_sort_key(row: Dict[str, Any], order_items: List[Tuple[str, bool]]) -> List[Tuple[Any, str]]:
        """Generates a list of sort keys for a row based on ORDER BY clauses."""
        keys = []
        for col_name, descending in order_items:
            value, type_cat = get_sort_key(row, col_name)

            # Null sorting logic (Rule 7)
            if value is None:
                if descending:
                    # NULL sorts after every value in DESC
                    keys.append((float('inf'), 'null'))
                else:
                    # NULL sorts before every value in ASC
                    keys.append((float('-inf'), 'null'))
                continue

            # For non-null values, we need a comparable type representation
            if type_cat == 'num':
                keys.append((value, 'num'))
            elif type_cat == 'str':
                # Sort strings naturally
                keys.append((str(value), 'str'))
            elif type_cat == 'bool':
                # Booleans are comparable (False < True)
                keys.append((value, 'bool'))
            else:
                 # Should not happen
                keys.append((value, 'unknown'))

        return keys

    # Rule 7: Stable sorting
    # We sort by the inverse of the descending flags, so standard Python sort works.
    def sort_comparator(row: Dict[str, Any]):
        keys = stable_sort_key(row, stmt.order_by)
        return keys

    try:
        filtered_rows.sort(key=sort_comparator, reverse=any(desc for _, desc in stmt.order_by))
    except SQLExecutionError:
        # This handles type mismatches during comparison/sorting of non-NULL values
        raise SQLExecutionError("Data kind mismatch detected during ordering.")


    # 4. Apply LIMIT (Rule 8)
    if stmt.limit is not None:
        final_rows = filtered_rows[:stmt.limit]
    else:
        final_rows = filtered_rows

    # 5. Format results (Rule 9)
    if stmt.columns is None:
        # Select * - shallow copy of the original row data
        return [dict(row) for row in final_rows]
    else:
        # Select specific columns
        result_rows = []
        for row in final_rows:
            new_row = {}
            for col_name in stmt.columns:
                # Use None if the column is missing (Rule 2/9)
                new_row[col_name] = row.get(col_name, None)
            result_rows.append(new_row)
        return result_rows

def query(sql: str, tables: Dict[str, List[Dict]]) -> List[Dict]:
    """Public entry point: parses SQL and executes the query."""
    try:
        stmt = parse(sql)
        return execute(stmt, tables)
    except SQLExecutionError as e:
        raise e
    except Exception as e:
        # Catch parsing errors that might bubble up as generic Exceptions if not handled perfectly
        if isinstance(e, SQLError):
            raise e
        raise SQLExecutionError(f"Internal execution error: {e}")
