### `minisql/tokens.py`

```python
from dataclasses import dataclass
from typing import List, Any

class SQLError(Exception):
    """Base class for all SQL errors."""
    pass

class SQLSyntaxError(SQLError):
    """Raised when the SQL syntax is incorrect."""
    def __init__(self, message: str, pos: int):
        super().__init__(f"Syntax Error at position {pos}: {message}")
        self.pos = pos

@dataclass(frozen=True)
class Token:
    """Represents a single token in the SQL stream."""
    kind: str
    value: Any
    pos: int

KEYWORDS = {
    'SELECT', 'FROM', 'WHERE', 'AND', 'OR', 'NOT', 'ORDER', 'BY',
    'ASC', 'DESC', 'LIMIT', 'IS', 'NULL', 'TRUE', 'FALSE',
    'JOIN', 'ON', 'GROUP', 'AS', 'COUNT', 'SUM', 'AVG', 'MIN', 'MAX'
}

def tokenize(sql: str) -> List[Token]:
    """Tokenizes the SQL string."""
    tokens: List[Token] = []
    i = 0
    n = len(sql)

    def advance(count: int) -> int:
        nonlocal i
        i += count
        return i - count

    def peek(offset: int = 0) -> str:
        if i + offset < n:
            return sql[i + offset]
        return ''

    def skip_whitespace():
        nonlocal i
        while i < n and sql[i].isspace():
            i += 1

    while i < n:
        char = sql[i]
        pos = i

        if char.isspace():
            i += 1
            continue

        # Operators and Delimiters
        if char in '()*,' :
            kind_map = {
                '(': 'LPAREN', ')': 'RPAREN', '*', 'STAR', ',': 'COMMA'
            }
            tokens.append(Token(kind_map[char], char, pos))
            i += 1
            continue

        if char in '=<>!':
            if char == '=' and peek(1) == '=':
                tokens.append(Token('OP', '==', pos))
                i += 2
                continue
            elif char == '<' and peek(1) == '=':
                tokens.append(Token('OP', '<=', pos))
                i += 2
                continue
            elif char == '>' and peek(1) == '=':
                tokens.append(Token('OP', '>=', pos))
                i += 2
                continue
            elif char == '!' and peek(1) == '=':
                tokens.append(Token('OP', '!=', pos))
                i += 2
                continue
            elif char == '<>':
                tokens.append(Token('OP', '!=', pos))
                i += 2
                continue
            else:
                op_char = char
                if op_char == '=':
                    tokens.append(Token('OP', '=', pos))
                    i += 1
                elif op_char == '>':
                    tokens.append(Token('OP', '>', pos))
                    i += 1
                elif op_char == '<':
                    tokens.append(Token('OP', '<', pos))
                    i += 1
                elif op_char == '!':
                    tokens.append(Token('OP', '!=', pos))
                    i += 1
                continue

        # Dot operator
        if char == '.':
            # Ensure the dot is not part of a number (checked by the number parser)
            tokens.append(Token('DOT', '.', pos))
            i += 1
            continue

        # Strings
        if char == "'":
            start_pos = pos
            i += 1 # Consume opening quote
            str_value = []
            while i < n:
                if sql[i] == "'":
                    i += 1 # Consume closing quote
                    # Check for escaped quote (two single quotes)
                    if i < n and sql[i] == "'":
                        str_value.append("'")
                        i += 1
                    break
                elif sql[i] == '\\':
                    i += 1
                    if i < n:
                        str_value.append(sql[i])
                else:
                    str_value.append(sql[i])
                    i += 1
            else:
                raise SQLSyntaxError("Unterminated string literal", start_pos)

            tokens.append(Token('STRING', "".join(str_value), start_pos))
            continue

        # Numbers
        if char.isdigit() or (char == '-' and (i + 1 < n and sql[i+1].isdigit())):
            start_pos = pos
            is_negative = False
            if char == '-':
                is_negative = True
                i += 1

            start_digits = i

            # Integer part
            while i < n and sql[i].isdigit():
                i += 1

            value = 0.0
            is_float = False

            # Fractional part
            if i < n and sql[i] == '.':
                i += 1
                is_float = True
                start_frac = i
                while i < n and sql[i].isdigit():
                    i += 1

                if i == start_frac:
                    # Dot without digits on the right
                    raise SQLSyntaxError("Invalid number format (dot without digits)", start_pos)

                # Reconstruct the number string to handle potential float conversion issues
                num_str = sql[start_digits:i]
                value = float(num_str)
            else:
                # Pure integer
                int_str = sql[start_digits:i]
                value = int(int_str)

            if is_negative:
                value = -value

            tokens.append(Token('NUMBER', value, start_pos))
            continue

        # Identifiers and Keywords
        if char.isalpha() or char == '_':
            start_pos = pos
            current_word = []
            while i < n and (sql[i].isalnum() or sql[i] == '_'):
                current_word.append(sql[i])
                i += 1

            word = "".join(current_word)
            upper_word = word.upper()

            if upper_word in KEYWORDS:
                kind = 'KEYWORD'
                value = upper_word
            else:
                # Identifiers (names) are case-sensitive
                kind = 'IDENT'
                value = word

            tokens.append(Token(kind, value, start_pos))
            continue

        # Catchall error
        raise SQLSyntaxError(f"Unexpected character '{char}'", pos)

    # Append EOF token
    tokens.append(Token('EOF', None, n))
    return tokens
