from dataclasses import dataclass
from typing import Any, List, Optional, Tuple, Dict, Union
from minisql.tokens import Token, SQLSyntaxError, tokenize

# --- AST Node Definitions ---

@dataclass(frozen=True)
class Column:
    # Holds the canonical text: 'name' or 'table.name'
    name: str

@dataclass(frozen=True)
class Aggregate:
    func: str  # COUNT, SUM, AVG, MIN, MAX
    arg: Optional[Column] # None for COUNT(*), Column for COUNT(ref) or func(ref)

    @property
    def canonical_text(self) -> str:
        """Returns the canonical text (e.g., 'COUNT(*)' or 'SUM(t.id)')."""
        if self.func == 'COUNT' and self.arg is None:
            return 'COUNT(*)'
        if self.arg:
            return f"{self.func}({self.arg.name})"
        # This case should ideally not happen if parsing is correct
        return self.func

@dataclass(frozen=True)
class Literal:
    value: Any  # int, float, str, bool, None

@dataclass(frozen=True)
class Compare:
    op: str  # =, !=, <, <=, >, >=
    left: Any
    right: Any

@dataclass(frozen=True)
class And:
    left: Any
    right: Any

@dataclass(frozen=True)
class Or:
    left: Any
    right: Any

@dataclass(frozen=True)
class Not:
    operand: Any

@dataclass(frozen=True)
class IsNull:
    operand: Any
    negated: bool  # True if IS NOT NULL

@dataclass(frozen=True)
class Join:
    table: str # The table name being joined to the LHS
    left: Column # The reference column in the LHS table
    right: Column # The reference column in the RHS table

@dataclass(frozen=True)
class Select:
    # New fields added sequentially: items, join, group_by
    items: List[Tuple[Any, str]] # (expr: Column|Aggregate, key: str)
    columns: Optional[List[str]] # None for *, list of output keys
    table: str
    join: Optional[Join]
    where: Optional[Any]
    group_by: List[str] # Canonical texts of group by expressions
    order_by: List[Tuple[str, bool]] # (text, descending)
    limit: Optional[int]

# --- Parser Implementation ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0
        self.token_map: Dict[str, Token] = {t.kind: t for t in tokens}

    def current_token(self) -> Token:
        return self.tokens[self.pos]

    def advance(self) -> Token:
        token = self.current_token()
        self.pos += 1
        return token

    def eat(self, token_kind: str, expected_value: Optional[Any] = None) -> Token:
        token = self.current_token()
        if token.kind != token_kind:
            raise SQLSyntaxError(f"Expected {token_kind}, got {token.kind} ('{token.value}')", token.pos)
        if expected_value is not None and token.value != expected_value:
             raise SQLSyntaxError(f"Expected value '{expected_value}', got '{token.value}'", token.pos)
        self.advance()
        return token

    def parse(self) -> Select:
        # 1. SELECT clause
        self.eat('KEYWORD', 'SELECT')
        items_tuple = self._parse_select_items()
        items = [item[0] for item in items_tuple]
        output_keys = [item[1] for item in items_tuple]

        if not items:
            raise SQLSyntaxError("SELECT list cannot be empty", self.tokens[0].pos)

        # 2. FROM clause
        self.eat('KEYWORD', 'FROM')
        from_table_name = self.eat('IDENT').value

        # 3. JOIN clause (Optional)
        join_clause = None
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'JOIN':
            self.advance() # Consume JOIN

            joined_table_name = self.eat('IDENT').value

            self.eat('KEYWORD', 'ON')

            left_ref = self._parse_reference()
            self.eat('OP', '=')
            right_ref = self._parse_reference()

            # The LHS column must belong to the FROM table (from_table_name)
            if not left_ref.name.startswith(f"{from_table_name}."):
                raise SQLSyntaxError("Join condition left side must reference a column in the FROM table.", left_ref.name)

            # The RHS column must belong to the joined table (joined_table_name)
            if not right_ref.name.startswith(f"{joined_table_name}."):
                raise SQLSyntaxError("Join condition right side must reference a column in the JOIN table.", right_ref.name)

            join_clause = Join(joined_table_name, left_ref, right_ref)


        # 4. WHERE clause (Optional)
        where_condition = None
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'WHERE':
            self.advance() # Consume WHERE
            where_condition = self._parse_condition()

        # 5. GROUP BY clause (Optional)
        group_by_refs = []
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'GROUP':
            self.advance() # Consume GROUP
            self.eat('KEYWORD', 'BY')

            group_by_refs = [self._parse_reference().name for _ in range(self._parse_ref_list())]

        # 6. ORDER BY clause (Optional)
        order_by_list = []
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'ORDER':
            self.advance() # Consume ORDER
            self.eat('KEYWORD', 'BY')
            order_by_list = self._parse_order_by()

        # 7. LIMIT clause (Optional)
        limit = None
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'LIMIT':
            self.advance() # Consume LIMIT
            limit_token = self.eat('NUMBER')
            limit = int(limit_token.value)

        # Check for EOF
        if self.current_token().kind != 'EOF':
            raise SQLSyntaxError(f"Unexpected token {self.current_token().kind} ('{self.current_token().value}')", self.current_token().pos)

        # --- Syntax Constraint Checks ---

        is_grouped = bool(group_by_refs) or any(isinstance(expr, Aggregate) for expr, _ in items_tuple)

        # Check 1: * in grouped query
        if is_grouped and (items[0] == '*' if len(items) == 1 else False):
             raise SQLSyntaxError("Cannot use '*' in a grouped query.", self.tokens[0].pos)

        # Check 2: Non-grouped aggregate in ORDER BY
        if not is_grouped and any(isinstance(expr, Aggregate) for expr, _ in items_tuple) and order_by_list:
            for text, _ in order_by_list:
                # If the ORDER BY text matches an aggregate's canonical text, it's an error
                is_aggregate_ref = any(expr.canonical_text == text for expr, _ in items_tuple if isinstance(expr, Aggregate))
                if is_aggregate_ref:
                    raise SQLSyntaxError("Aggregates are not allowed in ORDER BY of a query that is not grouped.", self.tokens[0].pos)


        # Check 3: Non-grouped plain ref not in GROUP BY (Only relevant if grouped)
        if is_grouped:
            group_by_texts = set(group_by_refs)
            for expr, _ in items_tuple:
                if isinstance(expr, Column):
                    # A plain column reference must match one of the group by keys
                    if expr.name not in group_by_texts:
                        raise SQLSyntaxError(f"Select item '{expr.name}' is not in GROUP BY clause.", self.tokens[0].pos)


        return Select(
            items=items_tuple,
            columns=output_keys if items[0] != '*' else None,
            table=from_table_name,
            join=join_clause,
            where=where_condition,
            group_by=group_by_refs,
            order_by=order_by_list,
            limit=limit
        )


    # --- Parsing Helpers ---

    def _parse_ref_list(self) -> int:
        """Parses a comma-separated list of references/columns."""
        count = 0
        if self.current_token().kind == 'IDENT' or self.current_token().kind == 'DOT':
            self._parse_reference()
            count = 1
            while self.current_token().kind == 'COMMA':
                self.advance()
                self._parse_reference()
                count += 1
        return count

    def _parse_reference(self) -> Column:
        """Parses a single reference (name or table.name)."""
        if self.current_token().kind == 'IDENT':
            name = self.eat('IDENT').value
            return Column(name)

        if self.current_token().kind == 'DOT':
            # This must be qualified: table.name
            self.advance() # Consume DOT
            table_name = self.eat('IDENT').value
            col_name = self.eat('IDENT').value
            return Column(f"{table_name}.{col_name}")

        raise SQLSyntaxError("Expected column name or qualified reference (table.name)", self.current_token().pos)


    def _parse_select_items(self) -> List[Tuple[Union[Column, Aggregate], str]]:
        """Parses select_list: * | item {, item}"""
        items = []

        token = self.current_token()
        if token.value == '*':
            self.advance()
            return [('*', '*')] # Special token for *

        while True:
            expr = self._parse_expr()

            # Check for AS clause
            alias = None
            if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'AS':
                self.advance()
                alias_token = self.eat('IDENT')
                alias = alias_token.value
            else:
                # Default key is the canonical text of the expression
                if isinstance(expr, Column):
                    alias = expr.name
                elif isinstance(expr, Aggregate):
                    alias = expr.canonical_text
                else:
                    # Should not happen
                    raise SQLSyntaxError("Invalid expression in select list", token.pos)

            items.append((expr, alias))

            if self.current_token().kind == 'COMMA':
                self.advance()
            else:
                break

        # Check for duplicate keys
        keys = set()
        for _, key in items:
            if key in keys:
                raise SQLSyntaxError(f"Duplicate output key '{key}' in select list.", self.tokens[0].pos)
            keys.add(key)

        return items


    def _parse_expr(self) -> Union[Column, Aggregate]:
        """Parses a single expression: ref | aggregate"""

        token = self.current_token()

        # 1. Aggregate
        if token.kind == 'KEYWORD' and token.value in ('COUNT', 'SUM', 'AVG', 'MIN', 'MAX'):
            func = self.eat('KEYWORD').value

            # Check for COUNT(*)
            if func == 'COUNT':
                self.eat('LPAREN')
                if self.current_token().value == '*':
                    self.advance()
                    self.eat('RPAREN')
                    return Aggregate(func, None)
                else:
                    # COUNT(ref)
                    arg_col = self._parse_reference()
                    self.eat('RPAREN')
                    return Aggregate(func, arg_col)

            # Other aggregates func(ref)
            func_token = self.eat('KEYWORD')
            self.eat('LPAREN')
            arg_col = self._parse_reference()
            self.eat('RPAREN')
            return Aggregate(func_token.value, arg_col)

        # 2. Reference
        return self._parse_reference()


    # --- Condition Parsing (Same precedence structure) ---

    def _parse_condition(self) -> Any:
        # Condition parsing remains largely the same, but operand now accepts refs
        return self._parse_or()

    def _parse_or(self) -> Any:
        left = self._parse_and()
        while self.current_token().kind == 'KEYWORD' and self.current_token().value == 'OR':
            op_token = self.advance() # Consume OR
            right = self._parse_and()
            left = Or(left, right)
        return left

    def _parse_and(self) -> Any:
        left = self._parse_not()
        while self.current_token().kind == 'KEYWORD' and self.current_token().value == 'AND':
            op_token = self.advance() # Consume AND
            right = self._parse_not()
            left = And(left, right)
        return left

    def _parse_not(self) -> Any:
        token = self.current_token()
        if token.kind == 'KEYWORD' and token.value == 'NOT':
            self.advance() # Consume NOT
            operand = self._parse_operand_or_is_null()
            return Not(operand)

        return self._parse_operand_or_is_null()

    def _parse_operand_or_is_null(self) -> Any:
        token = self.current_token()

        if token.kind in ('NUMBER', 'STRING', 'KEYWORD'):
            # Literals (including NULL, TRUE, FALSE)
            value = token.value
            self.advance()
            if token.kind == 'KEYWORD' and value == 'NULL':
                return Literal(None)
            return Literal(value)

        elif token.kind == 'LPAREN':
            # Parentheses grouping a condition
            self.advance() # Consume (
            condition = self._parse_condition()
            self.eat('RPAREN')
            return condition

        elif token.kind == 'IDENT' or token.kind == 'DOT':
            # Check for IS NULL check or simple reference
            temp_pos = self.pos

            # Parse potential operand (which could be a ref)
            operand = self._parse_reference()

            if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'IS':
                self.advance() # Consume IS

                is_token = self.current_token()
                if is_token.kind == 'KEYWORD' and is_token.value == 'NULL':
                    self.advance() # Consume NULL

                    negated = False
                    if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'NOT':
                        self.advance() # Consume NOT
                        negated = True

                    return IsNull(operand, negated)

            # If it wasn't IS NULL, we successfully parsed a reference
            return operand

        # Handle Binary Comparisons (Ref op Operand)
        if token.kind in ('IDENT', 'DOT'):
            temp_pos = self.pos

            # Parse LHS (Reference)
            lhs = self._parse_reference()

            if self.current_token().kind == 'OP':
                op = self.current_token().value
                self.advance() # Consume operator

                # RHS can be a literal, column, or parenthesis condition
                rhs = self._parse_operand_or_is_null() 
                return Compare(op, lhs, rhs)
            else:
                # Backtrack if it wasn't a comparison
                self.pos = temp_pos
                return lhs


        raise SQLSyntaxError(f"Expected operand (reference, literal, or '('), got {token.kind} ('{token.value}')", token.pos)


def parse(sql: str) -> Select:
    tokens = tokenize(sql)
    parser = Parser(tokens)
    return parser.parse()
