```python
from dataclasses import dataclass
from typing import Any, List, Dict, Tuple, Union, Iterator
import operator
import math

from minisql.parser import Select, Column, Literal, Compare, And, Or, Not, IsNull, Join, Aggregate
from minisql.tokens import SQLError, SQLSyntaxError

class SQLExecutionError(SQLError):
    """Raised during query execution due to data or logic issues."""
    pass

# --- Utility Functions ---

def get_value_type(value: Any) -> str:
    """Determines the type category of a value (str, num, bool, null)."""
    if value is None:
        return 'null'
    if isinstance(value, bool):
        return 'bool'
    if isinstance(value, (int, float)):
        return 'num'
    if isinstance(value, str):
        return 'str'
    raise SQLExecutionError(f"Unknown value type encountered: {type(value)}")

# --- Core Evaluation Logic (Comparison and Condition) ---

def evaluate_compare(left_val: Any, right_val: Any, op: str) -> Union[bool, None]:
    """Evaluates a binary comparison using three-valued logic."""
    type_l = get_value_type(left_val)
    type_r = get_value_type(right_val)

    # Rule 4: If either side is NULL, comparison is Unknown (None)
    if type_l == 'null' or type_r == 'null':
        return None

    # Rule 4: Values of different kinds
    if type_l != type_r:
        if op == '=': return False
        if op == '!=': return True
        # Rule 4: All other comparisons between different kinds raise error
        raise SQLExecutionError(f"Cannot compare values of different kinds ({type_l} vs {type_r}) using operator {op}")

    # Values of same kind (Rule 4)
    if type_l == 'num':
        if op == '=': return left_val == right_val
        if op == '!=': return left_val != right_val
        if op == '<': return left_val < right_val
        if op == '<=': return left_val <= right_val
        if op == '>': return left_val > right_val
        if op == '>=': return left_val >= right_val

    elif type_l == 'str':
        # Strings case-sensitive
        if op == '=': return str(left_val) == str(right_val)
        if op == '!=': return str(left_val) != str(right_val)
        # Relational operators raise error for strings
        raise SQLExecutionError("Relational operators (<, >, <=, >=) are not supported for string comparisons.")

    elif type_l == 'bool':
        # Python comparison rules apply
        if op == '=': return left_val == right_val
        if op == '!=': return left_val != right_val
        if op == '<': return left_val < right_val
        if op == '<=': return left_val <= right_val
        if op == '>': return left_val > right_val
        if op == '>=': return left_val >= right_val

def evaluate_condition(condition: Any, row_values: Dict[str, Any]) -> Union[bool, None]:
    """Recursively evaluates a condition AST node for a specific row."""

    if isinstance(condition, Literal):
        return condition.value

    elif isinstance(condition, Column):
        # Should only happen if the parser allowed a bare column in WHERE
        raise SQLExecutionError(f"Bare column {condition.name} provided as a condition.")

    elif isinstance(condition, Compare):
        left_val = row_values[condition.left.name] if isinstance(condition.left, Column) else condition.left.value
        right_val = row_values[condition.right.name] if isinstance(condition.right, Column) else condition.right.value
        return evaluate_compare(left_val, right_val, condition.op)

    elif isinstance(condition, IsNull):
        value = row_values[condition.operand.name] if isinstance(condition.operand, Column) else condition.operand.value
        is_null = value is None
        return not is_null if condition.negated else is_null

    elif isinstance(condition, Not):
        operand_result = evaluate_condition(condition.operand, row_values)
        if operand_result is None:
            return None
        return not operand_result

    elif isinstance(condition, And):
        left_result = evaluate_condition(condition.left, row_values)
        right_result = evaluate_condition(condition.right, row_values)

        if left_result is False or right_result is False: return False
        if left_result is None or right_result is None: return None
        return True

    elif isinstance(condition, Or):
        left_result = evaluate_condition(condition.left, row_values)
        right_result = evaluate_condition(condition.right, row_values)

        if left_result is True or right_result is True: return True
        if left_result is None or right_result is None: return None
        return False

    else:
        raise SQLExecutionError("Unknown condition AST node encountered.")

# --- Aggregation and Grouping Logic ---

def calculate_aggregate(agg: Aggregate, group_rows: List[Dict], all_table_columns: List[str]) -> Any:
    """Calculates a single aggregate over a group of rows."""

    if agg.func == 'COUNT':
        if agg.arg is None:
            # COUNT(*) counts all rows in the group
            return len(group_rows)
        else:
            # COUNT(ref) counts non-NULL values for that column
            count = 0
            col_name = agg.arg.name
            for row in group_rows:
                val = row.get(col_name)
                if val is not None:
                    count += 1
            return count

    # SUM, AVG, MIN, MAX require numerical or comparable types
    if not group_rows:
        return None

    if agg.func == 'SUM':
        values = []
        col_name = agg.arg.name if agg.arg else None

        for row in group_rows:
            if col_name:
                val = row.get(col_name)
                if val is not None and isinstance(val, (int, float)):
                    values.append(val)
            # Note: SUM() over NULL is NULL, but we skip NULLs here.

        if not values:
            return None

        total = sum(values)
        # Rule 5: Result is int if all were int, else float.
        if all(isinstance(v, int) for v in values):
            return int(total)
        return float(total)

    if agg.func == 'AVG':
        values = []
        col_name = agg.arg.name if agg.arg else None

        for row in group_rows:
            if col_name:
                val = row.get(col_name)
                if val is not None and isinstance(val, (int, float)):
                    values.append(val)

        if not values:
            return None

        # Rule 5: Always float
        return sum(values) / len(values)

    if agg.func == 'MIN':
        values = []
        col_name = agg.arg.name if agg.arg else None

        for row in group_rows:
            if col_name:
                val = row.get(col_name)
                if val is not None:
                    values.append(val)

        if not values:
            return None
        return min(values)

    if agg.func == 'MAX':
        values = []
        col_name = agg.arg.name if agg.arg else None

        for row in group_rows:
            if col_name:
                val = row.get(col_name)
                if val is not None:
                    values.append(val)

        if not values:
            return None
        return max(values)

# --- Join Logic ---

def perform_join(from_rows: List[Dict], join: Join, joined_table_rows: List[Dict]) -> List[Dict]:
    """Performs a cartesian product followed by INNER JOIN filtering."""

    a_table_name = from_rows[0].get('__source_table__', 'unknown')
    b_table_name = join.table

    joined_rows: List[Dict] = []

    # Iterate over A rows
    for row_a in from_rows:
        # Extract A data, removing internal metadata key
        data_a = {k: v for k, v in row_a.items() if not k.startswith('__')}

        # Iterate over B rows
        for row_b in joined_table_rows:
            # Extract B data, removing internal metadata key
            data_b = {k: v for k, v in row_b.items() if not k.startswith('__')}

            # Check join condition: a.p = b.q
            val_a = data_a[join.left.name]
            val_b = data_b[join.right.name]

            try:
                # Rule 2: Joining requires strict equality
                if val_a == val_b:
                    # Create the joined row dict with qualified keys
                    new_row = {}

                    # A columns (qualified)
                    for k, v in data_a.items():
                        new_row[f"{a_table_name}.{k}"] = v

                    # B columns (qualified)
                    for k, v in data_b.items():
                        new_row[f"{b_table_name}.{k}"] = v

                    joined_rows.append(new_row)
            except Exception:
                # Catch any comparison errors (e.g., different kinds) during join condition
                raise SQLExecutionError(f"Join condition failure: cannot compare values in {a_table_name}.{join.left.name} and {b_table_name}.{join.right.name}")

    return joined_rows

# --- Main Executor ---

def execute(stmt: Select, tables: Dict[str, List[Dict]]) -> List[Dict]:
    """Runs a parsed SQL statement over the in-memory tables."""

    # --- Step 1: Initialization & Table Retrieval ---

    if stmt.join is None:
        if stmt.table not in tables:
            raise SQLExecutionError(f"Unknown table '{stmt.table}'")

        data_rows = tables[stmt.table]
        # Tag rows with source table name for unqualified column resolution
        data_rows = [{**row, '__source_table__': stmt.table} for row in data_rows]
        joined_rows = data_rows
    else:
        # Handle JOIN
        from_table_name = stmt.table
        joined_table_name = stmt.join.table

        if from_table_name not in tables:
            raise SQLExecutionError(f"Unknown primary table '{from_table_name}'")
        if joined_table_name not in tables:
            raise SQLExecutionError(f"Unknown joined table '{joined_table_name}'")

        from_rows = [{**row, '__source_table__': from_table_name} for row in tables[from_table_name]]
        joined_table_rows = [{**row, '__source_table__': joined_table_name} for row in tables[joined_table_name]]

        # Perform Join
        joined_rows = perform_join(from_rows, stmt.join, joined_table_rows)

    # --- Step 2: WHERE Filtering (Rule 3) ---

    filtered_rows: List[Dict] = []
    if stmt.where is None:
        filtered_rows = joined_rows
    else:
        for row in joined_rows:
            # Row values map uses the qualified keys
            row_values = row
            try:
                condition_result = evaluate_condition(stmt.where, row_values)
            except SQLExecutionError as e:
                # Pass through comparison errors
                raise e

            if condition_result is True:
                filtered_rows.append(row)

    # --- Step 3: Grouping (Rule 4) ---

    grouped_rows: List[Dict] = []
    group_keys: Dict[Tuple, List[Dict]] = {} # Key: Tuple of group values, Value: List of rows in group

    if stmt.group_by:
        for row in filtered_rows:
            # Extract group by values
            group_values = []
            for gb_col in stmt.group_by:
                # Determine which table this column belongs to, if qualified
                if '.' in gb_col:
                    table_name, col_name = gb_col.split('.', 1)
                    row_values = {k: v for k, v in row.items() if k.startswith(f"{table_name}.") or k.startswith(f"{table_name}." if len(table_name)>1 else "")}
                    group_values.append(row.get(f"{table_name}.{col_name}"))
                else:
                    # Unqualified reference must come from the primary table (stmt.table)
                    # This is guaranteed by the parser if no join exists, or if the primary table is the source.
                    source_table = stmt.table
                    key = f"{source_table}.{gb_col}"
                    group_values.append(row.get(key))

            key = tuple(group_values)
            if key not in group_keys:
                group_keys[key] = []
            group_keys[key].append(row)

        # Output groups in order of first appearance
        for key in group_keys:
            grouped_rows.append(group_keys[key])
    else:
        # No grouping, all rows are in one group
        grouped_rows = [filtered_rows]

    # --- Step 4: Aggregation (Rule 5) ---

    aggregated_results: List[Dict] = []

    for group in grouped_rows:
        output_row = {}
        for item_expr, key in stmt.items:
            if isinstance(item_expr, Aggregate):
                try:
                    agg_result = calculate_aggregate(item_expr, group, []) # Table columns not strictly needed here
                    output_row[key] = agg_result
                except Exception as e:
                    raise SQLExecutionError(f"Aggregation error for {item_expr.canonical_text}: {e}")
            elif isinstance(item_expr, Column):
                # For non-aggregated columns, we take the value from the first row of the group
                # This is valid due to GROUP BY constraints.
                output_row[key] = group[0].get(item_expr.name) # Note: item_expr.name is canonical text

        aggregated_results.append(output_row)

    # If no groups were kept AND there was no GROUP BY, we still return one row (Rule 4)
    if not aggregated_results and not stmt.group_by and not filtered_rows:
        # Since there are no rows, we must still return one row with NULL/default values if SELECT * was used, 
        # but since we use explicit items, we return an empty list if the query is truly empty.
        # The rule states: "Without GROUP BY, all kept rows form one group, and the query returns exactly one row even when no row is kept."
        if not filtered_rows:
            empty_row = {}
            for _, key in stmt.items:
                 empty_row[key] = None
            return [empty_row]

    final_rows = aggregated_results if stmt.group_by else filtered_rows


    # --- Step 5: Ordering (Rule 6) ---

    def get_sort_value(row: Dict[str, Any], text: str, is_grouped: bool) -> Tuple[Any, str]:
        """Retrieves the sort value and its type category."""

        # Check if the sort text matches an output alias/canonical text
        alias_map = {key: expr for expr, key in stmt.items}
        if text in alias_map:
            expr = alias_map[text]
            if isinstance(expr, Aggregate):
                # If it's an aggregate, the value is the aggregate result itself (pre-calculated in final_rows)
                value = row.get(text)
                type_cat = get_value_type(value) if value is not None else 'null'
                return value, type_cat
            elif isinstance(expr, Column):
                 # Plain column reference: value is the row value
                value = row.get(expr.name) # name holds the canonical text
                type_cat = get_value_type(value) if value is not None else 'null'
                return value, type_cat

        # Fallback: Treat as a direct column reference (only applicable if NOT grouped)
        if not is_grouped:
            # We must find which column this refers to (qualified or unqualified)

            # Check for qualified references: T.name
            for key, val in row.items():
                if key.endswith(f".{text}"):
                    # We found the column
                    value = val
                    type_cat = get_value_type(value) if value is not None else 'null'
                    return value, type_cat

            # Check for unqualified references (must match the primary table)
            primary_table = stmt.table
            unqualified_key = f"{primary_table}.{text}"
            value = row.get(unqualified_key)
            type_cat = get_value_type(value) if value is not None else 'null'
            return value, type_cat

        # If not found by alias or column lookup, it's an error in a grouped query
        raise SQLExecutionError(f"Ordering column '{text}' does not match any select alias or column in the grouped result set.")


    def sort_comparator(row: Dict[str, Any]):
        """Generates a list of sort keys for a row."""
        keys = []
        for text, descending in stmt.order_by:
            value, type_cat = get_sort_value(row, text, bool(stmt.group_by))

            # Null sorting logic (Rule 7)
            if value is None:
                if descending:
                    keys.append((math.inf, 'null')) # Sort after values in DESC
                else:
                    keys.append((math.nan, 'null')) # Sort before values in ASC (using NaN representation for stability/sort behavior)
                continue

            # Standard sorting based on type
            if type_cat == 'num':
                keys.append((float(value), 'num'))
            elif type_cat == 'str':
                keys.append((str(value), 'str'))
            elif type_cat == 'bool':
                # False < True
                keys.append((value, 'bool'))
            else:
                keys.append((value, 'unknown'))
        return keys

    try:
        is_grouped = bool(stmt.group_by)
        final_rows.sort(key=sort_comparator, reverse=any(desc for _, desc in stmt.order_by))
    except SQLExecutionError as e:
        # Propagate explicit errors
        raise e
    except Exception as e:
        # Catch comparison/type errors during sorting
        raise SQLExecutionError(f"Data kind mismatch detected during ordering: {e}")


    # --- Step 6: LIMIT & Output Formatting (Rule 8 & 9) ---

    if stmt.limit is not None:
        final_rows = final_rows[:stmt.limit]

    result_rows = []

    if stmt.items[0][0] == '*':
        # SELECT * returns copies of the internal, qualified rows
        for row in final_rows:
            # Flatten and clean up qualified keys for final output
            cleaned_row = {}
            for k, v in row.items():
                # Keep only the qualified keys
                cleaned_row[k] = v
            result_rows.append(cleaned_row)
    else:
        # Select specific items - map the final rows to output keys
        for row in final_rows:
            new_row = {}
            for _, key in stmt.items:
                # Key is the alias or canonical text
                new_row[key] = row.get(key)
            result_rows.append(new_row)

    return result_rows

def query(sql: str, tables: Dict[str, List[Dict]]) -> List[Dict]:
    """Public entry point: parses SQL and executes the query."""
    try:
        stmt = parse(sql)
        return execute(stmt, tables)
    except SQLExecutionError as e:
        raise e
    except Exception as e:
        if isinstance(e, SQLError):
            raise e
        # Re-raise unexpected errors as execution errors
        raise SQLExecutionError(f"Internal query error: {type(e).__name__}: {e}")
