import json
import re
from dataclasses import dataclass, field
from typing import Any, Dict, Tuple, List

# --- Errors ---

class HTTPError(Exception):
    """Base class for HTTP errors."""
    status: int
    reason: str

    def __init__(self, status: int, reason: str):
        self.status = status
        self.reason = reason
        super().__init__(f"HTTP {status}: {reason}")

class BadRequest(HTTPError):
    """HTTP 400 Bad Request."""
    status = 400
    reason = "Bad Request"

    def __init__(self, message: str = None):
        if message:
            super().__init__(400, f"Bad Request: {message}")
        else:
            super().__init__(400, "Bad Request")

# --- Utility Functions ---

REASON_PHRASES = {
    200: "OK", 201: "Created", 204: "No Content",
    400: "Bad Request", 401: "Unauthorized", 404: "Not Found",
    405: "Method Not Allowed", 500: "Internal Server Error"
}

def get_reason_phrase(status: int) -> str:
    """Returns the standard reason phrase or 'Unknown'."""
    return REASON_PHRASES.get(status, "Unknown")

def percent_decode_string(s: str) -> str:
    """Decodes URL percent-encoding, handling '+' as space."""
    decoded = []
    i = 0
    while i < len(s):
        char = s[i]
        if char == '+':
            decoded.append(' ')
            i += 1
        elif char == '%':
            i += 1
            if i + 1 >= len(s):
                raise BadRequest("Invalid percent encoding sequence.")
            hex_pair = s[i:i+2]
            try:
                decoded.append(chr(int(hex_pair, 16)))
                i += 2
            except ValueError:
                raise BadRequest(f"Invalid hex sequence: {hex_pair}")
        else:
            decoded.append(char)
            i += 1
    return "".join(decoded)

def percent_decode_bytes(data: bytes) -> bytes:
    """Decodes bytes from percent-encoding rules."""
    decoded = bytearray()
    i = 0
    while i < len(data):
        byte = data[i]
        if byte == ord('%'):
            i += 1
            if i + 1 >= len(data):
                raise BadRequest("Invalid percent encoding sequence.")
            hex_pair = data[i:i+2]
            try:
                byte_val = int.from_bytes(hex_pair, 'big')
                decoded.append(byte_val)
                i += 2
            except ValueError:
                raise BadRequest("Invalid hex sequence in percent encoding.")
        else:
            decoded.append(byte)
            i += 1
    return bytes(decoded)

# --- Headers ---

class Headers:
    """Ordered, case-insensitive multi-map of header fields."""
    def __init__(self, pairs: Tuple[Tuple[str, str], ...] = ()):
        # Stores (name, value) pairs in order. Names are case-sensitive internally.
        self._fields: List[Tuple[str, str]] = list(pairs)

    def _find_index_by_name(self, name: str) -> int:
        """Finds the index of the first field matching the name (case-insensitive)."""
        for i, (n, _) in enumerate(self._fields):
            if n.lower() == name.lower():
                return i
        return -1

    def add(self, name: str, value: str):
        """Appends a field."""
        self._fields.append((name, value))

    def set(self, name: str, value: str):
        """Replaces every field with that name by a single one."""
        idx = self._find_index_by_name(name)
        if idx != -1:
            # Replace the existing field
            self._fields[idx] = (name, value)
        else:
            # Append it if it doesn't exist
            self._fields.append((name, value))

    def get(self, name: str, default: Any = None) -> Any:
        """Returns the first value for the given name (case-insensitive)."""
        idx = self._find_index_by_name(name)
        return self._fields[idx][1] if idx != -1 else default

    def h(self, name: str) -> str:
        """Raises KeyError if no field matches."""
        idx = self._find_index_by_name(name)
        if idx == -1:
            raise KeyError(name)
        return self._fields[idx][1]

    def get_all(self, name: str) -> List[str]:
        """Returns every value for the given name in order."""
        return [
            value for name_orig, value in self._fields
            if name_orig.lower() == name.lower()
        ]

    def __contains__(self, name: str) -> bool:
        return self._find_index_by_name(name) != -1

    def __len__(self) -> int:
        return len(self._fields)

    def items(self) -> List[Tuple[str, str]]:
        """Returns the list of (name, value) pairs in order."""
        return self._fields

# --- Request ---

@dataclass
class Request:
    method: str
    target: str
    path: str
    query_string: str
    version: str
    headers: Headers
    body: bytes
    params: Dict[str, Any] = field(default_factory=dict)
    state: Dict[str, Any] = field(default_factory=dict)

    @property
    def query(self) -> Dict[str, List[str]]:
        """
        The query string split into name: [values].
        """
        if not self.query_string:
            return {}

        query_dict = {}

        # Split by '&', skipping empty pieces
        for piece in filter(None, self.query_string.split('&')):
            parts = piece.split('=', 1)
            name = parts[0]
            value = parts[1] if len(parts) == 2 else ''

            try:
                # Decode using rules: + -> space, %XX decoding, UTF-8 validation
                decoded_name = percent_decode_string(name)
                decoded_value = percent_decode_string(value)
            except BadRequest as e:
                # Re-raise specific parsing error
                raise BadRequest(str(e))

            if decoded_name not in query_dict:
                query_dict[decoded_name] = []
            query_dict[decoded_name].append(decoded_value)

        return query_dict

    @property
    def content_type(self) -> Tuple[str, Dict[str, str]]:
        """
        Parses Content-Type header into (media_type, params).
        """
        ct_header = self.headers.get('Content-Type', '')
        if not ct_header:
            return ('', {})

        parts = ct_header.split(';')
        media_type = parts[0].strip().lower()
        params: Dict[str, str] = {}

        for part in parts[1:]:
            part = part.strip()
            if '=' in part:
                try:
                    name, value = part.split('=', 1)
                    name = name.strip().lower()
                    value = value.strip()

                    # Strip surrounding quotes
                    if value.startswith('"') and value.endswith('"'):
                        value = value[1:-1]

                    # First occurrence wins
                    if name not in params:
                        params[name] = value
                except ValueError:
                    # Skip invalid formats
                    pass
        return (media_type, params)

    def text(self) -> str:
        """Decodes the body using Content-Type charset, or UTF-8."""
        media_type, params = self.content_type
        charset = params.get('charset', 'utf-8')

        try:
            return self.body.decode(charset)
        except UnicodeDecodeError:
            raise BadRequest(f"Body encoding error using {charset}")

    def json(self) -> Any:
        """Parses body as JSON."""
        try:
            text_body = self.text()
            return json.loads(text_body)
        except UnicodeDecodeError:
            raise BadRequest("Body could not be decoded for JSON parsing.")
        except json.JSONDecodeError:
            raise BadRequest("Body is not valid JSON.")

# --- Response ---

@dataclass
class Response:
    status: int = 200
    headers: Headers = field(default_factory=lambda: Headers())
    body: bytes = b''

    @classmethod
    def text(cls, s: str, status: int = 200):
        """Class method to create a text response."""
        resp = cls(status=status)
        resp.headers.add('Content-Type', 'text/plain; charset=utf-8')
        resp.body = s.encode('utf-8')
        return resp

    @classmethod
    def json(cls, obj: Any, status: int = 200):
        """Class method to create a JSON response."""
        resp = cls(status=status)
        # Compact JSON serialization
        json_body = json.dumps(obj, separators=(',', ':'), sort_keys=True)
        resp.headers.add('Content-Type', 'application/json')
        resp.body = json_body.encode('utf-8')
        return resp

    def to_bytes(self) -> bytes:
        """Serializes the response into raw HTTP/1.1 bytes."""

        status_line = f"HTTP/1.1 {self.status} {get_reason_phrase(self.status)}\r\n"

        header_lines = []
        for name, value in self.headers.items():
            # Drop Content-Length if present, it will be set last
            if name.lower() == 'content-length':
                continue
            header_lines.append(f"{name}: {value}\r\n")

        # Add Content-Length last
        cl_line = f"Content-Length: {len(self.body)}\r\n"

        headers = "".join(header_lines) + cl_line

        # CRLF separator and body
        response_bytes = (status_line + headers + "\r\n" + self.body).encode('ascii')
        return response_bytes

# --- Parsing Logic ---

def parse_request(data: bytes) -> Request:
    """
    Parses exactly one request from raw bytes.
    """
    try:
        # 1. Separate head and body
        if b'\r\n\r\n' not in data:
            raise BadRequest("Missing HTTP headers separator.")

        head_bytes, body = data.split(b'\r\n\r\n', 1)
        head_str = head_bytes.decode('iso-8859-1')

        head_lines = head_str.split('\r\n')

        if not head_lines or not head_lines[0]:
            raise BadRequest("Request head is empty.")

        # 2. Parse Request Line
        request_line = head_lines[0]
        parts = request_line.split()
        if len(parts) != 3:
            raise BadRequest("Invalid request line format.")

        method, target, version = parts

        if method not in [c for c in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'] or not re.fullmatch(r'[A-Z]+', method):
             raise BadRequest("Invalid HTTP method.")

        if not target.startswith('/'):
            raise BadRequest("Target must start with /.")

        if version not in ("HTTP/1.1", "HTTP/1.0"):
            raise BadRequest("Unsupported HTTP version.")

        # 3. Parse Headers
        headers = Headers()
        content_length = None
        transfer_encoding = None

        header_lines_raw = head_lines[1:]

        for line in header_lines_raw:
            if not line:
                continue

            # Check for obsolete line folding
            if line.startswith(' ') or line.startswith('\t'):
                raise BadRequest("Obsolete line folding detected.")

            if ':' not in line:
                # Should not happen if we filter out empty lines
                continue

            try:
                name, value = line.split(':', 1)
                name = name.strip()
                value = value.strip()
                headers.add(name, value)

                if name.lower() == 'content-length':
                    content_length = value
                elif name.lower() == 'transfer-Encoding':
                    transfer_encoding = value.lower()
            except ValueError:
                raise BadRequest(f"Malformed header line: {line}")

        # 4. Determine Body Size and Validate
        body_size = 0

        if transfer_encoding:
            if transfer_encoding != 'chunked':
                raise BadRequest(f"Unsupported Transfer-Encoding: {transfer_encoding}")

            # Chunked encoding parsing
            body_chunks = b''
            cursor = 0

            while cursor < len(body):
                # Find size line (hex string up to \r\n)
                size_line_end = body.find(b'\r\n', cursor)
                if size_line_end == -1:
                    raise BadRequest("Malformed chunked body (missing size line terminator).")
                size_line = body[cursor:size_line_end]

                try:
                    # Size is a hex number, possibly followed by metadata (ignored)
                    size_hex = size_line.decode('ascii').strip()
                    size = int(size_hex, 16)
                except ValueError:
                    raise BadRequest(f"Malformed chunk size line: {size_line_end}")

                cursor = size_line_end + 2 # Move past \r\n

                if size == 0:
                    # End of chunks
                    # Optionally handle trailers here, but specs say they are ignored
                    cursor = body.find(b'\r\n\r\n', cursor) + 2 if body.find(b'\r\n\r\n', cursor) != -1 else len(body)
                    break

                # Read chunk data
                chunk_start = cursor
                chunk_end = cursor + size
                if chunk_end > len(body):
                    raise BadRequest("Malformed chunked body (incomplete chunk).")
                chunk_data = body[chunk_start:chunk_end]
                body_chunks += chunk_data
                cursor = chunk_end

                # Move past chunk terminator \r\n
                cursor += 2

            body = body_chunks
            body_size = len(body)

        elif content_length:
            try:
                body_size = int(content_length)
                if len(body) != body_size:
                    raise BadRequest(f"Content-Length mismatch. Expected {body_size} bytes, got {len(body)}.")
            except ValueError:
                raise BadRequest("Invalid Content-Length format.")
        else:
            # No body expected, body must be empty
            if len(body) > 0:
                raise BadRequest("Unexpected body data when no Content-Length or Transfer-Encoding is present.")

        # 5. Final Checks

        # Host header required for HTTP/1.1
        if version == "HTTP/1.1" and 'Host' not in headers:
            raise BadRequest("HTTP/1.1 requests must include a Host header.")

    except (KeyError, ValueError) as e:
        # Catch internal parsing errors that should result in a BadRequest
        raise BadRequest(f"Internal parsing error: {e}")
    except Exception as e:
        # Catch unexpected errors during parsing
        raise BadRequest(f"Unexpected parsing error: {e}")

    # 6. Construct Request object

    # Target contains the full path including the query string (if present)
    if '?' in target:
        path, query_string = target.split('?', 1)
    else:
        path = target
        query_string = ''

    return Request(
        method=method,
        target=target,
        path=path,
        query_string=query_string,
        version=version,
        headers=headers,
        body=body
    )
