from typing import Callable, List, Tuple, Dict, Any
from .request import Request, Response, HTTPError, BadRequest

# Type hint for handler: accepts Request, returns Response
Handler = Callable[[Request], Response]

class NotFound(HTTPError):
    """HTTP 404 Not Found."""
    status = 404
    reason = "Not Found"

class MethodNotAllowed(HTTPError):
    """HTTP 405 Method Not Allowed."""
    status = 405
    reason = "Method Not Allowed"
    allowed: List[str]

    def __init__(self, allowed: List[str]):
        self.allowed = sorted(allowed)
        super().__init__(405, "Method Not Allowed")

class Router:
    """Handles pattern matching and dispatching requests."""

    def __init__(self):
        # Stores: {method: [ (pattern_regex, pattern_segments, handler) ]}
        self._routes: Dict[str, List[Tuple[str, List[str], Handler]]] = {}

    def _validate_pattern(self, pattern: str):
        """Validates the structure of a route pattern string."""
        if not pattern.startswith('/'):
            raise ValueError("Pattern must start with '/'")

        segments = pattern.split('/')
        # Drop the leading empty segment
        segments = segments[1:]

        param_names = set()

        for segment in segments:
            if not segment:
                # Empty segment means trailing slash, which is fine if not the last one
                continue

            if segment.startswith('{') and segment.endswith('}'):
                content = segment[1:-1]

                if ':' not in content:
                    raise ValueError(f"Unknown converter in segment: {segment}")

                name, converter_str = content.split(':', 1)

                if name in param_names:
                    raise ValueError(f"Repeated parameter name: {name}")
                param_names.add(name)

                converter = converter_str

                if converter == 'int':
                    # Simple check for integer converter
                    pass
                elif converter == 'path':
                    # Path converter must be the last segment
                    if segments.index(segment) != len(segments) - 1:
                         raise ValueError("Path converter must be the last segment.")
                else:
                    raise ValueError(f"Unknown converter: {converter}")
            elif segment.startswith('/'):
                # Should have been split earlier
                raise ValueError("Invalid segment structure.")

        return segments, param_names

    def add(self, method: str, pattern: str, handler: Handler):
        """Registers a handler for a specific method and pattern."""

        segments, _ = self._validate_pattern(pattern)
        method = method.upper()

        if method not in self._routes:
            self._routes[method] = []

        # Check for exact duplicate registration
        for existing_pattern, _, _ in self._routes[method]:
            if existing_pattern == pattern:
                raise ValueError(f"Route already registered for {method} at {pattern}")

        self._routes[method].append((pattern, segments, handler))

    @staticmethod
    def route(pattern: str, methods: Tuple[str, ...] = ('GET',)):
        """Decorator to register a handler."""
        def decorator(handler: Handler):
            # We use a dummy router instance here as the actual registration
            # happens later when the App is created, but for the decorator
            # to work, we need a way to capture the registration.
            # Since the API implies this is used inside a context where the router
            # exists, we will assume the caller manually registers the handler
            # or we adapt the usage to expect the router instance.
            # Given the prompt constraints, we'll assume the caller uses a helper
            # or we register it lazily (which is messy). 
            # Best approach: Assume the caller uses `router.add(m, p, h)` directly.
            # If we must support the decorator, we need the Router instance passed in.
            raise NotImplementedError("Use router.add(method, pattern, handler) directly.")
        return decorator

    def _match_path(self, path: str, segments: List[str]) -> Tuple[Dict[str, Any], bool]:
        """
        Matches a request path against a pattern's segments.

        Returns: (params, success)
        """
        path_segments = path.split('/')

        params = {}

        if len(path_segments) != len(segments):
            return {}, False

        for i, pattern_segment in enumerate(segments):
            path_segment = path_segments[i]

            if not pattern_segment.startswith('{'):
                # Literal match
                if path_segment != pattern_segment:
                    return {}, False
            else:
                # Parameter match
                content = pattern_segment[1:-1]

                if ':' not in content:
                    raise ValueError("Invalid parameter format.")

                name, converter_str = content.split(':', 1)

                if converter_str == 'int':
                    try:
                        value = int(path_segment)
                    except ValueError:
                        return {}, False
                    params[name] = value
                elif converter_str == 'path':
                    # Path converter must match the remainder of the path
                    # Since we are segment-matching, this converter should only
                    # appear as the final segment, matching the entire remainder.

                    # If path_segment is not empty, it matches the remaining path.
                    # Since we split the request path, the segment here is the last one.
                    params[name] = path_segment
                else:
                    raise ValueError("Unknown converter.")

                else:
                    return {}, False

        return params, True


    def resolve(self, method: str, path: str) -> Tuple[Handler, Dict[str, Any]]:
        """
        Finds the matching handler and extracts parameters.
        """
        method = method.upper()

        # 1. Check specific method routes
        routes = self._routes.get(method, [])

        # 2. Collect all allowed methods from matching patterns (including HEAD support)
        potential_matches = []

        for pattern, segments, handler in self._routes.get(method, []):
            params, matched = self._match_path(path, segments)
            if matched:
                potential_matches.append((handler, params))

        if potential_matches:
            # First match wins
            return potential_matches[0]

        # 3. Handle HEAD fallback
        if method == 'HEAD' and self._routes.get('GET'):
            # Try GET routes for HEAD
            for pattern, segments, handler in self._routes.get('GET', []):
                params, matched = self._match_path(path, segments)
                if matched:
                    # HEAD request served by GET handler
                    return handler, params

        # 4. Handle Not Found
        if not potential_matches and method == 'HEAD' and not self._routes.get('GET'):
            raise NotFound(404, "Not Found")

        # 5. Handle Method Not Allowed (if paths matched but not for this method)

        # Identify all unique patterns that match the path, regardless of method
        all_matching_patterns = {} # {pattern_string: list_of_methods}

        for m, routes_list in self._routes.items():
            if m == method:
                continue # Already checked specific method matches

            for pattern, segments, _ in routes_list:
                params, matched = self._match_path(path, segments)
                if matched:
                    if pattern not in all_matching_patterns:
                        all_matching_patterns[pattern] = set()
                    all_matching_patterns[pattern].add(m)

        # Collect all allowed methods from all matching patterns
        allowed_methods = set()
        for methods_set in all_matching_patterns.values():
            allowed_methods.update(methods_set)

        if allowed_methods:
            raise MethodNotAllowed(list(allowed_methods))

        # Fallback to Not Found if no pattern matched at all
        raise NotFound(404, "Not Found")

    def dispatch(self, request: Request) -> Response:
        """
        Resolves, sets parameters, calls handler, and returns Response.
        """
        handler, params = self.resolve(request.method, request.path)

        # Store parameters
        request.params = params

        # Call handler
        return handler(request)
