```python
import base64
from typing import Callable, List, Any, Dict
from .request import Request, Response, BadRequest, HTTPError, MethodNotAllowed

# Middleware type: mw(request, call_next) -> Response
Middleware = Callable[[Request, Callable[[Request], Response]], Response]

class App:
    """Application container managing router and middleware."""
    def __init__(self, router: 'Router', middleware: List[Middleware] = None):
        self.router = router
        self.middleware = middleware if middleware is not None else []

    def use(self, mw: Middleware):
        """Appends a middleware to the chain."""
        self.middleware.append(mw)

    def _error_response(self, error: HTTPError) -> Response:
        """Converts an HTTPError into a standardized error Response."""
        resp = Response(status=error.status)

        if isinstance(error, MethodNotAllowed):
            # Special handling for 405
            resp.headers.add('Allow', ", ".join(error.allowed))

        # Body contains status and reason phrase
        body_text = f"{error.status} {error.reason}"
        resp.body = body_text.encode('utf-8')
        resp.headers.add('Content-Type', 'text/plain; charset=utf-8')
        return resp

    def _internal_error_response(self, e: Exception) -> Response:
        """Converts any other exception into a 500 error Response."""
        # Log the internal exception if necessary, but for this scope, just respond.
        resp = Response(status=500)
        resp.body = f"500 Internal Server Error".encode('utf-8')
        resp.headers.add('Content-Type', 'text/plain; charset=utf-8')
        return resp

    def _handle_call_next(self, request: Request, chain: List[Middleware]) -> Response:
        """
        The recursive handler that executes the middleware chain.
        The router dispatch is the innermost step.
        """
        # Base case: hit the router (the last element in the chain is the router's dispatch)
        if not chain:
            return self.router.dispatch(request)

        # Recursive step: call the next middleware
        current_mw = chain.pop()

        def call_next(req: Request) -> Response:
            return self._handle_call_next(req, chain)

        try:
            return current_mw(request, call_next)
        except Exception as e:
            # Catch exceptions raised by the middleware itself
            return self._internal_error_response(e)


    def handle(self, request: Request) -> Response:
        """
        Executes the full middleware chain, handling exceptions.
        """

        # The chain is run outermost to innermost.
        # We wrap the middleware list with the router's dispatch logic.
        chain = list(self.middleware)

        # Wrapper to catch HTTP errors generated by middleware or router
        def error_catching_call_next(req: Request) -> Response:
            try:
                return self._handle_call_next(req, chain)
            except HTTPError as e:
                return self._error_response(e)
            except Exception as e:
                # This should ideally be caught inside _handle_call_next, 
                # but we keep this as a final safeguard.
                return self._internal_error_response(e)

        return self._handle_call_next(request, [error_catching_call_next])

    def handle_bytes(self, data: bytes) -> bytes:
        """Parses raw bytes, handles the request, and returns raw response bytes."""
        try:
            request = self.router.parse_request(data) # Note: router needs parse_request
        except BadRequest as e:
            # BadRequest from parsing bypasses middleware entirely
            return self._error_response(BadRequest(e.reason)).to_bytes()

        response = self.handle(request)
        return response.to_bytes()

# --- Middleware Factories ---

def logger(lines: List[str]):
    """Middleware that logs the request details after the response is generated."""
    def mw(request: Request, call_next: Callable[[Request], Response]) -> Response:
        response = call_next(request)

        # Log the result
        log_line = f"{request.method} {request.path} {response.status}"
        lines.append(log_line)

        return response
    return mw

def cookies():
    """Middleware to parse the Cookie header into request.state['cookies']."""
    def mw(request: Request, call_next: Callable[[Request], Response]) -> Response:
        cookie_header = request.headers.get('Cookie', '')
        cookies_dict: Dict[str, str] = {}

        if cookie_header:
            # Treat pieces exactly like Content-Type parameters, but keep name case
            parts = cookie_header.split(';')
            for part in parts:
                part = part.strip()
                if '=' in part:
                    try:
                        name, value = part.split('=', 1)
                        name = name.strip() # Keep case
                        value = value.strip()

                        # Strip quotes
                        if value.startswith('"') and value.endswith('"'):
                            value = value[1:-1]

                        if name not in cookies_dict:
                            cookies_dict[name] = value
                    except ValueError:
                        pass

        request.state['cookies'] = cookies_dict
        return call_next(request)
    return mw

def basic_auth(users: Dict[str, str], realm: str = 'app'):
    """
    Middleware for Basic Authentication.
    Requires Authorization: Basic Base64(user:password).
    """
    def mw(request: Request, call_next: Callable[[Request], Response]) -> Response:
        auth_header = request.headers.get('Authorization')

        if not auth_header or not auth_header.lower().startswith('basic '):
            return call_next(request) # No auth header, proceed

        auth_string = auth_header[6:].strip()

        try:
            decoded_bytes = base64.b64decode(auth_string)
            decoded_credentials = decoded_bytes.decode('utf-8')
        except Exception:
            # Malformed base64
            error_response = Response(401)
            error_response.headers.add('WWW-Authenticate', f'Basic realm="{realm}"')
            return error_response

        if ':' not in decoded_credentials:
            # Invalid format user:pass
            error_response = Response(401)
            error_response.headers.add('WWW-Authenticate', f'Basic realm="{realm}"')
            return error_response

        username, password = decoded_credentials.split(':', 1)

        if username in users and users[username] == password:
            request.state['user'] = username
            return call_next(request) # Success, proceed
        else:
            # Failure
            error_response = Response(401)
            error_response.headers.add('WWW-Authenticate', f'Basic realm="{realm}"')
            return error_response
    return mw
