```python
import re
from typing import Any, Dict, List, Set, Tuple, Union

class FormulaError(ValueError):
    """Raised when a formula is syntactically incorrect or refers to invalid data."""
    pass

class ErrorValue(str):
    """Represents a calculation error in a cell."""
    pass

ERROR_GENERIC = ErrorValue("#ERROR!")
ERROR_CYCLE = ErrorValue("#CYCLE!")

# --- AST Node Definitions ---
class FormulaNode:
    """Base class for AST nodes."""
    pass

class Number(FormulaNode):
    def __init__(self, value: Union[int, float]):
        self.value = value
    def __repr__(self):
        return f"Number({self.value})"

class Ref(FormulaNode):
    def __init__(self, name: str):
        self.name = name.upper()
    def __repr__(self):
        return f"Ref({self.name})"

class UnaryOp(FormulaNode):
    def __init__(self, op: str, operand: FormulaNode):
        self.op = op
        self.operand = operand
    def __repr__(self):
        return f"UnaryOp('{self.op}', {self.operand})"

class BinaryOp(FormulaNode):
    def __init__(self, op: str, left: FormulaNode, right: FormulaNode):
        self.op = op
        self.left = left
        self.right = right
    def __repr__(self):
        return f"BinaryOp('{self.op}', {self.left}, {self.right})"


# --- Parsing Logic ---

# Regex components for tokenization
# Note: We use a permissive regex and handle whitespace during parsing.
TOKEN_DIGIT = r"\d+"
TOKEN_DOT = r"\."
TOKEN_LETTER = r"[A-Za-z]"
TOKEN_NUMBER_PART = fr"(?:{TOKEN_DIGIT}(?:\.{TOKEN_DIGIT})?)"
TOKEN_REF = fr"(?:{TOKEN_LETTER}{TOKEN_DIGIT}+)" # letters followed by digits

# Grammar structure:
# expr   := term {(+ | -) term}
# term   := unary {(* | /) unary}
# unary  := (+ | -) unary | number | ref | ( expr )

def _tokenize(source: str) -> List[str]:
    """Splits the formula source into meaningful tokens, allowing for whitespace."""
    # Insert spaces around operators and parentheses to facilitate splitting
    source = source.replace('(', ' ( ')
    source = source.replace(')', ' ) ')
    source = source.replace('+', ' + ')
    source = source.replace('-', ' - ')
    source = source.replace('*', ' * ')
    source = source.replace('/', ' / ')
    return [t for t in source.split() if t]

class Parser:
    """
    Parser implementation using recursive descent for the given grammar.
    Handles tokenization and AST construction.
    """
    def __init__(self, tokens: List[str]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Union[str, None]:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self) -> Union[str, None]:
        if self.pos < len(self.tokens):
            token = self.tokens[self.pos]
            self.pos += 1
            return token
        return None

    def expect(self, expected_token: str):
        token = self.advance()
        if token != expected_token:
            raise FormulaError(f"Expected '{expected_token}', got '{token}'")

    def parse(self) -> FormulaNode:
        """Entry point: parse expression."""
        return self._parse_expr()

    # expr   := term {(+ | -) term}
    def _parse_expr(self) -> FormulaNode:
        left = self._parse_term()

        while self.current_token() in ('+', '-'):
            op = self.advance()
            right = self._parse_term()
            left = BinaryOp(op, left, right)

        return left

    # term   := unary {(* | /) unary}
    def _parse_term(self) -> FormulaNode:
        left = self._parse_unary()

        while self.current_token() in ('*', '/'):
            op = self.advance()
            right = self._parse_unary()
            left = BinaryOp(op, left, right)

        return left

    # unary  := (+ | -) unary | number | ref | ( expr )
    def _parse_unary(self) -> FormulaNode:
        token = self.current_token()

        if token in ('+', '-'):
            op = self.advance()
            # Unary sign binds tighter than binary operators
            return UnaryOp(op, self._parse_unary())

        elif token is None:
             raise FormulaError("Unexpected end of input.")

        elif token in ('(', ):
            self.advance() # Consume '('
            expr = self._parse_expr()
            self.expect(')')
            return expr

        elif token.isdigit():
            # This handles numbers
            return self._parse_number()

        elif re.match(r"^[A-Za-z]", token):
            # This handles references (must start with a letter)
            return self._parse_ref()

        else:
            raise FormulaError(f"Unexpected token: '{token}'")

    def _parse_number(self) -> Number:
        token = self.advance()

        if '.' in token:
            try:
                value = float(token)
            except ValueError:
                raise FormulaError(f"Invalid float format: {token}")
        else:
            try:
                value = int(token)
            except ValueError:
                # Should not happen if regex/tokenization is correct
                raise FormulaError(f"Invalid integer format: {token}")

        return Number(value)

    def _parse_ref(self) -> Ref:
        # Ref pattern: letters followed by digits (A1, Z999)
        token = self.advance()
        if not re.match(r"^[A-Za-z]\d+$", token):
            raise FormulaError(f"Invalid reference format: {token}")

        # Sheet validation (done in sheet.py, but we ensure structural validity here)
        return Ref(token)


def parse_formula(source: str) -> FormulaNode:
    """
    Parses a formula string (after '=') into an AST.
    Raises FormulaError if parsing fails.
    """
    if not source.strip():
        raise FormulaError("Formula body cannot be empty.")

    tokens = _tokenize(source)
    if not tokens:
        raise FormulaError("Formula body cannot be empty.")

    parser = Parser(tokens)
    return parser.parse()


# --- Dependency Analysis ---

def references(tree: FormulaNode) -> Set[str]:
    """
    Recursively finds all cell references in the AST and returns them as an
    upper-case set of strings.
    """
    names = set()

    if isinstance(tree, Ref):
        names.add(tree.name)
    elif isinstance(tree, BinaryOp):
        names.update(references(tree.left))
        names.update(references(tree.right))
    elif isinstance(tree, UnaryOp):
        names.update(references(tree.operand))
    # Number nodes contribute no references

    return names

# --- Evaluation Logic ---

def evaluate(tree: FormulaNode, lookup: callable) -> Union[int, float, str, ErrorValue]:
    """
    Computes the value of the formula AST using the provided lookup function.
    lookup(name: str) -> value (int, float, str, None, or ErrorValue)
    """

    def _evaluate_node(node: FormulaNode) -> Union[int, float, str, ErrorValue]:

        if isinstance(node, Number):
            return node.value

        elif isinstance(node, Ref):
            name = node.name
            cell_value = lookup(name)

            if cell_value is None:
                # Rule 2: Empty cell gives 0
                return 0
            elif isinstance(cell_value, str) and cell_value.startswith("#"):
                # Propagate error values
                return cell_value
            elif isinstance(cell_value, str) and not cell_value.isdigit():
                # Rule 2: Formula is only a reference, return text unchanged
                return cell_value
            elif isinstance(cell_value, (int, float)):
                return cell_value
            else:
                # Should not happen if lookup returns valid types
                return ERROR_GENERIC

        elif isinstance(node, BinaryOp):
            left_val = _evaluate_node(node.left)
            right_val = _evaluate_node(node.right)

            # Rule 3: Handle error propagation
            if isinstance(left_val, str) and left_val.startswith("#"):
                return left_val
            if isinstance(right_val, str) and right_val.startswith("#"):
                return right_val

            # Rule 3: Handle text mixing
            if isinstance(left_val, str) and left_val.startswith("#") is False and not isinstance(left_val, (int, float)):
                 # If the value is a non-error string (text from a reference)
                 return ERROR_GENERIC
            if isinstance(right_val, str) and right_val.startswith("#") is False and not isinstance(right_val, (int, float)):
                 return ERROR_GENERIC

            # Perform arithmetic operations
            if node.op == '+':
                return left_val + right_val
            elif node.op == '-':
                return left_val - right_val
            elif node.op == '*':
                return left_val * right_val
            elif node.op == '/':
                if right_val == 0:
                    return ERROR_GENERIC
                # Rule 4: Division is always float
                return float(left_val) / float(right_val)

            # Should be unreachable
            return ERROR_GENERIC

        elif isinstance(node, UnaryOp):
            operand_val = _evaluate_node(node.operand)

            if isinstance(operand_val, str) and operand_val.startswith("#"):
                return operand_val

            if node.op == '+':
                return operand_val + 0
            elif node.op == '-':
                return operand_val - 0

            # Should be unreachable
            return ERROR_GENERIC

        return ERROR_GENERIC # Fallback


    return _evaluate_node(tree)
