from typing import Dict, Set, Iterable

class DependencyGraph:
    """
    Records dependencies between cells (precedents) and calculates transitive
    dependencies (dependents) and cycles.
    """
    def __init__(self):
        # cell -> set of cells it refers to (precedents)
        self._precedents: Dict[str, Set[str]] = {}
        # cell -> set of cells that refer to it (dependents)
        self._dependents: Dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Iterable[str]):
        """
        Sets the direct dependencies (precedents) for a given cell.
        """
        precedent_set = set(p for p in precedents if p)

        # 1. Update Precedents
        self._precedents[cell] = precedent_set

        # 2. Update Dependents structures

        # Clear old dependent links for this cell
        if cell in self._dependents:
            for old_precedent in self._precedents.get(cell, set()):
                if old_precedent in self._dependents and cell in self._dependents[old_precedent]:
                    self._dependents[old_precedent].discard(cell)

        # Establish new dependent links
        for p in precedent_set:
            if p not in self._dependents:
                self._dependents[p] = set()
            self._dependents[p].add(cell)

        # Ensure all known cells exist in both dicts, even if empty
        # (Important for cells that become isolated)
        if cell not in self._dependents:
            self._dependents[cell] = set()


    def precedents(self, cell: str) -> Set[str]:
        """Returns the direct cells that 'cell' depends on."""
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> Set[str]:
        """Returns the direct cells that depend on 'cell'."""
        return self._dependents.get(cell, set())

    def all_dependents(self, cell: str) -> Set[str]:
        """
        Returns every cell that refers to 'cell' directly or indirectly,
        including 'cell' itself if it is part of a cycle.
        """
        if cell not in self._precedents and cell not in self._dependents:
            return set()

        # Use BFS/DFS to find all reachable nodes starting from the cell
        queue = list(self.dependents.get(cell, set()))
        visited = {cell} # Always include the cell itself in the traversal context
        reachable = set()

        # Standard BFS for transitive closure
        while queue:
            current = queue.pop(0)
            if current not in reachable:
                reachable.add(current)

                # Look at who depends on 'current'
                for neighbor in self._dependents.get(current, set()):
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)

        # Note: The requirement states: "It contains 'cell' itself only when 'cell' is on a cycle."
        # We handle this adjustment later when calculating cycle_cells().
        return reachable

    def _find_cycles(self) -> Set[str]:
        """
        Identifies all cells involved in a circular reference using DFS.
        A cell is in a cycle if, when following its precedents, it eventually
        leads back to itself.
        """
        visiting: Set[str] = set()
        visited_finished: Set[str] = set()
        cycle_cells: Set[str] = set()

        # Iterate over all known cells
        all_cells = set(self._precedents.keys()) | set(self._dependents.keys())

        def dfs(cell: str, path: Set[str]):
            if cell in visiting:
                # Cycle detected
                cycle_cells.add(cell)
                return

            if cell in visited_finished:
                return

            visiting.add(cell)
            path.add(cell)

            for precedent in self.precedents(cell):
                if precedent in cycle_cells:
                    # If precedent is already known to be in a cycle, this cell is affected.
                    cycle_cells.add(cell)
                    continue

                if precedent not in visited_finished:
                    dfs(precedent, path)

            # Backtrack
            visiting.remove(cell)
            path.remove(cell)
            visited_finished.add(cell)

        # Start DFS from every cell to ensure all components are checked
        for cell in sorted(list(all_cells)):
            if cell not in visited_finished:
                dfs(cell, set())

        return cycle_cells


    def cycle_cells(self) -> Set[str]:
        """Returns all cells that lie on a circular reference."""
        return self._find_cycles()

    # Helper to adjust dependents based on cycles
    def get_all_dependents_with_cycle_check(self, cell: str) -> Set[str]:
        """
        Returns the transitive dependents, ensuring 'cell' is included only if it's in a cycle.
        """
        if cell in self.cycle_cells():
             # If the cell itself is in a cycle, it affects itself.
             return self.all_dependents(cell)

        # Otherwise, the standard transitive closure is sufficient
        return self.all_dependents(cell)
