from typing import Dict, Any, List, Union, Set
from .graph import DependencyGraph
from .formula import parse_formula, references, evaluate, FormulaNode, ErrorValue, ERROR_GENERIC, ERROR_CYCLE

CellType = Union[int, float, str, None, ErrorValue]

class Sheet:
    """
    The main spreadsheet object, managing cell data, dependencies, and recalculation.
    """
    MAX_ROWS = 999
    MAX_COLS = 26

    def __init__(self):
        # Internal storage: {cell_name: raw_input_string}
        self._raw_data: Dict[str, str] = {}
        # Internal value cache: {cell_name: actual_value}
        self._values: Dict[str, CellType] = {}
        # Dependency tracking
        self._graph = DependencyGraph()
        self.evaluations = 0

    # --- Utility Functions ---

    def _validate_name(self, name: str):
        """Validates and normalizes cell names (e.g., 'b7' -> 'B7')."""
        name = name.upper()
        if not name:
            raise ValueError("Cell name cannot be empty.")

        match = re.match(r"([A-Z]{1,26})(\d+)", name)
        if not match:
            raise ValueError(f"Invalid cell name format: {name}")

        col_letters, row_str = match.groups()

        # Check column bounds (A-Z)
        if len(col_letters) > self.MAX_COLS:
             raise ValueError(f"Column name '{col_letters}' exceeds limit (A-Z).")

        # Check row bounds and formatting
        try:
            row_number = int(row_str)
            if row_number < 1 or row_number > self.MAX_ROWS:
                raise ValueError("Row number out of bounds.")
            # Leading zero check: if row_str is longer than 1 and starts with '0'
            if len(row_str) > 1 and row_str.startswith('0'):
                 raise ValueError("Row number cannot have leading zeros.")

        except ValueError:
            raise ValueError(f"Invalid row number: {row_str}")

        # Final bounds check (implicit in the above logic for 1-999)
        if row_number > self.MAX_ROWS:
            raise ValueError("Row number out of bounds.")

        return name

    def _get_row_major_order(self, cells: Set[str]) -> List[str]:
        """
        Sorts cell names by row number, then by column letter.
        Requires cell names to be uppercase (A1, B7).
        """
        def sort_key(name: str) -> Tuple[int, str]:
            col_str = "".join(filter(str.isalpha, name))
            row_str = "".join(filter(str.isdigit, name))
            return (int(row_str), col_str)

        return sorted(list(cells), key=sort_key)

    def _get_value(self, name: str) -> CellType:
        """Internal safe lookup function for evaluation."""
        return self._values.get(name, None)

    def _calculate_cell(self, name: str) -> CellType:
        """
        Calculates the value for a single cell if it contains a formula.
        Returns the calculated value.
        """
        raw_input = self._raw_data.get(name, "")

        if not raw_input or not raw_input.startswith('='):
            return self._parse_raw_input(raw_input)

        try:
            formula_source = raw_input[1:].strip()
            ast = parse_formula(formula_source)

            # 1. Check for cycles
            if name in self._graph.cycle_cells():
                return ERROR_CYCLE

            # 2. Evaluate
            # We pass our internal lookup function to evaluate
            return evaluate(ast, self._get_value)

        except Exception:
            # Catch all formula/parsing errors
            return ERROR_GENERIC

    def _parse_raw_input(self, raw_input: str) -> CellType:
        """
        Parses non-formula raw input (numbers, text, or empty).
        """
        if raw_input == '':
            return None

        # Check for number format: optional sign followed by digits/float
        # Since we only handle positive numbers based on the prompt's grammar
        # (no signs/exponents, unless it's the optional leading minus for storage)

        stripped_input = raw_input.strip()
        if stripped_input.startswith('-'):
            stripped_input = stripped_input[1:]

        if re.match(r"^\d+(\.\d+)?$", stripped_input):
            try:
                if '.' in stripped_input:
                    return float(stripped_input)
                else:
                    return int(stripped_input)
            except ValueError:
                # Should not happen given the regex
                return ERROR_GENERIC

        # Default is text
        return raw_input


    # --- Public Interface Methods ---

    def set(self, name: str, raw: str) -> List[str]:
        """
        Stores cell input, recalculates affected cells, and returns affected names.
        """
        name = self._validate_name(name)

        if not isinstance(raw, str):
            raise TypeError("Input 'raw' must be a string.")

        original_value = self._values.get(name)

        # Store raw input immediately
        self._raw_data[name] = raw

        # Determine all cells that might be affected (including self)
        affected_cells_set = self._graph.get_all_dependents_with_cycle_check(name)

        # If the cell itself was not previously in the affected set, we must add it
        if name not in affected_cells_set:
             affected_cells_set.add(name)

        # --- Recalculation Phase ---

        recalculated_names: List[str] = []

        # 1. Recalculate all affected cells
        # We must calculate them in a dependency-respecting order (Topological Sort)
        # Since we are calculating a subset of cells, we need a local topological sort.

        # Build temporary dependency structure for the affected set
        local_dependencies: Dict[str, Set[str]] = {}
        local_dependents: Dict[str, Set[str]] = {}

        for cell in affected_cells_set:
            precedents = self._graph.precedents(cell)
            # Filter precedents to only include those *also* in the affected set
            # This is slightly simplified, as we rely on the overall graph, but we ensure we process order.
            local_dependencies[cell] = precedents
            for p in precedents:
                 if p in affected_cells_set:
                     local_dependents.setdefault(p, set()).add(cell)

        # Kahn's Algorithm for Topological Sort on the affected subgraph
        queue = []
        in_degree = {cell: len(self._graph.precedents(cell).intersection(affected_cells_set)) for cell in affected_cells_set}

        for cell in affected_cells_set:
            if in_degree[cell] == 0:
                queue.append(cell)

        topo_order = []
        while queue:
            cell = queue.pop(0)
            topo_order.append(cell)

            # Find all cells that depend on 'cell' (within the affected set)
            for dependent in self._graph.dependents(cell).intersection(affected_cells_set):
                in_degree[dependent] -= 1
                if in_degree[dependent] == 0:
                    queue.append(dependent)

        if len(topo_order) != len(affected_cells_set):
            # This implies a cycle *among* the affected cells, which should have been handled by graph checks,
            # but is a safety check for topological sort failure.
            pass

        # 2. Execute recalculation in topological order

        # Track which cells had a value change
        changed_cells: Set[str] = set()

        for name in topo_order:

            # If the cell was not previously in the sheet, or if it has changed raw input
            # we must recalculate.
            needs_recalc = (name not in self._values) or (self._raw_data.get(name) != self._values.get(name, "") or name == name) 

            new_value = None

            if name in self._graph.cycle_cells():
                # Rule 2: Cell on a cycle is #CYCLE! and is not evaluated
                new_value = ERROR_CYCLE
            elif name in self._graph.precedents():
                # Formula cell: calculate the new value
                new_value = self._calculate_cell(name)
            else:
                # Simple data cell (text/number/None): parse the raw input
                new_value = self._parse_raw_input(self._raw_data[name])

            # Check for value change
            old_value = self._values.get(name)

            # Equality check needs to handle error values correctly
            is_changed = (old_value != new_value)

            if is_changed:
                changed_cells.add(name)

            # Update internal state
            self._values[name] = new_value

            # Track formula evaluations
            if name in self._graph.precedents() and not (isinstance(new_value, str) and new_value.startswith("#")):
                self.evaluations += 1


        # 3. Final result formatting

        # The list must be in row-major order
        recalculated_names = self._get_row_major_order(changed_cells)
        return recalculated_names

    def get(self, name: str) -> CellType:
        """Returns the cell's value."""
        name = self._validate_name(name)
        return self._values.get(name)

    def raw(self, name: str) -> str:
        """Returns the raw input stored for the cell."""
        name = self._validate_name(name)
        return self._raw_data.get(name, "")

    def cells(self) -> List[str]:
        """Returns all non-empty cell names in row-major order."""
        all_cells = set(self._values.keys())
        empty_cells = set()

        # Identify cells that are truly empty (None)
        for name, value in self._values.items():
            if value is None:
                empty_cells.add(name)

        non_empty_cells = all_cells - empty_cells
        return self._get_row_major_order(non_empty_cells)

    def __repr__(self):
        return f"<Sheet evaluations={self.evaluations}>"
