```python
import re
from typing import Any, Dict, List, Set, Tuple, Union, Callable, Optional

# Define error values globally
class FormulaError(ValueError):
    """Raised when a formula is syntactically incorrect or refers to invalid data."""
    pass

class ErrorValue(str):
    """Represents a calculation error in a cell."""
    pass

ERROR_CYCLE = ErrorValue("#CYCLE!")
ERROR_DIV_ZERO = ErrorValue("#DIV/0!")
ERROR_VALUE = ErrorValue("#VALUE!")
ERROR_REF = ErrorValue("#REF!")

# --- AST Node Definitions ---
class FormulaNode:
    """Base class for AST nodes."""
    pass

class Number(FormulaNode):
    def __init__(self, value: Union[int, float]):
        self.value = value
    def __repr__(self):
        return f"Number({self.value})"

class Ref(FormulaNode):
    def __init__(self, name: str):
        self.name = name.upper()
    def __repr__(self):
        return f"Ref({self.name})"

class UnaryOp(FormulaNode):
    def __init__(self, op: str, operand: FormulaNode):
        self.op = op
        self.operand = operand
    def __repr__(self):
        return f"UnaryOp('{self.op}', {self.operand})"

class BinaryOp(FormulaNode):
    def __init__(self, op: str, left: FormulaNode, right: FormulaNode):
        self.op = op
        self.left = left
        self.right = right
    def __repr__(self):
        return f"BinaryOp('{self.op}', {self.left}, {self.right})"

class Call(FormulaNode):
    def __init__(self, fname: str, args: List[FormulaNode]):
        self.fname = fname.upper()
        self.args = args
    def __repr__(self):
        return f"Call('{self.fname}', {self.args})"

# --- Parsing Logic ---

# Regex components
TOKEN_DIGIT = r"\d+"
TOKEN_DOT = r"\."
TOKEN_LETTER = r"[A-Za-z]"
TOKEN_NUMBER_PART = fr"(?:{TOKEN_DIGIT}(?:\.{TOKEN_DIGIT})?)"
TOKEN_REF = fr"(?:{TOKEN_LETTER}{TOKEN_DIGIT}+)" # letters followed by digits

# Tokenization uses aggressive space insertion
def _tokenize(source: str) -> List[str]:
    """Splits the formula source into meaningful tokens, allowing for whitespace."""

    # Operators and separators
    operators = ['+', '-', '*', '/', '(', ')', ':']
    source = source
    for op in operators:
        source = source.replace(op, f" {op} ")

    # Function names (SUM, AVG, etc.) are separated by spaces implicitly

    return [t for t in source.split() if t]

class Parser:
    """
    Parser implementation using recursive descent for the given grammar.
    """
    def __init__(self, tokens: List[str]):
        self.tokens = tokens
        self.pos = 0
        self.known_functions = {'SUM', 'AVG', 'MIN', 'MAX'}

    def current_token(self) -> Optional[str]:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self) -> Optional[str]:
        if self.pos < len(self.tokens):
            token = self.tokens[self.pos]
            self.pos += 1
            return token
        return None

    def expect(self, expected_token: str):
        token = self.advance()
        if token != expected_token:
            raise FormulaError(f"Expected '{expected_token}', got '{token}'")

    def parse(self) -> FormulaNode:
        """Entry point: parse expression."""
        tree = self._parse_expr()
        if self.current_token() is not None:
            raise FormulaError(f"Unexpected token at end of formula: '{self.current_token()}'")
        return tree

    # expr   := term {(+ | -) term}
    def _parse_expr(self) -> FormulaNode:
        left = self._parse_term()

        while self.current_token() in ('+', '-'):
            op = self.advance()
            right = self._parse_term()
            left = BinaryOp(op, left, right)

        return left

    # term   := unary {(* | /) unary}
    def _parse_term(self) -> FormulaNode:
        left = self._parse_unary()

        while self.current_token() in ('*', '/'):
            op = self.advance()
            right = self._parse_unary()
            left = BinaryOp(op, left, right)

        return left

    # unary  := (+ | -) unary | number | ref | call | ( expr )
    def _parse_unary(self) -> FormulaNode:
        token = self.current_token()

        if token in ('+', '-'):
            op = self.advance()
            return UnaryOp(op, self._parse_unary())

        elif token is None:
             raise FormulaError("Unexpected end of input.")

        elif token == '(':
            self.advance() # Consume '('
            expr = self._parse_expr()
            self.expect(')')
            return expr

        elif token in self.known_functions:
            return self._parse_call()

        elif re.match(r"^[A-Za-z]", token):
            # Must be a reference (if it doesn't start a function)
            return self._parse_ref()

        elif token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
            # Must be a number
            return self._parse_number()

        else:
            raise FormulaError(f"Unexpected token: '{token}'")

    def _parse_number(self) -> Number:
        token = self.advance()

        # Handle potential leading minus if it wasn't consumed by unary op (though it should be)
        if token and token.startswith('-'):
            token = token[1:]

        if '.' in token:
            try:
                value = float(token)
            except ValueError:
                raise FormulaError(f"Invalid float format: {token}")
        else:
            try:
                value = int(token)
            except ValueError:
                raise FormulaError(f"Invalid integer format: {token}")

        return Number(value)

    def _parse_ref(self) -> Ref:
        # Ref pattern: letters followed by digits (A1, Z999)
        token = self.advance()
        if not re.match(r"^[A-Za-z]\d+$", token):
            raise FormulaError(f"Invalid reference format: {token}")

        return Ref(token)

    def _parse_range(self) -> Tuple[Ref, Ref]:
        """
        Parses a range (Ref : Ref).
        Requires a preceding Ref token and a subsequent ':' token.
        """
        start_ref = self._parse_ref()
        self.expect(':')
        end_ref = self._parse_ref()
        return start_ref, end_ref

    def _parse_arg(self) -> FormulaNode:
        """
        Parses an argument: ref : ref | expr
        """
        token = self.current_token()

        # Check for range first (must start with a reference)
        if re.match(r"^[A-Za-z]\d+$", token):
            start_ref = self._parse_ref()

            if self.current_token() == ':':
                self.advance() # Consume ':'
                end_ref = self._parse_ref()
                return tuple(self._parse_range()) # Return as a tuple (Ref, Ref) to signify range

        # Otherwise, it's a normal expression (potentially wrapped in parentheses)
        return self._parse_expr()


    def _parse_call(self) -> Call:
        """
        Parses a function call: fname ( arg {, arg} )
        """
        fname = self.advance().upper()
        if fname not in self.known_functions:
            raise FormulaError(f"Unknown function: {fname}")

        self.expect('(')

        args = []

        # Handle the possibility of zero arguments (though prompt says no arguments allowed)
        if self.current_token() != ')':
            # Parse the first argument
            args.append(self._parse_arg())

            # Parse subsequent arguments
            while self.current_token() == ',':
                self.advance() # Consume ','
                args.append(self._parse_arg())

        self.expect(')')

        # Check for no arguments (which is illegal based on prompt)
        if not args:
            raise FormulaError(f"Function {fname} requires at least one argument.")

        return Call(fname, args)


def parse_formula(source: str) -> FormulaNode:
    """
    Parses a formula string (after '=') into an AST.
    Raises FormulaError if parsing fails.
    """
    if not source.strip():
        raise FormulaError("Formula body cannot be empty.")

    tokens = _tokenize(source)
    if not tokens:
        raise FormulaError("Formula body cannot be empty.")

    parser = Parser(tokens)
    return parser.parse()


# --- Dependency Analysis ---

def references(tree: FormulaNode, sheet_bounds: Tuple[int, int]) -> Set[str]:
    """
    Recursively finds all cell references in the AST and returns them as an
    upper-case set of strings, including ranges.
    sheet_bounds: (max_rows, max_cols) for validation.
    """
    names = set()

    if isinstance(tree, Ref):
        names.add(tree.name)
    elif isinstance(tree, BinaryOp):
        names.update(references(tree.left, sheet_bounds))
        names.update(references(tree.right, sheet_bounds))
    elif isinstance(tree, UnaryOp):
        names.update(references(tree.operand, sheet_bounds))
    elif isinstance(tree, Call):
        for arg in tree.args:
            if isinstance(arg, tuple) and isinstance(arg[0], Ref) and isinstance(arg[1], Ref):
                # Handle Range: ref : ref
                r1 = arg[0]
                r2 = arg[1]
                names.add(r1.name)
                names.add(r2.name)
            else:
                names.update(references(arg, sheet_bounds))

    return names

# --- Evaluation Helpers ---

def _range_to_cells(r1: Ref, r2: Ref, max_rows: int, max_cols: int) -> Optional[List[str]]:
    """
    Converts two corner references (r1, r2) into a sorted list of internal cell names.
    Returns None if either corner is outside the sheet.
    """

    # Utility to parse A1 into (col_index, row_index)
    def parse_ref(ref: Ref) -> Tuple[int, int]:
        col_str = "".join(filter(str.isalpha, ref.name))
        row_str = "".join(filter(str.isdigit, ref.name))

        col_index = 0
        for i, char in enumerate(col_str):
            col_index += (ord(char) - ord('A') + 1) * (26**(len(col_str) - 1 - i))

        row_index = int(row_str)
        return col_index, row_index

    try:
        c1, r1 = parse_ref(r1)
        c2, r2 = parse_ref(r2)
    except ValueError:
        # Should not happen if Ref structure is correct
        return None

    # Check boundaries (1-based indices)
    if not (1 <= r1 <= max_rows and 1 <= c1 <= max_cols) or \
       not (1 <= r2 <= max_rows and 1 <= c2 <= max_cols):
        return None

    # Determine bounding box
    min_r = min(r1, r2)
    max_r = max(r1, r2)
    min_c = min(c1, c2)
    max_c = max(c1, c2)

    cells = []
    # Iterate in row-major order
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            col_str = chr(ord('A') + c - 1)
            cells.append(f"{col_str}{r}")

    return cells


def evaluate(tree: FormulaNode, lookup: Callable[[str], Any], max_rows: int, max_cols: int) -> Any:
    """
    Computes the value of the formula AST.
    lookup(name: str) -> value (int, float, str, None, or ErrorValue)
    """

    def _evaluate_node(node: FormulaNode) -> Union[int, float, str, ErrorValue]:

        if isinstance(node, Number):
            return node.value

        elif isinstance(node, Ref):
            # Check for out-of-bounds references
            ref_name = node.name
            col_str = "".join(filter(str.isalpha, ref_name))
            row_str = "".join(filter(str.isdigit, ref_name))

            if len(col_str) > max_cols:
                 return ERROR_REF

            try:
                row_number = int(row_str)
                if row_number < 1 or row_number > max_rows:
                    return ERROR_REF
            except ValueError:
                 # Should be caught during parsing, but safety check
                 return ERROR_REF


            cell_value = lookup(ref_name)

            if cell_value is None:
                return 0
            elif isinstance(cell_value, str) and cell_value.startswith("#"):
                return cell_value
            elif isinstance(cell_value, str) and not isinstance(cell_value, ErrorValue):
                # Text from cell
                return cell_value
            elif isinstance(cell_value, (int, float)):
                return cell_value
            else:
                return ERROR_VALUE

        elif isinstance(node, BinaryOp):
            left_val = _evaluate_node(node.left)
            right_val = _evaluate_node(node.right)

            # Error propagation: leftmost error takes precedence over #VALUE!
            if isinstance(left_val, str) and left_val.startswith("#"):
                return left_val
            if isinstance(right_val, str) and right_val.startswith("#"):
                return right_val

            # Text mixing check (if either operand is non-numeric text, it's #VALUE!)
            # Note: Numeric results (int/float) from Refs/Ranges are always numeric.
            is_left_text = isinstance(left_val, str) and not isinstance(left_val, ErrorValue) and not isinstance(left_val, (int, float))
            is_right_text = isinstance(right_val, str) and not isinstance(right_val, ErrorValue) and not isinstance(right_val, (int, float))

            if is_left_text or is_right_text:
                 return ERROR_VALUE

            # Arithmetic operations (Only proceed if both are numeric/zero)
            try:
                if node.op == '+':
                    return left_val + right_val
                elif node.op == '-':
                    return left_val - right_val
                elif node.op == '*':
                    return left_val * right_val
                elif node.op == '/':
                    if right_val == 0:
                        return ERROR_DIV_ZERO
                    return float(left_val) / float(right_val)
            except TypeError:
                # Catch unexpected type errors (e.g., trying to add a non-numeric text accidentally)
                return ERROR_VALUE

            return ERROR_VALUE

        elif isinstance(node, UnaryOp):
            operand_val = _evaluate_node(node.operand)

            if isinstance(operand_val, str) and operand_val.startswith("#"):
                return operand_val

            if isinstance(operand_val, str) and not isinstance(operand_val, ErrorValue):
                 return ERROR_VALUE # Cannot apply +/- to text

            if node.op == '+':
                return operand_val + 0
            elif node.op == '-':
                return operand_val - 0

            return ERROR_VALUE

        elif isinstance(node, Call):
            fname = node.fname

            # 1. Evaluate arguments first
            evaluated_args = []
            for arg_node in node.args:
                if isinstance(arg_node, tuple) and isinstance(arg_node[0], Ref) and isinstance(arg_node[1], Ref):
                    # This is a range argument (R1:R2)
                    r1 = arg_node[0]
                    r2 = arg_node[1]

                    # Get all cells in the range, checking bounds
                    range_cells = _range_to_cells(r1, r2, max_rows, max_cols)
                    if range_cells is None:
                        return ERROR_REF # Range out of bounds

                    # Evaluate the range
                    range_values = []

                    # Iterate through cells in row-major order
                    for cell_name in range_cells:
                        cell_val = lookup(cell_name)

                        if isinstance(cell_val, str) and cell_val.startswith("#"):
                            return cell_val # Immediate error propagation

                        if isinstance(cell_val, (int, float)):
                            range_values.append(cell_val)
                        # Skip empty (None) or text cells

                    evaluated_args.append(range_values)
                else:
                    # Evaluate expression/reference
                    arg_result = _evaluate_node(arg_node)

                    if isinstance(arg_result, str) and arg_result.startswith("#"):
                        return arg_result # Error propagation

                    # Check for text results from single reference arguments
                    if isinstance(arg_result, str) and not isinstance(arg_result, ErrorValue) and not isinstance(arg_result, (int, float)):
                        # Argument is text, which is not a number
                        return ERROR_VALUE

                    evaluated_args.append(arg_result)

            # 2. Compute function result

            if fname == 'SUM':
                numbers = []
                for arg in evaluated_args:
                    if isinstance(arg, list):
                        numbers.extend(arg)
                    elif isinstance(arg, (int, float)):
                        numbers.append(arg)

                if not numbers:
                    return 0

                # Check if any element was text (only possible if it was a single non-numeric reference)
                if any(isinstance(arg, str) and not isinstance(arg, ErrorValue) for arg in evaluated_args):
                     return ERROR_VALUE

                # Check for mixed types
                first_is_float = any(isinstance(n, float) for n in numbers)
                if first_is_float:
                    return sum(numbers)
                else:
                    return int(sum(numbers))

            elif fname == 'AVG':
                numbers = []
                for arg in evaluated_args:
                    if isinstance(arg, list):
                        numbers.extend(arg)
                    elif isinstance(arg, (int, float)):
                        numbers.append(arg)

                if not numbers:
                    return ERROR_DIV_ZERO
                return sum(numbers) / len(numbers)

            elif fname == 'MIN':
                numbers = []
                for arg in evaluated_args:
                    if isinstance(arg, list):
                        numbers.extend(arg)
                    elif isinstance(arg, (int, float)):
                        numbers.append(arg)

                if not numbers:
                    return 0
                return min(numbers)

            elif fname == 'MAX':
                numbers = []
                for arg in evaluated_args:
                    if isinstance(arg, list):
                        numbers.extend(arg)
                    elif isinstance(arg, (int, float)):
                        numbers.append(arg)

                if not numbers:
                    return 0
                return max(numbers)

        return ERROR_VALUE # Should not be reached

    return _evaluate_node(tree)
