from dataclasses import dataclass
from typing import List, Optional

@dataclass(frozen=True)
class TicTacToe:
    board: str

    def __post_init__(self):
        if len(self.board) != 9:
            raise ValueError("TicTacToe board must be 9 characters long.")

        counts = {'X': 0, 'O': 0}
        for char in self.board:
            if char not in ('X', 'O', '.'):
                raise ValueError(f"Invalid character in board: {char}")
            counts[char] += 1

        if counts['X'] < counts['O'] or counts['X'] > counts['O'] + 1:
            raise ValueError("Impossible game state: X must lead or match O in count.")

    def player(self) -> str:
        counts = {'X': 0, 'O': 0}
        for char in self.board:
            if char == 'X':
                counts['X'] += 1
            elif char == 'O':
                counts['O'] += 1

        return 'X' if counts['X'] == counts['O'] else 'O'

    def moves(self) -> List[int]:
        return [i for i, char in enumerate(self.board) if char == '.']

    def play(self, move: int) -> 'TicTacToe':
        if not 0 <= move < 9:
            raise ValueError("Illegal move: index out of bounds.")
        if self.board[move] != '.':
            raise ValueError(f"Illegal move: square {move} is already taken.")

        new_board = list(self.board)
        new_board[move] = self.player()
        return TicTacToe("".join(new_board))

    def winner(self) -> Optional[str]:
        board = self.board

        # Check rows
        for i in range(3):
            if board[i*3] == board[i*3+1] == board[i*3+2] and board[i*3] != '.':
                return board[i*3]

        # Check columns
        for j in range(3):
            if board[j] == board[j+3] == board[j+6] and board[j] != '.':
                return board[j]

        # Check diagonals
        # Top-left to bottom-right
        if board[0] == board[4] == board[8] and board[0] != '.':
            return board[0]
        # Top-right to bottom-left
        if board[2] == board[4] == board[6] and board[2] != '.':
            return board[2]

        return None

    def is_over(self) -> bool:
        return self.winner() is not None or len(self.moves()) == 0

    def __str__(self) -> str:
        return "\n".join(self.board[i*3:(i+1)*3] for i in range(3))

    @classmethod
    def from_moves(cls, moves: List[int]) -> 'TicTacToe':
        board_list = ['.'] * 9
        current_state = cls(board='.........')

        for move in moves:
            try:
                current_state = current_state.play(move)
            except ValueError as e:
                raise ValueError(f"Illegal move sequence: {e}") from e
        return current_state
