from dataclasses import dataclass
from typing import List, Optional

@dataclass(frozen=True)
class ConnectFour:
    columns: int
    rows: int

    # Internal state: list of lists (row, col), row 0 is bottom
    _board_state: List[List[str]]

    def __post_init__(self):
        if self.columns < 1 or self.rows < 1:
            raise ValueError("Columns and rows must be at least 1.")

        # Initialize board with empty cells ('.')
        self._board_state = [['.' for _ in range(self.columns)] for _ in range(self.rows)]

    @property
    def board(self) -> List[List[str]]:
        return self._board_state

    def player(self) -> str:
        x_count = sum(row.count('X') for row in self._board_state)
        o_count = sum(row.count('O') for row in self._board_state)
        return 'X' if x_count == o_count else 'O'

    def moves(self) -> List[int]:
        # Legal moves are columns that are not full
        return [c for c in range(self.columns) if self._board_state[self.rows - 1][c] == '.']

    def play(self, col: int) -> 'ConnectFour':
        if not 0 <= col < self.columns:
            raise ValueError("Illegal move: column index out of bounds.")

        # Find the lowest empty row (gravity)
        row_to_place = -1
        for r in range(self.rows):
            if self._board_state[r][col] == '.':
                row_to_place = r
            else:
                # Since we check from bottom up, the first non-empty cell means the row below it was the target
                break

        if row_to_place == -1:
            # Column is full
            raise ValueError(f"Illegal move: Column {col} is full.")

        # Create a mutable copy for the new state
        new_board_list = [row[:] for row in self._board_state]
        new_board_list[row_to_place][col] = self.player()

        # Create the new immutable state
        new_state = ConnectFour(self.columns, self.rows)
        new_state._board_state = new_board_list
        return new_state

    def cell(self, column: int, row: int) -> str:
        if not 0 <= column < self.columns or not 0 <= row < self.rows:
            raise IndexError("Coordinates outside board dimensions.")
        return self._board_state[row][column]

    def winner(self) -> Optional[str]:
        P = self._board_state
        C = self.columns
        R = self.rows
        WIN_SIZE = 4

        if R < WIN_SIZE and C < WIN_SIZE:
            return None # Not big enough for a 4-in-a-row

        # Check Horizontal
        for r in range(R):
            for c in range(C - WIN_SIZE + 1):
                piece = P[r][c]
                if piece != '.':
                    if all(P[r][c + i] == piece for i in range(WIN_SIZE)):
                        return piece

        # Check Vertical
        for c in range(C):
            for r in range(R - WIN_SIZE + 1):
                piece = P[r][c]
                if piece != '.':
                    if all(P[r + i][c] == piece for i in range(WIN_SIZE)):
                        return piece

        # Check Diagonal (Top-Left to Bottom-Right)
        for r in range(R - WIN_SIZE + 1):
            for c in range(C - WIN_SIZE + 1):
                piece = P[r][c]
                if piece != '.':
                    if all(P[r + i][c + i] == piece for i in range(WIN_SIZE)):
                        return piece

        # Check Diagonal (Top-Right to Bottom-Left)
        for r in range(R - WIN_SIZE + 1):
            for c in range(WIN_SIZE - 1, C):
                piece = P[r][c]
                if piece != '.':
                    if all(P[r + i][c - i] == piece for i in range(WIN_SIZE)):
                        return piece

        return None

    def is_over(self) -> bool:
        # Check if full board
        if len(self.moves()) == 0:
            return True
        # Check for winner
        return self.winner() is not None

    def __str__(self) -> str:
        # ConnectFour shows the top row first.
        # We reverse the board list before joining rows.
        rows_str = []
        for r in range(self.rows - 1, -1, -1):
            rows_str.append("".join(self._board_state[r]))
        return "\n".join(rows_str)

    @classmethod
    def from_moves(cls, moves: List[int], columns: int = 7, rows: int = 6) -> 'ConnectFour':
        state = cls(columns=columns, rows=rows)
        for move in moves:
            try:
                state = state.play(move)
            except ValueError as e:
                raise ValueError(f"Illegal move sequence: {e}") from e
        return state


def evaluate(state: ConnectFour) -> int:
    """
    Heuristic evaluation for ConnectFour. 
    Window of 4 cells (H, V, D).
    1 player (n pieces): score n*n (positive if state.player, negative otherwise).
    Empty windows or 4-piece windows: score 0.
    """
    score = 0
    P = state.board
    C = state.columns
    R = state.rows
    WIN_SIZE = 4

    def count_pieces(window: List[str]) -> dict:
        counts = {'X': 0, 'O': 0, '.': 0}
        for piece in window:
            counts[piece] += 1
        return counts

    # Helper function to iterate over all possible 4-cell windows
    windows = []

    # 1. Horizontal windows
    for r in range(R):
        for c in range(C - WIN_SIZE + 1):
            windows.append([P[r][c+i] for i in range(WIN_SIZE)])

    # 2. Vertical windows
    for c in range(C):
        for r in range(R - WIN_SIZE + 1):
            windows.append([P[r+i][c] for i in range(WIN_SIZE)])

    # 3. Diagonal (TL to BR)
    for r in range(R - WIN_SIZE + 1):
        for c in range(C - WIN_SIZE + 1):
            windows.append([P[r+i][c+i] for i in range(WIN_SIZE)])

    # 4. Diagonal (TR to BL)
    for r in range(R - WIN_SIZE + 1):
        for c in range(WIN_SIZE - 1, C):
            windows.append([P[r+i][c-i] for i in range(WIN_SIZE)])


    for window in windows:
        counts = count_pieces(window)

        # Only check windows that are not fully empty and not fully filled (4 pieces)
        if counts['.'] > 0 and counts['X'] > 0 and counts['O'] > 0:
            # Mixed window (both X and O)
            continue

        if counts['X'] + counts['O'] < WIN_SIZE:
            # Partially filled window

            if counts['X'] == 0:
                # Only O pieces (or empty)
                n = counts['O']
                if n > 0:
                    # Positive if state.player is O, negative otherwise
                    value = n * n if state.player() == 'O' else -(n * n)
                    score += value

            elif counts['O'] == 0:
                # Only X pieces (or empty)
                n = counts['X']
                if n > 0:
                    # Positive if state.player is X, negative otherwise
                    value = n * n if state.player() == 'X' else -(n * n)
                    score += value
            # Note: If both are 0 (empty), score is 0, handled by default.

    return score
