```python
from dataclasses import dataclass
from typing import Callable, Optional, TypeVar, Generic
import math
import random

# Define TypeVars for generic use in the search algorithm
S = TypeVar('S')
M = TypeVar('M')
A = TypeVar('A')

@dataclass(frozen=True)
class SearchResult:
    score: float
    move: Optional[M]
    nodes: int

# --- Search Implementation ---

def search(state: S, depth: Optional[int] = None, evaluate: Optional[Callable[[S], float]] = None) -> SearchResult:
    """
    Negamax search with alpha-beta pruning.
    """

    # Initialize search parameters
    MAX_SCORE = float('inf')
    MIN_SCORE = float('-inf')

    # State specific helper functions
    def is_terminal(s: S) -> bool:
        return s.is_over()

    def get_ply(s: S) -> int:
        # We assume ply is 0 at the root of the search
        # Since we don't pass ply down, we must rely on the search function structure
        # To simplify, we handle ply tracking externally if needed, but for the 
        # terminal scoring defined in the prompt, the ply needs to be tracked 
        # relative to the initial call depth. 
        # Since this search function is recursive, we need to pass ply down.
        raise NotImplementedError("ply must be passed explicitly if required for scoring.")

    def negamax(s: S, alpha: float, beta: float, current_depth: int, root_depth: int, ply: int) -> float:

        if current_depth == 0 or is_terminal(s):
            # Terminal state scoring
            if is_terminal(s):
                winner = s.winner()

                if winner is None:
                    return 0.0 # Draw

                # Score is for the player to move in state s
                player_to_move = s.player()

                if winner == player_to_move:
                    # Win: 1000 - ply (higher ply means slower win, lower score)
                    return float(1000 - ply)
                else:
                    # Loss: -(1000 - ply)
                    return float(-(1000 - ply))

            # Depth limit reached, evaluate
            if evaluate is not None:
                return evaluate(s)
            else:
                return 0.0


        moves = s.moves()
        if not moves:
            # Should have been caught by is_terminal, but safety check
            return 0.0

        max_score = float('-inf')

        # We need to track the best move that achieved this max score
        best_move = moves[0] # Defaulting to first move if scores tie

        nodes_examined = 0

        for move in moves:
            next_state = s.play(move)
            nodes_examined += 1

            # Recursive call: negamax switches perspective (maximizer becomes minimizer)
            score = -negamax(next_state, -beta, -alpha, current_depth - 1, root_depth, ply + 1)

            if score > max_score:
                max_score = score
                best_move = move

            alpha = max(alpha, score)
            if alpha >= beta:
                break # Beta cutoff

        # We need to wrap this complex recursive structure to track nodes accurately.
        # Since the required return type is SearchResult, we must restructure the public function.
        return max_score

    # --- Wrapper function to manage SearchResult tracking ---

    total_nodes = 1 # Root node

    # We use a nested helper to track nodes cleanly
    def search_recursive(s: S, alpha: float, beta: float, current_depth: int, ply: int) -> Tuple[float, Optional[M]]:
        nonlocal total_nodes

        if current_depth == 0 or is_terminal(s):
            if is_terminal(s):
                winner = s.winner()
                if winner is None: return 0.0, None

                player_to_move = s.player()

                if winner == player_to_move:
                    return float(1000 - ply), None
                else:
                    return float(-(1000 - ply)), None

            if evaluate is not None:
                return evaluate(s), None
            else:
                return 0.0, None


        max_score = float('-inf')
        best_move = None

        moves = s.moves()

        for move in moves:
            next_state = s.play(move)
            total_nodes += 1

            # Recursive call
            score, _ = search_recursive(next_state, -beta, -alpha, current_depth - 1, ply + 1)

            negated_score = -score

            # Tie breaking: choose the first move encountered
            if negated_score > max_score:
                max_score = negated_score
                best_move = move

            alpha = max(alpha, negated_score)
            if alpha >= beta:
                break 

        return max_score, best_move


    score, move = search_recursive(state, float('-inf'), float('inf'), depth if depth is not None else sys.maxsize, 0, 0)

    return SearchResult(score=score, move=move, nodes=total_nodes)


def best_move(state: S, depth: Optional[int] = None, evaluate: Optional[Callable[[S], float]] = None) -> M:
    """
    Returns the move that achieves the best score.
    Raises ValueError if the game is over.
    """
    if state.is_over():
        raise ValueError("Game is already over.")

    result = search(state, depth=depth, evaluate=evaluate)

    if result.move is None:
         # Should only happen if moves() was empty, which is handled by is_over
         raise ValueError("No legal moves found.")

    return result.move

# --- Agent Definitions ---
import sys

def search_agent(depth: Optional[int] = None, evaluate: Optional[Callable[[S], float]] = None) -> A:
    """
    Returns an agent that plays best_move using search.
    """
    def agent(state: S) -> M:
        return best_move(state, depth, evaluate)
    return agent

def random_agent(seed: int) -> A:
    """
    Returns an agent that plays a random legal move.
    """
    rng = random.Random(seed)
    def agent(state: S) -> M:
        if not state.moves():
            raise ValueError("Cannot move, game over.")
        return rng.choice(state.moves())
    return agent

def play_game(state: S, agents: Dict[str, A]) -> Tuple[S, List[Any]]:
    """
    Plays the game until it is over.
    Returns (final_state, list_of_moves).
    """
    current_state = state
    moves_played = []

    while not current_state.is_over():
        player_symbol = current_state.player()
        agent_func = agents[player_symbol]

        try:
            move = agent_func(current_state)
        except ValueError as e:
             # Agent returned an illegal move (e.g., if game was technically over 
             # just before the call, although loop check should prevent this)
             raise ValueError(f"Agent tried an illegal move: {e}") from e

        try:
            current_state = current_state.play(move)
            moves_played.append(move)
        except ValueError as e:
            # This catches errors from the game state itself (e.g., move after game over)
            raise ValueError(f"Illegal move {move} attempted by {player_symbol}: {e}") from e

    return current_state, moves_played
