This file handles the transformation of raw text into a stream of structured tokens, managing precise line and column positions and reporting scanner-specific errors.

```python
# js/scanner.py
from collections import namedtuple
import re

# Define the JSONError class
class JSONError(ValueError):
    def __init__(self, msg, line, column):
        self.msg = msg
        self.line = line
        self.column = column
        super().__init__(f"{msg} at line {line} column {column}")

# Define the Token structure
Token = namedtuple('Token', ['kind', 'value', 'line', 'column'])

class ScannerError(JSONError):
    """Wrapper for scanner errors."""
    pass

class Scanner:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.line = 1
        self.column = 1

    def advance(self):
        if self.pos >= len(self.text):
            return None
        char = self.text[self.pos]
        self.pos += 1
        if char == '\n':
            self.line += 1
            self.column = 1
        else:
            self.column += 1
        return char

    def peek(self, offset=0):
        idx = self.pos + offset
        if idx >= len(self.text):
            return None
        return self.text[idx]

    def current_pos(self):
        return self.line, self.column

    def skip_whitespace(self):
        while True:
            char = self.peek()
            if char is None or char not in ' \t\n\r':
                break
            self.advance()

    def scan_string(self, start_line, start_column):
        start_pos = self.pos
        # Consume the opening quote
        self.advance()

        while self.pos < len(self.text):
            char = self.peek()

            if char == '"':
                # End of string
                value = self.text[start_pos + 1: self.pos]
                return value

            if char == '\\':
                self.advance() # Consume '\'
                escape_char = self.peek()

                if escape_char is None:
                    raise ScannerError("Unterminated string: expected character after escape", start_line, start_column)

                if escape_char == '"' or escape_char == '\\' or escape_char == '/':
                    self.advance()
                    value += {'"': '"', '\\': '\\', '/': '/'}.get(escape_char)
                    continue

                elif escape_char == 'b':
                    self.advance()
                    value += '\b'
                    continue
                elif escape_char == 'f':
                    self.advance()
                    value += '\f'
                    continue
                elif escape_char == 'n':
                    self.advance()
                    value += '\n'
                    continue
                elif escape_char == 'r':
                    self.advance()
                    value += '\r'
                    continue
                elif escape_char == 't':
                    self.advance()
                    value += '\t'
                    continue

                elif escape_char == 'u':
                    # Handle \uXXXX
                    self.advance() # Consume 'u'
                    hex_digits = self.text[self.pos: self.pos + 4]
                    if len(hex_digits) != 4:
                        raise ScannerError("Invalid escape sequence: expected four hex digits after \\u", start_line, start_column)

                    try:
                        codepoint = int(hex_digits, 16)

                        # Handle high/low surrogate pairs
                        if 0xD800 <= codepoint <= 0xDBFF:
                            # High surrogate encountered. Expect low surrogate next.

                            # Check if the next 4 hex digits form a low surrogate
                            if self.peek(4) == '\\' and self.text[self.pos+1] == 'u':
                                # This logic assumes the surrogate pair is encoded as two sequential \u escapes.
                                # Since the scanner processes character by character, we need to handle the pair structure.

                                # The JSON standard requires the pair to be encoded as two consecutive \uXXXX escapes.
                                # Since we are processing the sequence, we decode the high one, and then expect the low one.

                                # High surrogate (D800-DBFF)
                                high_char = chr(codepoint)
                                self.pos += 4

                                # Check for low surrogate escape immediately following
                                low_start_pos = self.pos

                                # We need to read the *next* \uXXXX escape sequence.
                                next_escape_start = self.pos
                                if self.peek() != '\\':
                                    # The sequence is broken.
                                    raise ScannerError("High surrogate not followed by a low surrogate escape", start_line, start_column)

                                # Skip the starting backslash of the next escape
                                self.advance() 

                                # Read the next four hex digits
                                next_hex_digits = self.text[self.pos: self.pos + 4]
                                if len(next_hex_digits) != 4:
                                    raise ScannerError("Invalid escape sequence: expected four hex digits for low surrogate", start_line, start_column)

                                try:
                                    low_codepoint = int(next_hex_digits, 16)
                                except ValueError:
                                    raise ScannerError("Invalid hex digits in low surrogate escape", start_line, start_column)

                                # Check if it is indeed a low surrogate (DC00-DFFF)
                                if not (0xDC00 <= low_codepoint <= 0xDFFF):
                                    raise ScannerError("Low surrogate expected but found non-low surrogate character", start_line, start_column)

                                # Combine surrogates
                                unicode_codepoint = 0x10000 + ((codepoint - 0xD800) * 0x400) + (low_codepoint - 0xDC00)
                                value += chr(unicode_codepoint)
                                self.pos += 4
                                continue # Successfully parsed pair
                            else:
                                # High surrogate not followed by a second \u
                                raise ScannerError("High surrogate not followed by a low surrogate escape", start_line, start_column)

                        elif 0xDC00 <= codepoint <= 0xDFFF:
                            # Low surrogate on its own
                            raise ScannerError("Low surrogate found without preceding high surrogate", start_line, start_column)
                        else:
                            # Standard character (BMP)
                            value += chr(codepoint)
                            self.pos += 4
                            continue

                    except ValueError:
                        raise ScannerError("Invalid hexadecimal digits in Unicode escape sequence", start_line, start_column)

                else:
                    # Unknown escape sequence
                    raise ScannerError(f"Unknown escape sequence: \\{escape_char}", start_line, start_column)

            # Check for raw control characters (U+0000–U+001F)
            current_char = char
            if 0x00 <= ord(current_char) <= 0x1F and current_char not in ('\n', '\r', '\t', '\b', '\f'):
                raise ScannerError("Raw control character found inside string", start_line, start_column)

            value += char
            self.advance()

        # If we reached here, the string was unterminated
        raise ScannerError("Unterminated string literal", start_line, start_column)

    def scan_number(self, start_line, start_column):
        start_pos = self.pos

        # Use regex to find the longest possible run of number characters
        # Pattern: optional sign, followed by digits/dot/e/E
        # This pattern is intentionally broad to capture the entire potential number token.
        match = re.match(r'[+-]?[0-9\.eE+-]+', self.text[self.pos:])
        if not match:
            # Should not happen if called correctly
            raise ScannerError("Internal error during number scan", start_line, start_column)

        num_text = match.group(0)
        self.pos += len(num_text)

        # Update position trackers to reflect consumption
        # Note: Line/Column tracking must be accurate based on num_text
        for char in num_text:
            if char == '\n':
                self.line += 1
                self.column = 1
            else:
                self.column += 1

        # Validate the structure strictly
        # A valid number must start with a digit or a sign followed by a digit.
        # It must contain at least one digit.

        is_integer = True
        if '.' in num_text:
            is_integer = False
        if 'e' in num_text.lower():
            is_integer = False

        if not num_text.lstrip('+-').replace('.', '').replace('e', '').replace('E', '').isdigit():
             # Simple check for illegal characters within the run
             pass # This should be handled by the regex, but defensive check.

        # Strict JSON number validation:

        # 1. Must contain at least one digit
        if not any(c.isdigit() for c in num_text):
            raise ScannerError("Invalid number: must contain at least one digit", start_line, start_column)

        # 2. Check for illegal structures (e.g., 1. or .1 or 1.2.3 or 1e)
        parts = re.split(r'([eE][+-]?)', num_text.lstrip('+-'))

        valid = True
        for i, part in enumerate(parts):
            if i % 2 == 0: # Mantissa part
                if not part:
                    continue
                if part == '.' or part == '+.' or part == '-.':
                    valid = False
                    break

                # Check for multiple decimal points
                if part.count('.') > 1:
                    valid = False
                    break

                # Check if it ends with a dot unless followed by E
                if part.endswith('.') and i + 1 < len(parts) and parts[i+1] != '':
                    # If it ends with '.' and the next part is the exponent part
                    # this is fine (e.g., 1.e4), but if the next part is another mantissa (not possible with split)
                    pass

            else: # Exponent part (e.g., 'e4', 'E-2')
                if not part.startswith(('e', 'E')): # Should be impossible if split works correctly
                     valid = False
                     break
                exponent_val = part[1:]
                if not exponent_val.lstrip('+-').isdigit():
                    valid = False
                    break

        if not valid:
            raise ScannerError("Invalid number format", start_line, start_column)

        # Conversion
        if is_integer:
            try:
                # Handle -0 case
                return int(num_text) if num_text != "-0" else 0
            except ValueError:
                 # Should be caught by validation above, but defensive
                 raise ScannerError("Internal error converting number to integer", start_line, start_column)
        else:
            try:
                return float(num_text)
            except ValueError:
                # Should be caught by validation above
                raise ScannerError("Internal error converting number to float", start_line, start_column)


    def scan_literal(self, start_line, start_column):
        start_pos = self.pos

        # Read all contiguous ASCII letters
        while self.peek() is not None and self.peek().isalpha():
            self.advance()

        lit_text = self.text[start_pos: self.pos]

        if lit_text == 'true':
            return Token('TRUE', True, start_line, start_column)
        elif lit_text == 'false':
            return Token('FALSE', False, start_line, start_column)
        elif lit_text == 'null':
            return Token('NULL', None, start_line, start_column)
        else:
            # Invalid literal (e.g., 'trueX' or 'nul')
            raise ScannerError(f"Invalid literal: {lit_text}", start_line, start_column)


    def tokenize(self):
        tokens = []

        # Positional context for errors
        start_line, start_column = 1, 1

        while True:
            self.skip_whitespace()

            if self.pos >= len(self.text):
                tokens.append(Token('EOF', None, self.line, self.column))
                break

            char = self.peek()
            line, column = self.current_pos()

            if char in '{}[]:,':
                self.advance()
                tokens.append(Token(char, None, line, column))

            elif char in '0123456789-':
                # Potential start of a number
                try:
                    token = self.scan_number(line, column)
                    tokens.append(Token('NUMBER', token, line, column))
                except ScannerError as e:
                    raise e # Re-raise scanner error

            elif char.isalpha():
                # Potential start of a literal
                try:
                    token = self.scan_literal(line, column)
                    tokens.append(token)
                except ScannerError as e:
                    raise e # Re-raise scanner error

            elif char == '"':
                # Start of a string
                try:
                    value = self.scan_string(line, column)
                    tokens.append(Token('STRING', value, line, column))
                except ScannerError as e:
                    raise e # Re-raise scanner error

            else:
                # Any other character is an unexpected character error
                self.advance()
                raise ScannerError(f"Unexpected character: '{char}'", line, column)

        return tokens

def tokenize(text: str) -> list[Token]:
    """
    Tokenizes the input text into a list of Token objects.
    """
    scanner = Scanner(text)
    return scanner.tokenize()

