# js/dump.py
import math

class Dumper:
    def __init__(self, obj, indent_level=0, sort_keys=False, ensure_ascii=False, path=None, seen=None):
        self.obj = obj
        self.indent_level = indent_level
        self.sort_keys = sort_keys
        self.ensure_ascii = ensure_ascii
        self.path = path # Used for cycle detection
        self.seen = seen if seen is not None else set()

    def dumps(self, *, indent=None, sort_keys=False, ensure_ascii=False):
        """Public facing entry point."""
        if indent is None:
            return self._dump_internal(indent_level=0, sort_keys=sort_keys, ensure_ascii=ensure_ascii)

        if indent < 0:
            raise ValueError("Indentation level must be non-negative")

        return self._dump_internal(indent_level=indent, sort_keys=sort_keys, ensure_ascii=ensure_ascii)

    def _dump_internal(self, indent_level: int, sort_keys: bool, ensure_ascii: bool):
        """Recursive serialization core."""
        obj = self.obj

        try:
            if isinstance(obj, dict):
                return self._dump_object(obj, indent_level, sort_keys, ensure_ascii)
            elif isinstance(obj, list):
                return self._dump_array(obj, indent_level, sort_keys, ensure_ascii)
            elif isinstance(obj, tuple):
                # Constraint: tuples come back as lists
                return self._dump_array(list(obj), indent_level, sort_keys, ensure_ascii)
            elif obj is None:
                return "null"
            elif isinstance(obj, bool):
                return "true" if obj else "false"
            elif isinstance(obj, int):
                return str(obj)
            elif isinstance(obj, float):
                # Handle special float cases
                if math.isnan(obj):
                    raise ValueError("Cannot serialize NaN")
                if math.isinf(obj):
                    raise ValueError("Cannot serialize Infinity")
                # Use repr(f) to handle standard float precision
                return str(obj) 
            elif isinstance(obj, str):
                return self._dump_string(obj, ensure_ascii)
            else:
                # Catch types not supported by JSON (e.g., datetime objects, custom classes)
                raise TypeError(f"Object of type {type(obj).__name__} is not serializable.")
        except ValueError as e:
            # Re-raise specific serialization errors (NaN/Inf)
            raise e
        except Exception as e:
            # Catch type errors and re-raise
            raise e

    def _dump_string(self, s: str, ensure_ascii: bool):
        parts = []

        if not ensure_ascii:
            # If not enforcing ASCII, write the string raw (including non-ASCII chars)
            # We still need to escape control characters and quotes/backslashes
            escaped_s = s.replace('\\', '\\\\').replace('"', '\\"')

            # Escape short forms
            for char in s:
                if char == '\b':
                    parts.append('\\b')
                elif char == '\f':
                    parts.append('\\f')
                elif char == '\n':
                    parts.append('\\n')
                elif char == '\r':
                    parts.append('\\r')
                elif char == '\t':
                    parts.append('\\t')
                else:
                    # Standard characters are kept as is
                    parts.append(char)

            # Re-apply quote/backslash escaping after processing short forms
            return '"' + "".join(parts).replace('\\', '\\\\').replace('"', '\\"') + '"'

        else:
            # ASCII enforcement: escape all non-ASCII characters, use \u00xx

            def escape_char(char):
                char_ord = ord(char)
                if char_ord < 0x20 or char_ord == '"' or char_ord == '\\':
                    if char == '"': return '\\"'
                    if char == '\\': return '\\\\'

                    if char_ord == 0x08: return '\\b'
                    if char_ord == 0x0C: return '\\f'
                    if char_ord == 0x0A: return '\\n'
                    if char_ord == 0x0D: return '\\r'
                    if char_ord == 0x09: return '\\t'

                    # Standard \u00xx escape for control characters
                    return f'\\u{char_ord:04x}'
                elif char_ord > 0x7F:
                    # Characters above ASCII 127
                    if char_ord <= 0xFFFF:
                        return f'\\u{char_ord:04x}'
                    else:
                        # Surrogate pair required
                        high = 0xD800 + ((char_ord - 0x10000) // 0x400)
                        low = 0xDC00 + ((char_ord - 0x10000) % 0x400)
                        return f'\\u{high:04x}\\u{low:04x}'
                else:
                    return char

            # Apply escaping character by character
            escaped_chars = [escape_char(c) for c in s]
            return '"' + "".join(escaped_chars) + '"'


    def _dump_array(self, arr: list, indent_level: int, sort_keys: bool, ensure_ascii: bool) -> str:
        if not arr:
            return "[]"

        indent = " " * (indent_level * 4)
        inner_indent = " " * ((indent_level + 1) * 4)

        elements = []
        for i, item in enumerate(arr):
            dumped = self._dump_internal(indent_level + 1, sort_keys, ensure_ascii)

            if indent_level > 0:
                # Indented mode: each element gets its own line, preceded by inner_indent
                elements.append(f"{inner_indent}{dumped}")
            else:
                # Compact mode: elements are joined by comma space
                elements.append(dumped)

        if indent_level == 0:
            return "[" + ",".join(elements) + "]"
        else:
            # Indented mode: list starts/ends with bracket on its own line
            body = ",\n".join(elements)
            return f"[\n{body}\n{indent}]"

    def _dump_object(self, obj: dict, indent_level: int, sort_keys: bool, ensure_ascii: bool) -> str:
        if not obj:
            return "{}"

        if sort_keys:
            keys = sorted(obj.keys())
        else:
            keys = list(obj.keys())

        if not all(isinstance(k, str) for k in keys):
            raise TypeError("Dictionary keys must be strings.")

        indent = " " * (indent_level * 4)
        inner_indent = " " * ((indent_level + 1) * 4)

        members = []
        for key in keys:
            value = obj[key]

            # Dump key string
            key_dumped = self._dump_string(key, ensure_ascii)

            # Dump value recursively
            value_dumped = self._dump_internal(indent_level + 1, sort_keys, ensure_ascii)

            # Format: "key": value
            member_string = f"{key_dumped}: {value_dumped}"
            members.append(member_string)

        if indent_level == 0:
            return "{" + ",".join(members) + "}"
        else:
            # Indented mode: object starts/ends with bracket on its own line
            body = ",\n".join(members)
            return f"{\n{body}\n{indent}}"


def dumps(obj, *, indent=None, sort_keys=False, ensure_ascii=False):
    """
    Serializes a Python object into a JSON string.
    """
    # Cycle detection check
    def check_cycle(item, seen_set):
        if item in seen_set:
            return True
        seen_set.add(id(item))

        if isinstance(item, (dict, list, tuple)):
            for sub_item in item:
                if check_cycle(sub_item, seen_set):
                    return True
        return False

    if check_cycle(obj, set()):
        raise ValueError("Object contains a recursive reference (cycle).")

    return Dumper(obj).dumps(indent=indent, sort_keys=sort_keys, ensure_ascii=ensure_ascii)
