# js/parser.py
from js.scanner import tokenize, Token, JSONError

# Define the ParserError type alias
ParserError = JSONError

class Parser:
    def __init__(self, tokens: list[Token], max_depth: int, duplicate_keys: str):
        self.tokens = tokens
        self.pos = 0
        self.tokens_len = len(tokens)
        self.max_depth = max_depth
        self.duplicate_keys = duplicate_keys

    def current_token(self) -> Token:
        if self.pos < self.tokens_len:
            return self.tokens[self.pos]
        return Token('EOF', None, 1, 1) 

    def eat(self, expected_kind: str, expected_value=None):
        token = self.current_token()
        if token.kind != expected_kind:
            raise ParserError(f"Expected '{expected_kind}' but got '{token.kind}'", token.line, token.column)
        if expected_value is not None and token.value != expected_value:
            raise ParserError(f"Expected value '{expected_value}' but got '{token.value}'", token.line, token.column)

        self.pos += 1
        return token

    def parse_value(self, current_depth: int):
        token = self.current_token()

        if token.kind == 'STRING':
            self.eat('STRING')
            return token.value
        elif token.kind == 'NUMBER':
            self.eat('NUMBER')
            return token.value
        elif token.kind == 'TRUE':
            self.eat('TRUE')
            return True
        elif token.kind == 'FALSE':
            self.eat('FALSE')
            return False
        elif token.kind == 'NULL':
            self.eat('NULL')
            return None
        elif token.kind == '{':
            return self.parse_object(current_depth + 1)
        elif token.kind == '[':
            return self.parse_array(current_depth + 1)
        else:
            raise ParserError("Expected value", token.line, token.column)

    def parse_object(self, current_depth: int):
        # Consume '{'
        self.eat('{')
        obj = {}

        # Handle empty object {}
        if self.current_token().kind == '}':
            self.eat('}')
            return obj

        while True:
            # Parse Key (must be a string)
            key_token = self.current_token()
            if key_token.kind != 'STRING':
                raise ParserError("Object key must be a string", key_token.line, key_token.column)
            self.eat('STRING')
            key = key_token.value

            # Check for repeated key policy
            if key in obj:
                if self.duplicate_keys == 'first':
                    # Ignore subsequent occurrences
                    pass 
                elif self.duplicate_keys == 'error':
                    # Raise error pointing at the start of the repeated key
                    raise ParserError(f"Duplicate key found: '{key}'", key_token.line, key_token.column)
                # If 'last', we just proceed (last value wins)

            # Consume ':'
            self.eat(':')

            # Parse Value
            value = self.parse_value(current_depth)

            obj[key] = value

            # Check next token: ',' or '}'
            next_token = self.current_token()

            if next_token.kind == '}':
                self.eat('}')
                return obj
            elif next_token.kind == ',':
                self.eat(',') # Consume ','
            else:
                raise ParserError("Expected ',' or '}' in object", next_token.line, next_token.column)

    def parse_array(self, current_depth: int):
        # Consume '['
        self.eat('[')
        arr = []

        # Handle empty array []
        if self.current_token().kind == ']':
            self.eat(']')
            return arr

        while True:
            # Parse Value
            value = self.parse_value(current_depth)
            arr.append(value)

            # Check next token: ',' or ']'
            next_token = self.current_token()

            if next_token.kind == ']':
                self.eat(']')
                return arr
            elif next_token.kind == ',':
                self.eat(',') # Consume ','
            else:
                raise ParserError("Expected ',' or ']' in array", next_token.line, next_token.column)


def loads(text: str, duplicate_keys: str = 'last', max_depth: int = None, allow_nan: bool = False):
    """
    Parses a JSON string into a Python object.
    """
    if not text.strip():
        raise JSONError("Input cannot be empty", 1, 1)

    if max_depth is not None and (max_depth <= 0):
        raise ValueError("max_depth must be positive or None.")

    # Pass allow_nan to scanner
    tokens = tokenize(text, allow_nan=allow_nan)

    # Initialize parser with strict modes
    parser = Parser(tokens, max_depth, duplicate_keys)

    try:
        # Start parsing at depth 1 (for top-level container)
        result = parser.parse_value(1)
    except JSONError:
        raise # Re-raise scanner/parser errors
    except ValueError as e:
        # Catch custom errors like invalid duplicate keys
        if "duplicate_keys" in str(e):
             raise e
        # Re-raise other ValueErrors (e.g., max_depth failure)
        raise

    # Check if there is trailing junk after the top-level value
    if parser.current_token().kind != 'EOF':
        unexpected_token = parser.current_token()
        raise JSONError("Unexpected characters after JSON value", unexpected_token.line, unexpected_token.column)

    return result

