import math

class Dumper:
    def __init__(self, obj, indent_level=0, sort_keys=False, ensure_ascii=False, allow_nan=False):
        self.obj = obj
        self.indent_level = indent_level
        self.sort_keys = sort_keys
        self.ensure_ascii = ensure_ascii
        self.allow_nan = allow_nan

    def dumps(self, *, indent=None, sort_keys=False, ensure_ascii=False, allow_nan=False):
        """Public facing entry point."""
        if indent is None:
            return self._dump_internal(0, sort_keys, ensure_ascii, allow_nan)

        if indent < 0:
            raise ValueError("Indentation level must be non-negative")

        return self._dump_internal(indent, sort_keys, ensure_ascii, allow_nan)

    def _dump_internal(self, indent_level: int, sort_keys: bool, ensure_ascii: bool, allow_nan: bool):
        """Recursive serialization core."""
        obj = self.obj

        if isinstance(obj, dict):
            return self._dump_object(obj, indent_level, sort_keys, ensure_ascii, allow_nan)
        elif isinstance(obj, list):
            return self._dump_array(obj, indent_level, sort_keys, ensure_ascii, allow_nan)
        elif isinstance(obj, tuple):
            # Constraint: tuples come back as lists
            return self._dump_array(list(obj), indent_level, sort_keys, ensure_ascii, allow_nan)
        elif obj is None:
            return "null"
        elif isinstance(obj, bool):
            return "true" if obj else "false"
        elif isinstance(obj, int):
            return str(obj)
        elif isinstance(obj, float):
            if math.isnan(obj):
                if allow_nan:
                    return "NaN"
                else:
                    raise ValueError("Cannot serialize NaN (allow_nan=False)")
            if math.isinf(obj):
                if allow_nan:
                    return "Infinity" if obj > 0 else "-Infinity"
                else:
                    raise ValueError("Cannot serialize Infinity (allow_nan=False)")

            # Finite float
            # Use str(obj) for compact representation, ensuring it looks like a number
            return str(obj) 
        elif isinstance(obj, str):
            return self._dump_string(obj, ensure_ascii)
        else:
            raise TypeError(f"Object of type {type(obj).__name__} is not serializable.")

    def _dump_string(self, s: str, ensure_ascii: bool):
        if ensure_ascii:
            def escape_char(char):
                char_ord = ord(char)

                if char_ord == '"': return '\\"'
                if char_ord == '\\': return '\\\\'

                if char_ord < 0x20:
                    # Control characters and less than space
                    if char == '\b': return '\\b'
                    if char == '\f': return '\\f'
                    if char == '\n': return '\\n'
                    if char == '\r': return '\\r'
                    if char == '\t': return '\\t'

                    # General control character escape
                    return f'\\u{char_ord:04x}'

                if char_ord > 0xFFFF:
                    # Surrogate pair required
                    high = 0xD800 + ((char_ord - 0x10000) // 0x400)
                    low = 0xDC00 + ((char_ord - 0x10000) % 0x400)
                    return f'\\u{high:04x}\\u{low:04x}'
                else:
                    # BMP character > U+007F
                    return f'\\u{char_ord:04x}'

            escaped_chars = [escape_char(c) for c in s]
            return '"' + "".join(escaped_chars) + '"'
        else:
            # Non-ASCII mode: raw character output, but still escape quotes/backslashes and control chars

            # 1. Escape quotes and backslashes first
            escaped_s = s.replace('\\', '\\\\').replace('"', '\\"')

            parts = []
            for char in s:
                if char == '\b':
                    parts.append('\\b')
                elif char == '\f':
                    parts.append('\\f')
                elif char == '\n':
                    parts.append('\\n')
                elif char == '\r':
                    parts.append('\\r')
                elif char == '\t':
                    parts.append('\\t')
                else:
                    # Use the already escaped version to ensure proper quoting/backslash escaping
                    parts.append(char)

            # Re-apply quote/backslash escaping after processing short forms
            return '"' + "".join(parts).replace('\\', '\\\\').replace('"', '\\"') + '"'

    def _dump_array(self, arr: list, indent_level: int, sort_keys: bool, ensure_ascii: bool, allow_nan: bool) -> str:
        if not arr:
            return "[]"

        indent = " " * (indent_level * 4)
        inner_indent = " " * ((indent_level + 1) * 4)

        elements = []
        for i, item in enumerate(arr):
            dumped = self._dump_internal(indent_level + 1, sort_keys, ensure_ascii, allow_nan)

            if indent_level > 0:
                elements.append(f"{inner_indent}{dumped}")
            else:
                elements.append(dumped)

        if indent_level == 0:
            return "[" + ",".join(elements) + "]"
        else:
            # Indented mode: list starts/ends with bracket on its own line
            body = ",\n".join(elements)
            return f"[\n{body}\n{indent}]"

    def _dump_object(self, obj: dict, indent_level: int, sort_keys: bool, ensure_ascii: bool, allow_nan: bool) -> str:
        if not obj:
            return "{}"

        if sort_keys:
            keys = sorted(obj.keys())
        else:
            keys = list(obj.keys())

        if not all(isinstance(k, str) for k in keys):
            raise TypeError("Dictionary keys must be strings.")

        indent = " " * (indent_level * 4)
        inner_indent = " " * ((indent_level + 1) * 4)

        members = []
        for key in keys:
            value = obj[key]

            # Dump key string
            key_dumped = self._dump_string(key, ensure_ascii)

            # Dump value recursively
            value_dumped = self._dump_internal(indent_level + 1, sort_keys, ensure_ascii, allow_nan)

            # Format: "key": value
            member_string = f"{key_dumped}: {value_dumped}"
            members.append(member_string)

        if indent_level == 0:
            return "{" + ",".join(members) + "}"
        else:
            # Indented mode: object starts/ends with bracket on its own line
            body = ",\n".join(members)
            return f"{\n{body}\n{indent}}"


def dumps(obj, *, indent=None, sort_keys=False, ensure_ascii=False, allow_nan=False):
    """
    Serializes a Python object into a JSON string.
    """

    # Cycle detection check
    def check_cycle(item, seen_set):
        if item in seen_set:
            return True
        seen_set.add(id(item))

        if isinstance(item, (dict, list, tuple)):
            for sub_item in item:
                if check_cycle(sub_item, seen_set):
                    return True
        return False

    if check_cycle(obj, set()):
        raise ValueError("Object contains a recursive reference (cycle).")

    return Dumper(obj).dumps(indent=indent, sort_keys=sort_keys, ensure_ascii=ensure_ascii, allow_nan=allow_nan)
