import re
from functools import total_ordering

class Version:
    """
    Represents a semantic version MAJOR.MINOR.PATCH.
    """
    _VERSION_REGEX = re.compile(r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$")

    def __init__(self, text: str):
        match = self._VERSION_REGEX.match(text)
        if not match:
            raise ValueError(f"Invalid version format: {text}. Must be MAJOR.MINOR.PATCH without leading zeros.")

        parts = tuple(int(p) for p in match.groups())
        self.major, self.minor, self.patch = parts

    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch}"

    def __hash__(self):
        return hash((self.major, self.minor, self.patch))

    def __eq__(self, other):
        if isinstance(other, Version):
            return (self.major, self.minor, self.patch) == \
                   (other.major, other.minor, other.patch)
        return False

    def __lt__(self, other):
        if isinstance(other, Version):
            return (self.major, self.minor, self.patch) < \
                   (other.major, other.minor, other.patch)
        raise TypeError("Cannot compare Version with incompatible type")

    def __le__(self, other):
        return self < other or self == other

    def __gt__(self, other):
        if isinstance(other, Version):
            return (self.major, self.minor, self.patch) > \
                   (other.major, other.minor, other.patch)
        raise TypeError("Cannot compare Version with incompatible type")

    def __ge__(self, other):
        return self > other or self == other

    def __repr__(self):
        return f"Version('{self}')"

class Range:
    """
    Represents a set of version constraints.
    """
    def __init__(self, spec: str):
        self._spec = spec.strip()
        if not self._spec:
            raise ValueError("Range specification cannot be empty.")

        self.constraints = []
        self._parse_spec(spec)

    def _parse_spec(self, spec: str):
        # Clean up whitespace
        parts = [p.strip() for p in spec.split(',')]

        for part in parts:
            if not part:
                raise ValueError("Range spec contains empty constraint.")

            # Regex to capture operator and version: (operator)(version)
            # Operator can be ^, ~, ==, !=, >, <, >=, <=
            match = re.match(r'([!<>~=^]*)([\d.]+)', part)

            if not match:
                raise ValueError(f"Invalid constraint format: {part}")

            op_raw, v_text = match.groups()
            op = op_raw.strip()

            try:
                v = Version(v_text)
            except ValueError as e:
                raise ValueError(f"Bad version in range spec: {part}. {e}")

            # Handle special operators
            if op == '^':
                # Caret operator (Semantic Versioning standard):
                # ^X.Y.Z = >=X.Y.Z, <(X+1).0.0 (if X>0)
                # ^0.Y.Z = >=0.Y.Z, <0.(Y+1).0 (if Y>0)
                # ^0.0.Z = >=0.0.Z, <0.0.(Z+1) (if Z>0)
                if v.major > 0:
                    upper_bound = Version(f"{v.major + 1}.0.0")
                elif v.minor > 0:
                    upper_bound = Version(f"0.{v.minor + 1}.0")
                elif v.patch > 0:
                    upper_bound = Version(f"0.0.{v.patch + 1}")
                else: # ^0.0.0
                    upper_bound = Version("0.0.1")

                # If the starting version was 0.0.0, the range is [0.0.0, 0.0.1)
                if v == Version("0.0.0"):
                    self.constraints.append((v, '>=', None))
                    self.constraints.append((upper_bound, '<', None))
                else:
                    self.constraints.append((v, '>=', None))
                    self.constraints.append((upper_bound, '<', None))

            elif op == '~':
                # Tilde operator: ~=1.2.3 = >=1.2.3, <1.3.0
                if v.major == 0 and v.minor == 0 and v.patch == 0:
                    # ~0.0.0 means exactly 0.0.0 (or maybe 0.0.0, <0.0.1 if we follow general logic)
                    # For simplicity, matching standard library behavior for patch bumps:
                    upper_bound = Version(f"0.0.{v.patch + 1}")
                    self.constraints.append((v, '>=', None))
                    self.constraints.append((upper_bound, '<', None))
                else:
                    # Bump only the minor version, keeping patch at 0
                    upper_bound = Version(f"{v.major}.{v.minor + 1}.0")
                    self.constraints.append((v, '>=', None))
                    self.constraints.append((upper_bound, '<', None))

            elif op == '==':
                self.constraints.append((v, '==', None))
            elif op == '!=':
                self.constraints.append((v, '!=', None))
            elif op == '>':
                self.constraints.append((v, '>', None))
            elif op == '<':
                self.constraints.append((v, '<', None))
            elif op == '>=':
                self.constraints.append((v, '>=', None))
            elif op == '<=':
                self.constraints.append((v, '<=', None))
            else:
                # Should be caught by regex, but safety check
                raise ValueError(f"Unknown operator or badly formatted constraint: {part}")

    def contains(self, v: Version) -> bool:
        """Checks if a given version satisfies all constraints."""
        for constraint_v, operator, _ in self.constraints:
            if not self._check_single_constraint(v, constraint_v, operator):
                return False
        return True

    def _check_single_constraint(self, v: Version, constraint_v: Version, operator: str) -> bool:
        if operator == '==':
            return v == constraint_v
        elif operator == '!=':
            return v != constraint_v
        elif operator == '>':
            return v > constraint_v
        elif operator == '<':
            return v < constraint_v
        elif operator == '>=':
            return v >= constraint_v
        elif operator == '<=':
            return v <= constraint_v
        return False # Should not happen

    def __str__(self):
        # Recreate the canonical string representation for output
        # Note: This is a simplification. In a real system, we'd reconstruct the exact input string.
        # Here, we rely on the stored constraints to represent the effective spec.
        # We will just use the original spec stripped of whitespace for simplicity and consistency with prompt.
        return self._spec

