from typing import Dict, List, Tuple, Optional
from resolve.versions import Version, Range

class PackageIndex:
    """
    Stores all available package versions and their dependencies.
    """
    def __init__(self):
        # {name: {version_str: {dep_name: Range}}}
        self._packages: Dict[str, Dict[str, Dict[str, Range]]] = {}

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None):
        """Adds a specific release version of a package."""
        try:
            v = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Bad version provided for {name}: {e}")

        if name not in self._packages:
            self._packages[name] = {}

        if version_str in self._packages[name]:
            raise ValueError(f"Version {version_str} already exists for package {name}.")

        parsed_requires = {}
        if requires:
            for dep_name, spec_str in requires.items():
                try:
                    parsed_requires[dep_name] = Range(spec_str)
                except ValueError as e:
                    raise ValueError(f"Bad dependency range for {name}@{version_str} on {dep_name}: {e}")

        self._packages[name][version_str] = parsed_requires

    def versions(self, name: str) -> List[Version]:
        """Returns a list of known Version objects of name, newest first."""
        if name not in self._packages:
            return []

        versions = []
        for version_str in self._packages[name].keys():
            try:
                versions.append(Version(version_str))
            except ValueError:
                # Should not happen if input was validated via add()
                pass

        # Sort newest first (descending order)
        return sorted(versions, reverse=True)

    def requirements(self, name: str, version_str: str) -> Dict[str, Range]:
        """
        Returns the dependency map for a specific version.
        Raises KeyError if the version is unknown.
        """
        if name not in self._packages:
            raise KeyError(f"Package {name} not found.")
        if version_str not in self._packages[name]:
            raise KeyError(f"Version {version_str} not found for package {name}.")

        return self._packages[name][version_str]

    @staticmethod
    def from_dict(data: Dict[str, Dict[str, Dict[str, str]]]) -> 'PackageIndex':
        """Builds an index from a nested dictionary structure."""
        index = PackageIndex()
        for name, versions_data in data.items():
            for version_str, requires in versions_data.items():
                parsed_requires = {}
                for dep_name, spec_str in requires.items():
                    try:
                        parsed_requires[dep_name] = Range(spec_str)
                    except ValueError as e:
                        # In a real system, this should raise during setup
                        raise ValueError(f"Error loading index: Bad range for {name}@{version_str} on {dep_name}: {e}")

                index.add(name, version_str, requires)
        return index

