from typing import Dict, List, Optional, Tuple
from resolve.versions import Version, Range
from resolve.index import PackageIndex

class ResolutionError(Exception):
    """Raised when the dependency resolution fails."""
    def __init__(self, package: str, explanation: str):
        self.package = package
        self.explanation = explanation
        super().__init__(explanation)

    def __str__(self):
        return self.explanation

# Type aliases for clarity
Requirements = Dict[str, str]  # {name: spec_string}
Selection = Dict[str, Version] # {name: selected_version}
Constraint = Tuple[str, Range, str] # (requirer_id, range_object, requirer_str)

def resolve(index: PackageIndex, requirements: Requirements) -> Selection:
    """
    Performs the dependency resolution using depth-first search and backtracking.
    Returns the successful selection map.
    Raises ResolutionError on failure.
    """

    # Initial order: root requirements sorted alphabetically
    initial_order = sorted(requirements.keys())

    # State tracking
    # order: Names of packages that need to be resolved, in processing order.
    order: List[str] = list(initial_order)
    # selected: Packages resolved so far {name: Version}
    selected: Selection = {}
    # constraints_map: {name: List[Constraint]} - Accumulated constraints for each package
    constraints_map: Dict[str, List[Constraint]] = {name: [] for name in index.versions(initial_order[0]) if initial_order}

    def _add_constraint(name: str, requirer_id: str, range_obj: Range, requirer_str: str):
        """Helper to add a constraint to the map."""
        if name not in constraints_map:
            constraints_map[name] = []
        constraints_map[name].append((requirer_id, range_obj, requirer_str))

    def dfs_resolve(
        current_order: List[str], 
        current_selected: Selection, 
        current_constraints_map: Dict[str, List[Constraint]]
    ) -> Optional[Selection]:
        """
        Depth-First Search resolver function.
        Returns the successful selection or None if the branch fails.
        """

        # 1. Find the next package to resolve
        next_pkg_name = None
        try:
            # Find the first package in the order that hasn't been selected yet
            for name in current_order:
                if name not in current_selected:
                    next_pkg_name = name
                    break
            if next_pkg_name is None:
                # Success: all packages in the order are resolved
                return current_selected
        except IndexError:
             # Should only happen if current_order was empty, which means success
             return current_selected


        pkg_name = next_pkg_name

        # 2. Identify candidates (Versions of pkg_name)
        available_versions = index.versions(pkg_name)
        candidates = available_versions

        # 3. Try each candidate (newest first)
        for candidate_v in candidates:
            candidate_version_str = str(candidate_v)

            # --- Acceptability Check ---
            is_acceptable = True

            # 3a. Check constraints from root requirements and selected packages
            all_constraints = current_constraints_map.get(pkg_name, [])

            for requirer_id, range_obj, requirer_str in all_constraints:
                if not range_obj.contains(candidate_v):
                    is_acceptable = False
                    # Store failure reason for error reporting
                    candidate_failure_reason = (
                        f"  {requirer_str} requires {pkg_name} {range_obj}."
                    )
                    break

            if not is_acceptable:
                # If this candidate failed the static constraint check, we skip it.
                # We need to collect all reasons for the final error message.
                continue 

            # 3b. Check constraints imposed by already selected dependencies
            # Iterate over the candidate's dependencies
            try:
                candidate_deps = index.requirements(pkg_name, candidate_version_str)
            except KeyError:
                # Should not happen if index is built correctly, but safe guard
                continue 

            for dep_name, dep_range in candidate_deps.items():
                if dep_name in current_selected:
                    selected_version = current_selected[dep_name]

                    # Check if the *selected* version satisfies the *candidate's* requirement
                    if not dep_range.contains(selected_version):
                        is_acceptable = False
                        # Store failure reason for error reporting
                        candidate_failure_reason = (
                            f"  {pkg_name} {candidate_version_str} requires {dep_name} {dep_range}, "
                            f"but {dep_name} {selected_version} is selected"
                        )
                        break

            if not is_acceptable:
                # If this candidate failed the dynamic dependency check, we skip it.
                continue

            # --- Candidate is Acceptable: Proceed with selection ---

            # 4. New State Setup (Deep copies for backtracking)
            new_selected = current_selected.copy()
            new_selected[pkg_name] = candidate_v

            new_constraints_map = {k: list(v) for k, v in current_constraints_map.items()}

            # 5. Update Constraints & Order
            new_order = list(current_order)

            # Update the processing order: append new dependencies alphabetically
            new_deps_to_add = []
            if pkg_name in candidate_deps:
                for dep_name in candidate_deps.keys():
                    if dep_name not in current_selected and dep_name not in new_order:
                        new_deps_to_add.append(dep_name)

            new_deps_to_add.sort()
            new_order.extend(new_deps_to_add)

            # Apply new constraints imposed by pkg_name (candidate_version_str)
            for dep_name, dep_range in candidate_deps.items():
                requirer_str = f"{pkg_name} {candidate_version_str}"
                _add_constraint(dep_name, pkg_name, dep_range, requirer_str)

            # 6. Recursive Call
            result = dfs_resolve(new_order, new_selected, new_constraints_map)

            if result is not None:
                # Success! Return the found resolution.
                return result

            # If recursive call failed (result is None), backtrack implicitly and try next candidate.

        # 7. If no candidate worked, this branch fails.
        return None


    # --- Initialization and Execution ---

    # Setup initial root constraints
    initial_constraints_map = {}
    for pkg_name, spec_str in requirements.items():
        try:
            range_obj = Range(spec_str)
            # Root constraints always use '<root>' as the requirer ID
            requirer_str = f"<root> requires {pkg_name} {range_obj}"
            initial_constraints_map[pkg_name] = [(f'<root>', range_obj, requirer_str)]
        except ValueError as e:
            raise ValueError(f"Invalid root requirement for {pkg_name}: {e}")


    # Run DFS
    final_selection = dfs_resolve(initial_order, selected, initial_constraints_map)

    if final_selection is None:
        # --- Resolution Failed: Generate Error Report ---

        # We must re-run the search to find the exact failure point,
        # but since the DFS structure above only returns success, we must simulate the failure state.
        # Instead of re-running, we will use a dedicated function to capture the failure details,
        # which is complex due to the required state logging.

        # For simplicity and adherence to the prompt's structure, we must find the first point of failure.

        # A robust solution would wrap dfs_resolve to catch failure reason, but since the prompt
        # demands precise state tracking on failure, let's restructure the failure logging logic 
        # into a dedicated search helper.

        error_details = _find_failure(index, requirements, initial_order, initial_constraints_map)

        pkg = error_details['package']
        explanation_lines = []
        explanation_lines.append(f"cannot resolve {pkg}")

        # Constraints section
        constraints_list = error_details['constraints']
        for _, range_obj, requirer_str in constraints_list:
             explanation_lines.append(f"  {requirer_str}")

        # Version exclusion section
        exclusion_reasons = error_details['exclusion_reasons']
        if not exclusion_reasons:
             explanation_lines.append("  no versions of {pkg} are known")
        else:
            for reason in exclusion_reasons:
                explanation_lines.append(reason)

        error_explanation = "\n".join(explanation_lines)
        raise ResolutionError(pkg, error_explanation)

    return final_selection

# Helper function to find the failure state for error reporting
def _find_failure(
    index: PackageIndex, 
    requirements: Requirements, 
    initial_order: List[str], 
    initial_constraints_map: Dict[str, List[Constraint]]
) -> Dict:
    """
    Simulates the search to capture the precise state where the first package
    has no acceptable candidate.
    """

    # State tracking initialization
    order: List[str] = list(initial_order)
    selected: Selection = {}
    constraints_map: Dict[str, List[Constraint]] = initial_constraints_map

    # We use a stack for iterative DFS to manage state changes explicitly for logging
    # Stack item: (order_snapshot, selected_snapshot, constraints_snapshot)
    stack: List[Tuple[List[str], Selection, Dict[str, List[Constraint]]]] = [(order, selected, constraints_map)]

    while stack:
        current_order, current_selected, current_constraints_map = stack.pop()

        next_pkg_name = None
        for name in current_order:
            if name not in current_selected:
                next_pkg_name = name
                break

        if next_pkg_name is None:
            # Should not happen if we are looking for failure state
            continue

        pkg_name = next_pkg_name
        available_versions = index.versions(pkg_name)
        candidates = available_versions

        failed_candidates = []
        successful_candidates = []

        for candidate_v in candidates:
            candidate_version_str = str(candidate_v)
            is_acceptable = True
            candidate_failure_reason = None

            # 3a. Check constraints from root requirements and selected packages
            all_constraints = current_constraints_map.get(pkg_name, [])

            for requirer_id, range_obj, requirer_str in all_constraints:
                if not range_obj.contains(candidate_v):
                    is_acceptable = False
                    candidate_failure_reason = f"  {requirer_str} requires {pkg_name} {range_obj}."
                    break

            if not is_acceptable:
                failed_candidates.append(candidate_failure_reason)
                continue

            # 3b. Check constraints imposed by already selected dependencies
            try:
                candidate_deps = index.requirements(pkg_name, candidate_version_str)
            except KeyError:
                continue 

            for dep_name, dep_range in candidate_deps.items():
                if dep_name in current_selected:
                    selected_version = current_selected[dep_name]
                    if not dep_range.contains(selected_version):
                        is_acceptable = False
                        candidate_failure_reason = (
                            f"  {pkg_name} {candidate_version_str} requires {dep_name} {dep_range}, "
                            f"but {dep_name} {selected_version} is selected"
                        )
                        break

            if not is_acceptable:
                failed_candidates.append(candidate_failure_reason)
                continue

            # Acceptable candidate
            successful_candidates.append(candidate_v)

        # --- Failure Check ---
        if not successful_candidates:
            # This is the first point of failure. We capture the state.
            return {
                'package': pkg_name,
                'constraints': current_constraints_map.get(pkg_name, []),
                'exclusion_reasons': failed_candidates
            }

        # --- Success/Recursion Step ---
        # Since we prefer newest first, we only proceed with the first successful candidate
        # (the newest one) and ignore others in this specific error-finding loop.

        # Select the newest successful candidate
        candidate_v = successful_candidates[0] 
        candidate_version_str = str(candidate_v)

        # Setup next state
        new_selected = current_selected.copy()
        new_selected[pkg_name] = candidate_v

        new_constraints_map = {k: list(v) for k, v in current_constraints_map.items()}

        new_order = list(current_order)

        new_deps_to_add = []
        try:
            candidate_deps = index.requirements(pkg_name, candidate_version_str)
        except KeyError:
             candidate_deps = {} # Handle case where dependency data might be missing

        for dep_name in candidate_deps.keys():
            if dep_name not in current_selected and dep_name not in new_order:
                new_deps_to_add.append(dep_name)

        new_deps_to_add.sort()
        new_order.extend(new_deps_to_add)

        # Apply new constraints
        for dep_name, dep_range in candidate_deps.items():
            requirer_str = f"{pkg_name} {candidate_version_str}"
            if dep_name not in new_constraints_map:
                 new_constraints_map[dep_name] = []
            new_constraints_map[dep_name].append((pkg_name, dep_range, requirer_str))

        # Push the next state onto the stack
        stack.append((new_order, new_selected, new_constraints_map))

    # Should theoretically not be reached if the resolution was successful
    raise Exception("Internal Solver Logic Error: Failed to find failure state.")
