from dataclasses import dataclass
from typing import Dict, Any, Tuple

DIRECTIONS = ('north', 'south', 'east', 'west', 'up', 'down')

@dataclass(frozen=True)
class Item:
    id: str
    name: str
    description: str
    portable: bool = True

@dataclass(frozen=True)
class Room:
    id: str
    name: str
    description: str
    exits: Dict[str, str]
    items: Tuple[str, ...]

class WorldError(ValueError):
    pass

class World:
    def __init__(self, start: str, rooms: Dict[str, Room], items: Dict[str, Item]):
        self.start = start
        self.rooms = rooms
        self.items = items

    @staticmethod
    def from_dict(data: Dict[str, Any]) -> 'World':
        try:
            start_id = data['start']
            room_data = data['rooms']
            item_data = data['items']
        except KeyError as e:
            raise WorldError(f"Missing required key in world dictionary: {e}")

        # 1. Check start room
        if start_id not in room_data:
            raise WorldError(f"Start room '{start_id}' not found.")

        rooms: Dict[str, Room] = {}
        item_definitions: Dict[str, Item] = {}
        room_item_counts: Dict[str, int] = {} # Tracks item ID occurrences per room

        # 2. Process Items
        all_item_ids = set()
        for item_id, item_data in item_data.items():
            if item_id in all_item_ids:
                # Should not happen if item IDs are unique in the dictionary structure
                # But good practice to check if we were merging data.
                pass 

            portable = item_data.get('portable', True)
            item = Item(
                id=item_id,
                name=item_data['name'],
                description=item_data['description'],
                portable=portable
            )
            item_definitions[item_id] = item
            all_item_ids.add(item_id)
            room_item_counts[item_id] = 0 # Initialize count

        # 3. Process Rooms
        for room_id, r_data in room_data.items():
            # Check essential room fields
            if 'name' not in r_data or 'description' not in r_data:
                raise WorldError(f"Room '{room_id}' must have 'name' and 'description'.")

            # Initialize room item list
            initial_item_ids = r_data.get('items', [])
            initial_item_ids = [i for i in initial_item_ids if i] # Filter out empty strings

            # Check item validity and count
            for item_id in initial_item_ids:
                if item_id not in item_definitions:
                    raise WorldError(f"Room '{room_id}' lists unknown item ID '{item_id}'.")

                room_item_counts[item_id] += 1

            if room_item_counts[item_id] > 1:
                 # This check handles items being listed multiple times across different rooms 
                 # IF we were tracking global counts, but the requirement is: 
                 # "an item is listed more than once (in one room or across rooms)."
                 # Let's adjust the tracking to check if the total count exceeds 1.
                 # Since we are iterating rooms sequentially, we'll check the total count at the end.
                 pass # We track the total count of usage below.

            # Process exits
            exits: Dict[str, str] = r_data.get('exits', {})
            for direction, target_id in exits.items():
                if direction.lower() not in (d.lower() for d in DIRECTIONS):
                    raise WorldError(f"Room '{room_id}' uses unknown direction '{direction}'.")
                if target_id not in room_data:
                    raise WorldError(f"Room '{room_id}' exits to unknown room '{target_id}'.")

            rooms[room_id] = Room(
                id=room_id,
                name=r_data['name'],
                description=r_data['description'],
                exits={d.lower(): target_id for d in exits},
                items=tuple(initial_item_ids)
            )

        # Final check: ensure no item is listed more than once across the entire world
        total_item_counts = {item_id: 0 for item_id in all_item_ids}
        for room in rooms.values():
            for item_id in room.items:
                if item_id not in total_item_counts:
                     # This should only happen if an item was defined but never listed, which is fine.
                     continue
                total_item_counts[item_id] += 1

        for item_id, count in total_item_counts.items():
            if count > 1:
                raise WorldError(f"Item '{item_id}' is listed more than once across the world.")


        return World(start_id, rooms, item_definitions)
