from typing import NamedTuple
from dataclasses import dataclass

@dataclass(frozen=True)
class Command:
    verb: str
    arg: str | None

class ParseError(ValueError):
    pass

def normalize_tokens(tokens: list[str]) -> tuple[list[str], list[str]]:
    """
    Removes articles ('the', 'a', 'an') after the first word.
    Returns (processed_tokens, articles_removed_count).
    """
    if not tokens:
        return [], 0

    # Keep the first token as is
    processed_tokens = [tokens[0]]

    # Process subsequent tokens
    for i in range(1, len(tokens)):
        token = tokens[i]
        lower_token = token.lower()
        if lower_token in ('the', 'a', 'an'):
            # Skip the article
            continue
        processed_tokens.append(token)

    return processed_tokens, 0


def parse(line: str) -> Command:
    line = line.strip().lower()

    if not line:
        raise ParseError("Say something.")

    tokens = line.split()

    if not tokens:
        raise ParseError("Say something.")

    first_word = tokens[0]

    # Map single letters to full directions
    if first_word in ('n', 's', 'e', 'w', 'u', 'd'):
        direction_map = {'n': 'north', 's': 'south', 'e': 'east', 'w': 'west', 'u': 'up', 'd': 'down'}
        full_direction = direction_map[first_word]

        # Check for "go DIR"
        if len(tokens) > 1:
             # If the input was 'go n', first_word is 'go'. This block shouldn't execute.
             # If input was 'n', it is handled here.
             return Command('go', full_direction)
        # If input was just 'n' (or similar)
        return Command('go', full_direction)

    # Handle multi-word commands starting with 'go'
    if first_word == 'go':
        if len(tokens) == 1:
            raise ParseError("Go where?")

        # Check if the argument is a direction
        arg = ' '.join(tokens[1:]).lower()
        if arg in ('north', 'south', 'east', 'west', 'up', 'down'):
            return Command('go', arg)
        else:
            raise ParseError(f'"{arg}" is not a direction.')

    # Handle Look/Examine/Inventory
    if first_word in ('look', 'l', 'examine', 'x'):
        if len(tokens) == 1:
            return Command('look', None)
        else:
            # Look X, Examine X, Look at X
            return Command('look', ' '.join(tokens[1:]))

    if first_word in ('inventory', 'inv', 'i'):
        return Command('inventory', None)

    # Handle Take/Get/Drop
    if first_word in ('take', 'get'):
        if len(tokens) == 1:
            raise ParseError("Take what?")
        # Process arguments: remove articles after the first word
        processed_tokens = [tokens[0]]
        processed_tokens, _ = normalize_tokens(tokens)
        arg = ' '.join(processed_tokens[1:])
        return Command('take', arg)

    if first_word == 'drop':
        if len(tokens) == 1:
            raise ParseError("Drop what?")
        # Process arguments
        processed_tokens = [tokens[0]]
        processed_tokens, _ = normalize_tokens(tokens)
        arg = ' '.join(processed_tokens[1:])
        return Command('drop', arg)

    # Handle unknown word
    raise ParseError(f'I don\'t know the word "{first_word}".')
