import json
from typing import Dict, List, Any
import os

from adventure.world import World, Room, Item, DIRECTIONS, WorldError
from adventure.parser import Command, ParseError

class SaveError(ValueError):
    pass

class Game:
    def __init__(self, world: World):
        self.world = world
        self.room_id = world.start
        self.inventory: List[str] = []
        self.moves: int = 0

        # Initialize room items list (maintaining order)
        # Items are loaded in the order they appear in the world definition
        self._room_item_order: Dict[str, List[str]] = {
            room_id: list(room.items) 
            for room_id, room in world.rooms.items()
        }

        # Item IDs that are currently in the room when the game starts
        self._current_room_items = list(world.rooms[self.room_id].items)

    def items_in(self, room_id: str) -> List[str]:
        """Returns a copy of item IDs currently in the specified room."""
        return list(self._room_item_order.get(room_id, []))

    def do(self, line: str) -> str:
        try:
            command: Command = self.world.parser.parse(line) # Assuming world has access to parser, or import directly
            # For clean separation, we must re-import/access the parser directly.
            from adventure.parser import parse
            command: Command = parse(line)
        except ParseError as e:
            return str(e)

        verb = command.verb
        arg = command.arg

        if verb == 'look':
            return self._handle_look(arg)
        elif verb == 'go':
            return self._handle_go(arg)
        elif verb == 'take':
            return self._handle_take(arg)
        elif verb == 'drop':
            return self._handle_drop(arg)
        elif verb == 'inventory':
            return self._handle_inventory()
        else:
            # Should not happen if parser is correct
            return "Unknown command."

    def _get_item_data(self, item_id: str) -> Item | None:
        """Gets the Item object from the world definition."""
        return self.world.items.get(item_id)

    def _match_item(self, arg: str) -> tuple[Item | None, str | None]:
        """
        Searches for an item matching the argument (ID or name).
        Searches room first, then inventory.
        Returns (Item object, item_id).
        """
        if not arg:
            return None, None

        # 1. Search Room
        for item_id in self._current_room_items:
            item = self._get_item_data(item_id)
            if item:
                if arg == item_id or arg == item.name.lower():
                    return item, item_id

        # 2. Search Inventory
        for item_id in self.inventory:
            item = self._get_item_data(item_id)
            if item:
                if arg == item_id or arg == item.name.lower():
                    return item, item_id

        return None, None

    def _handle_look(self, arg: str | None) -> str:
        room = self.world.rooms[self.room_id]

        if arg is None:
            # Handle 'look'

            # 1. Name
            lines = [room.name]
            # 2. Description
            lines.append(room.description)

            # 3. Exits
            exits_list = []
            for direction in DIRECTIONS:
                if direction in room.exits:
                    exits_list.append(direction)

            exits_str = f"Exits: {', '.join(exits_list)}." if exits_list else "Exits: none."
            lines.append(exits_str)

            # 4. Items
            room_items_ids = self.items_in(self.room_id)
            if room_items_ids:
                item_names = [self._get_item_data(i).name for i in room_items_ids]
                lines.append(f"You see: {', '.join(item_names)}.")

            return "\n".join(lines)

        else:
            # Handle 'look X'
            item, item_id = self._match_item(arg)

            if item:
                # Determine if it was found in the room or inventory
                if item_id in self.items_in(self.room_id):
                     # Found in room
                     return item.description
                elif item_id in self.inventory:
                     # Found in inventory
                     return item.description
            else:
                return f"You see no {arg} here."


    def _handle_go(self, direction: str) -> str:
        room = self.world.rooms[self.room_id]

        if direction in room.exits:
            next_room_id = room.exits[direction]
            self.room_id = next_room_id
            self.moves += 1

            # Update current items list for the new room
            self._current_room_items = list(self.world.rooms[self.room_id].items)

            # Return the look text of the new room
            return self._handle_look(None)
        else:
            return "You can't go that way."

    def _handle_take(self, arg: str) -> str:
        item, item_id = self._match_item(arg)

        if not item:
            return f"You see no {arg} here."

        # Check if in Room
        if item_id in self.items_in(self.room_id):
            if not item.portable:
                return f"You can't take the {item.name}."

            # Move item from room to inventory
            self.inventory.append(item_id)
            self._current_room_items.remove(item_id)

            # Update the room's item list (remove item_id)
            try:
                 self._room_item_order[self.room_id].remove(item_id)
            except ValueError:
                 # Should not happen if _current_room_items was correct
                 pass

            return f"Taken: {item.name}."

        # Check if in Inventory
        elif item_id in self.inventory:
            return f"You already have the {item.name}."

        # Fallback (should be unreachable)
        return f"You see no {arg} here."


    def _handle_drop(self, arg: str) -> str:
        item, item_id = self._match_item(arg)

        if not item:
            return "You aren't carrying that."

        # Check if in Inventory
        if item_id in self.inventory:
            # Move item from inventory to room
            self.inventory.remove(item_id)
            self._current_room_items.append(item_id)

            # Update the room's item list (append item_id)
            self._room_item_order[self.room_id].append(item_id)

            return f"Dropped: {item.name}."

        # If it's in the room, we do nothing (drop implies carrying)
        return "You aren't carrying that."


    def _handle_inventory(self) -> str:
        if not self.inventory:
            return "You are carrying nothing."

        item_names = []
        for item_id in self.inventory:
            item = self._get_item_data(item_id)
            if item:
                item_names.append(item.name)

        return f"You are carrying: {', '.join(item_names)}."


    def save(self) -> str:
        """Returns a JSON string of the current game state."""

        # Create the item list map for saving: Room ID -> List[Item ID]
        items_state: Dict[str, List[str]] = {}
        for room_id, room in self.world.rooms.items():
            # We only save items that are currently *in* the room, 
            # not items that exist globally but aren't listed.

            # Note: Since we maintain _room_item_order, we use that list.
            items_state[room_id] = self._room_item_order[room_id]

        state = {
            "version": 1,
            "room": self.room_id,
            "inventory": self.inventory,
            "items": items_state,
            "moves": self.moves
        }
        return json.dumps(state)

    @classmethod
    def load(cls, world: World, text: str) -> 'Game':
        """Loads a game state from a JSON string."""
        try:
            data: Dict[str, Any] = json.loads(text)
        except json.JSONDecodeError:
            raise SaveError("Invalid JSON format.")

        # Validate structure and version
        if not isinstance(data, dict):
            raise SaveError("Saved data must be a JSON object.")
        if data.get('version') != 1:
            raise SaveError("Unsupported save file version.")

        try:
            saved_room_id = data['room']
            saved_inventory: List[str] = data['inventory']
            saved_items: Dict[str, List[str]] = data['items']
            saved_moves = data['moves']
        except KeyError as e:
            raise SaveError(f"Missing required key in save file: {e}.")

        # Validate data integrity
        if saved_moves < 0 or not isinstance(saved_moves, int):
            raise SaveError("Moves must be a non-negative integer.")

        if saved_room_id not in world.rooms:
            raise SaveError(f"Room ID '{saved_room_id}' not found in world.")

        # Check for item existence and uniqueness
        seen_item_ids = set()

        # Check inventory items
        for item_id in saved_inventory:
            if item_id not in world.items:
                raise SaveError(f"Inventory contains unknown item ID '{item_id}'.")
            if item_id in seen_item_ids:
                raise SaveError(f"Item ID '{item_id}' appears more than once in inventory.")
            seen_item_ids.add(item_id)

        # Check room items
        for room_id, item_list in saved_items.items():
            if room_id not in world.rooms:
                raise SaveError(f"Room ID '{room_id}' in save file not found in world.")

            for item_id in item_list:
                if item_id not in world.items:
                    raise SaveError(f"Room '{room_id}' contains unknown item ID '{item_id}'.")
                if item_id in seen_item_ids:
                    raise SaveError(f"Item ID '{item_id}' appears more than once across inventory and rooms.")
                seen_item_ids.add(item_id)

        # Create the game instance
        game = cls(world)
        game.room_id = saved_room_id
        game.inventory = saved_inventory
        game.moves = saved_moves

        # Reconstruct room item state based on loaded data
        game._room_item_order = {
            room_id: item_list for room_id, item_list in saved_items.items()
        }
        # We must also ensure the current room items list is properly set
        game._current_room_items = game.items_in(game.room_id)

        return game
