from dataclasses import dataclass
from typing import Dict, Any, Tuple, List, Union

DIRECTIONS = ('north', 'south', 'east', 'west', 'up', 'down')
ExitTarget = Union[str, Dict[str, Any]]

@dataclass(frozen=True)
class Item:
    id: str
    name: str
    description: str
    portable: bool = True
    treasure: int = 0

@dataclass(frozen=True)
class Room:
    id: str
    name: str
    description: str
    exits: Dict[str, ExitTarget]
    items: Tuple[str, ...]
    locks: Dict[str, str] # direction -> key item id

class WorldError(ValueError):
    pass

class World:
    def __init__(self, start: str, rooms: Dict[str, Room], items: Dict[str, Item]):
        self.start = start
        self.rooms = rooms
        self.items = items

    @staticmethod
    def from_dict(data: Dict[str, Any]) -> 'World':
        try:
            start_id = data['start']
            room_data = data['rooms']
            item_data = data['items']
        except KeyError as e:
            raise WorldError(f"Missing required key in world dictionary: {e}")

        if start_id not in room_data:
            raise WorldError(f"Start room '{start_id}' not found.")

        rooms: Dict[str, Room] = {}
        item_definitions: Dict[str, Item] = {}

        # Map of item ID to its total usage count
        total_item_counts: Dict[str, int] = {} 

        # 1. Process Items
        for item_id, item_data in item_data.items():
            treasure = item_data.get('treasure', 0)
            if not isinstance(treasure, int) or treasure < 0:
                raise WorldError(f"Item '{item_id}' treasure must be a non-negative integer.")

            portable = item_data.get('portable', True)
            item = Item(
                id=item_id,
                name=item_data['name'],
                description=item_data['description'],
                portable=portable,
                treasure=treasure
            )
            item_definitions[item_id] = item
            total_item_counts[item_id] = 0

        # 2. Process Rooms
        for room_id, r_data in room_data.items():
            if 'name' not in r_data or 'description' not in r_data:
                raise WorldError(f"Room '{room_id}' must have 'name' and 'description'.")

            initial_item_ids = r_data.get('items', [])
            initial_item_ids = [i for i in initial_item_ids if i]

            # Process exits and locks
            raw_exits: Dict[str, ExitTarget] = r_data.get('exits', {})
            exits: Dict[str, str] = {} # direction -> target_room_id (only for unlocked exits)
            locks: Dict[str, str] = {} # direction -> key item id

            for direction, target in raw_exits.items():
                direction = direction.lower()
                if direction not in DIRECTIONS:
                    raise WorldError(f"Room '{room_id}' uses unknown direction '{direction}'.")

                if isinstance(target, str):
                    # Plain room exit
                    target_room_id = target
                    exits[direction] = target_room_id
                elif isinstance(target, dict):
                    # Locked exit dict
                    if 'to' not in target or 'key' not in target:
                        raise WorldError(f"Locked exit in '{room_id}' must specify 'to' and 'key'.")

                    target_room_id = target['to']
                    key_id = target['key']

                    if target_room_id not in room_data:
                        raise WorldError(f"Locked exit in '{room_id}' leads to unknown room '{target_room_id}'.")
                    if key_id not in item_definitions:
                        raise WorldError(f"Locked exit in '{room_id}' requires unknown key item '{key_id}'.")

                    exits[direction] = target_room_id
                    locks[direction] = key_id
                else:
                    raise WorldError(f"Exit target in '{room_id}' must be a string or dictionary.")

            # Check items
            for item_id in initial_item_ids:
                if item_id not in item_definitions:
                    raise WorldError(f"Room '{room_id}' lists unknown item ID '{item_id}'.")
                total_item_counts[item_id] += 1

            if any(count > 1 for count in total_item_counts.values()):
                 # This check is redundant because we check after all rooms, but good safety net.
                 pass 

            rooms[room_id] = Room(
                id=room_id,
                name=r_data['name'],
                description=r_data['description'],
                exits=exits,
                items=tuple(initial_item_ids),
                locks=locks
            )

        # Final check: ensure no item is listed more than once across the entire world
        for item_id, count in total_item_counts.items():
            if count > 1:
                raise WorldError(f"Item '{item_id}' is listed more than once across the world.")

        return World(start_id, rooms, item_definitions)
