from typing import NamedTuple
from dataclasses import dataclass

@dataclass(frozen=True)
class Command:
    verb: str
    arg: str | None

class ParseError(ValueError):
    pass

def normalize_tokens(tokens: list[str]) -> tuple[list[str], list[str]]:
    """
    Removes articles ('the', 'a', 'an') after the first word.
    Returns (processed_tokens).
    """
    if not tokens:
        return []

    processed_tokens = [tokens[0]]

    for i in range(1, len(tokens)):
        token = tokens[i]
        lower_token = token.lower()
        if lower_token in ('the', 'a', 'an'):
            continue
        processed_tokens.append(token)

    return processed_tokens


def parse(line: str) -> Command:
    line = line.strip().lower()

    if not line:
        raise ParseError("Say something.")

    tokens = line.split()

    if not tokens:
        raise ParseError("Say something.")

    first_word = tokens[0]

    # Handle single letter directions
    if first_word in ('n', 's', 'e', 'w', 'u', 'd'):
        direction_map = {'n': 'north', 's': 'south', 'e': 'east', 'w': 'west', 'u': 'up', 'd': 'down'}
        full_direction = direction_map[first_word]
        return Command('go', full_direction)

    # Handle 'score' command
    if first_word == 'score':
        if len(tokens) > 1:
            raise ParseError("I don't understand that.")
        return Command('score', None)

    # Handle Look/Examine/Inventory
    if first_word in ('look', 'l', 'examine', 'x'):
        if len(tokens) == 1:
            return Command('look', None)
        else:
            return Command('look', ' '.join(tokens[1:]))

    if first_word in ('inventory', 'inv', 'i'):
        return Command('inventory', None)

    # Handle Go
    if first_word == 'go':
        if len(tokens) == 1:
            raise ParseError("Go where?")

        arg_line = ' '.join(tokens[1:]).lower()
        if arg_line in ('north', 'south', 'east', 'west', 'up', 'down'):
            return Command('go', arg_line)
        else:
            raise ParseError(f'"{arg_line}" is not a direction.')

    # Handle Take/Get/Drop/Use
    if first_word in ('take', 'get', 'drop', 'use'):
        if len(tokens) == 1:
            if first_word == 'take':
                raise ParseError("Take what?")
            elif first_word == 'drop':
                raise ParseError("Drop what?")
            elif first_word == 'use':
                raise ParseError("Use what?")
            # For 'score', this case is already handled above, but kept for completeness
        else:
            # Process arguments: remove articles after the first word
            processed_tokens = normalize_tokens(tokens)
            arg = ' '.join(processed_tokens[1:])

            if first_word == 'use':
                return Command('use', arg)
            elif first_word == 'take':
                return Command('take', arg)
            elif first_word == 'drop':
                return Command('drop', arg)

    # Handle unknown word
    raise ParseError(f'I don\'t know the word "{first_word}".')
