import json
from typing import Dict, List, Any
from collections import OrderedDict
import copy

from adventure.world import World, Room, Item, DIRECTIONS, WorldError
from adventure.parser import parse, Command, ParseError

class SaveError(ValueError):
    pass

class Game:
    def __init__(self, world: World):
        self.world = world
        self.room_id: str = world.start
        self.inventory: List[str] = []
        self.moves: int = 0

        # State tracking
        self.score: int = 0
        self.visited: set[str] = set()
        self.scored: set[str] = set()

        # Tracking unlocked exits: (room_id, direction)
        # We use a set of tuples for easy management
        self.unlocked: set[tuple[str, str]] = set() 

        # Room item order tracking
        self._room_item_order: Dict[str, List[str]] = {}
        self._current_room_items: List[str] = []

        # Initialize state
        self.visited.add(self.room_id)

        self._initialize_room_items()

    def _initialize_room_items(self):
        """Initializes the item list for the starting room and all rooms."""
        for room_id, room in self.world.rooms.items():
            item_list = list(room.items)
            self._room_item_order[room_id] = item_list

        self._current_room_items = self._room_item_order[self.room_id]

    def items_in(self, room_id: str) -> List[str]:
        """Returns a copy of item IDs currently in the specified room."""
        return list(self._room_item_order.get(room_id, []))

    def _get_item_data(self, item_id: str) -> Item | None:
        """Gets the Item object from the world definition."""
        return self.world.items.get(item_id)

    def _match_item(self, arg: str) -> tuple[Item | None, str | None]:
        """
        Searches for an item matching the argument (ID or name).
        Searches room first, then inventory.
        Returns (Item object, item_id).
        """
        if not arg:
            return None, None

        # 1. Search Room
        for item_id in self._current_room_items:
            item = self._get_item_data(item_id)
            if item:
                if arg == item_id or arg == item.name.lower():
                    return item, item_id

        # 2. Search Inventory
        for item_id in self.inventory:
            item = self._get_item_data(item_id)
            if item:
                if arg == item_id or arg == item.name.lower():
                    return item, item_id

        return None, None

    def do(self, line: str) -> str:
        try:
            command: Command = parse(line)
        except ParseError as e:
            return str(e)

        verb = command.verb
        arg = command.arg

        if verb == 'look':
            return self._handle_look(arg)
        elif verb == 'go':
            return self._handle_go(arg)
        elif verb == 'take':
            return self._handle_take(arg)
        elif verb == 'drop':
            return self._handle_drop(arg)
        elif verb == 'inventory':
            return self._handle_inventory()
        elif verb == 'use':
            return self._handle_use(arg)
        elif verb == 'score':
            return self._handle_score()
        else:
            return "Unknown command."

    def _handle_look(self, arg: str | None) -> str:
        room = self.world.rooms[self.room_id]

        if arg is None:
            # Handle 'look'

            lines = [room.name]
            lines.append(room.description)

            # Exits
            exits_list = []
            for direction in DIRECTIONS:
                if direction in room.exits:
                    target = room.exits[direction]
                    is_locked = False
                    if isinstance(target, dict):
                        # Check if the lock exists and hasn't been unlocked
                        lock_key_id = target.get('key')
                        if lock_key_id and (self.room_id, direction) not in self.unlocked:
                            is_locked = True

                    if is_locked:
                         exits_list.append(f"{direction} (locked)")
                    else:
                         exits_list.append(direction)

            exits_str = f"Exits: {', '.join(exits_list)}." if exits_list else "Exits: none."
            lines.append(exits_str)

            # Items
            room_items_ids = self.items_in(self.room_id)
            if room_items_ids:
                item_names = [self._get_item_data(i).name for i in room_items_ids]
                lines.append(f"You see: {', '.join(item_names)}.")

            return "\n".join(lines)

        else:
            # Handle 'look X'
            item, item_id = self._match_item(arg)

            if item:
                return item.description
            else:
                return f"You see no {arg} here."

    def _handle_go(self, direction: str) -> str:
        room = self.world.rooms[self.room_id]

        if direction not in room.exits:
            return "You can't go that way."

        target = room.exits[direction]
        is_locked = False

        if isinstance(target, dict):
            # This is a locked exit definition
            lock_key_id = target.get('key')

            # Check if this specific exit has been unlocked
            if lock_key_id and (self.room_id, direction) not in self.unlocked:
                is_locked = True

        if is_locked:
            return f"The way {direction} is locked."
        else:
            # Move successful
            next_room_id = room.exits[direction]

            # Check for first visit score (only non-start rooms)
            if next_room_id != self.world.start and next_room_id not in self.visited:
                self.score += 10
                self.visited.add(next_room_id)

            self.room_id = next_room_id
            self.moves += 1

            # Update current items list for the new room
            self._current_room_items = self._room_item_order[self.room_id]

            return self._handle_look(None)

    def _handle_take(self, arg: str) -> str:
        item, item_id = self._match_item(arg)

        if not item:
            return f"You see no {arg} here."

        # Check if in Room
        if item_id in self._current_room_items:
            if not item.portable:
                return f"You can't take the {item.name}."

            # Update score if taking for the first time
            if item_id not in self.scored:
                self.score += item.treasure
                self.scored.add(item_id)

            # Move item from room to inventory
            self.inventory.append(item_id)
            self._current_room_items.remove(item_id)
            self._room_item_order[self.room_id].remove(item_id)

            return f"Taken: {item.name}."

        # Check if in Inventory
        elif item_id in self.inventory:
            return f"You already have the {item.name}."

        return f"You see no {arg} here."


    def _handle_drop(self, arg: str) -> str:
        item, item_id = self._match_item(arg)

        if not item:
            return "You aren't carrying that."

        # Check if in Inventory
        if item_id in self.inventory:
            # Move item from inventory to room
            self.inventory.remove(item_id)
            self._current_room_items.append(item_id)
            self._room_item_order[self.room_id].append(item_id)

            return f"Dropped: {item.name}."

        return "You aren't carrying that."

    def _handle_use(self, arg: str) -> str:
        item, item_id = self._match_item(arg)

        if not item:
            return f"You aren't carrying that."

        # Check current room exits for locks matching this key
        unlocked_directions = []
        room = self.world.rooms[self.room_id]

        # Iterate through room's potential exits
        for direction, target in room.exits.items():
            is_locked = isinstance(target, dict) and target.get('key') == item_id

            if is_locked and (self.room_id, direction) not in self.unlocked:
                unlocked_directions.append(direction)

        if unlocked_directions:
            # Unlock all matching exits
            for direction in unlocked_directions:
                self.unlocked.add((self.room_id, direction))

            return f"Unlocked: {', '.join(unlocked_directions)}."
        else:
            return f"Nothing here to use the {item.name} on."


    def _handle_inventory(self) -> str:
        if not self.inventory:
            return "You are carrying nothing."

        item_names = []
        for item_id in self.inventory:
            item = self._get_item_data(item_id)
            if item:
                item_names.append(item.name)

        return f"You are carrying: {', '.join(item_names)}."

    def _handle_score(self) -> str:
        return f"Your score is {self.score}."

    def save(self) -> str:
        """Returns a JSON string of the current game state (Version 2)."""

        items_state: Dict[str, List[str]] = {}
        for room_id, room in self.world.rooms.items():
            # We save the current contents of the room
            items_state[room_id] = self._room_item_order[room_id]

        state = {
            "version": 2,
            "room": self.room_id,
            "inventory": self.inventory,
            "items": items_state,
            "moves": self.moves,
            "score": self.score,
            "visited": sorted(list(self.visited)),
            "scored": sorted(list(self.scored)),
            "unlocked": sorted(list(self.unlocked))
        }
        return json.dumps(state)

    @classmethod
    def load(cls, world: World, text: str) -> 'Game':
        """Loads a game state from a JSON string, handling V1 and V2."""
        try:
            data: Dict[str, Any] = json.loads(text)
        except json.JSONDecodeError:
            raise SaveError("Invalid JSON format.")

        if not isinstance(data, dict):
            raise SaveError("Saved data must be a JSON object.")

        version = data.get('version')

        if version not in (1, 2):
            raise SaveError(f"Unsupported save file version: {version}.")

        try:
            saved_room_id = data['room']
            saved_inventory: List[str] = data['inventory']
            saved_items: Dict[str, List[str]] = data['items']
            saved_moves = data['moves']

            # Load state components based on version
            score = data.get('score', 0)
            visited = set(data.get('visited', []))
            scored = set(data.get('scored', []))
            unlocked = set()

            if version == 2:
                try:
                    saved_unlocked = data['unlocked']
                    if not isinstance(saved_unlocked, list):
                         raise SaveError("Unlocked list must be a list.")
                    unlocked = set(tuple(item) for item in saved_unlocked)
                except KeyError:
                    raise SaveError("Version 2 save is missing the 'unlocked' key.")

                # Final check for V2 state keys
                if not all(k in data for k in ["score", "visited", "scored"]):
                     raise SaveError("Version 2 save is missing score, visited, or scored.")

        except KeyError as e:
            raise SaveError(f"Missing required key in save file: {e}.")

        # --- Validation Checks ---

        if saved_moves < 0 or not isinstance(saved_moves, int):
            raise SaveError("Moves must be a non-negative integer.")
        if score < 0 or not isinstance(score, int):
             raise SaveError("Score must be a non-negative integer.")

        if saved_room_id not in world.rooms:
            raise SaveError(f"Room ID '{saved_room_id}' not found in world.")

        seen_item_ids = set()

        # Check inventory items
        for item_id in saved_inventory:
            if item_id not in world.items:
                raise SaveError(f"Inventory contains unknown item ID '{item_id}'.")
            if item_id in seen_item_ids:
                raise SaveError(f"Item ID '{item_id}' appears more than once in inventory.")
            seen_item_ids.add(item_id)

        # Check room items
        for room_id, item_list in saved_items.items():
            if room_id not in world.rooms:
                raise SaveError(f"Room ID '{room_id}' in save file not found in world.")

            for item_id in item_list:
                if item_id not in world.items:
                    raise SaveError(f"Room '{room_id}' contains unknown item ID '{item_id}'.")
                if item_id in seen_item_ids:
                    raise SaveError(f"Item ID '{item_id}' appears more than once across inventory and rooms.")
                seen_item_ids.add(item_id)

        # Validate unlocked exits (V2 only)
        if version == 2:
            for room_id, direction in unlocked:
                room = world.rooms[room_id]
                target = room.exits[direction]
                if not isinstance(target, dict):
                    raise SaveError(f"Unlocked entry ({room_id}, {direction}) does not correspond to a locked exit.")
                key_id = target.get('key')
                if key_id not in world.items:
                    raise SaveError(f"Unlocked entry requires unknown key item '{key_id}'.")
                if (room_id, direction) not in world.rooms[room_id].locks:
                     raise SaveError(f"Unlocked entry ({room_id}, {direction}) was never a locked exit.")


        # --- Game Initialization ---
        game = cls(world)
        game.room_id = saved_room_id
        game.inventory = saved_inventory
        game.moves = saved_moves
        game.score = score
        game.visited = visited
        game.scored = scored
        game.unlocked = unlocked

        # Reconstruct room item state
        game._room_item_order = saved_items
        game._current_room_items = saved_items.get(game.room_id, [])

        return game
