import hashlib
from dataclasses import dataclass, field
from typing import NamedTuple, Any, Tuple, Iterable, Dict
import io

class CorruptObject(ValueError):
    """Raised when an object serialization is malformed or corrupt."""
    pass

class Blob:
    """Represents a file content object."""
    def __init__(self, data: bytes):
        self.data = data

    def __eq__(self, other: Any) -> bool:
        return isinstance(other, Blob) and self.data == other.data

    def __hash__(self):
        return hash(self.data)

    def __repr__(self):
        return f"Blob({repr(self.data)[:20]}...)"

class TreeEntry(NamedTuple):
    """Represents an entry within a tree."""
    name: str
    kind: str  # 'blob' or 'tree'
    oid: str

class Tree:
    """Represents a directory structure."""
    def __init__(self, entries: Iterable[TreeEntry]):
        self._entries = self._validate_and_sort(entries)

    def _validate_entry(self, entry: TreeEntry):
        if not entry.name:
            raise ValueError("Tree entry name cannot be empty.")
        if entry.name in (".", ".."):
            raise ValueError("Tree entry name cannot be '.' or '..'.")
        # Check for illegal characters: /, "\0", "\t", "\n"
        if '/' in entry.name or '\0' in entry.name or '\t' in entry.name or '\n' in entry.name:
            raise ValueError(f"Invalid character found in tree entry name: {entry.name}")
        if entry.kind not in ('blob', 'tree'):
            raise ValueError(f"Invalid kind '{entry.kind}' for entry {entry.name}.")
        if len(entry.oid) != 40 or not all(c in '0123456789abcdef' for c in entry.oid):
            raise ValueError(f"Invalid OID format: {entry.oid}")

    def _validate_and_sort(self, entries: Iterable[TreeEntry]) -> Tuple[TreeEntry, ...]:
        validated = []
        for entry in entries:
            self._validate_entry(entry)
            validated.append(entry)

        # Sort by UTF-8 bytes of the names
        sorted_entries = tuple(sorted(validated, key=lambda e: e.name.encode('utf-8')))
        return sorted_entries

    @property
    def entries(self) -> Tuple[TreeEntry, ...]:
        return self._entries

    def __eq__(self, other: Any) -> bool:
        return isinstance(other, Tree) and self._entries == other._entries

    def __hash__(self):
        # Hash based on the canonical representation (the tuple of entries)
        return hash(self._entries)

    def __repr__(self):
        return f"Tree(entries={len(self._entries)})"

@dataclass(frozen=True)
class Commit:
    """Represents a commit object."""
    tree: str  # OID of the root tree
    parents: Tuple[str, ...]
    author: str
    timestamp: int
    message: str

    def __post_init__(self):
        if not isinstance(self.tree, str) or len(self.tree) != 40:
            raise ValueError("Tree OID must be a valid 40-char hex string.")
        for parent_oid in self.parents:
            if not isinstance(parent_oid, str) or len(parent_oid) != 40:
                raise ValueError("Parent OID must be a valid 40-char hex string.")

        if "\n" in self.author:
            raise ValueError("Author string cannot contain newlines.")

        if not isinstance(self.timestamp, int) or self.timestamp < 0:
            raise ValueError("Timestamp must be a non-negative integer.")

        # Note: We assume message content is valid ASCII/UTF-8 and doesn't strictly need format validation here,
        # only that it is present.

    def __eq__(self, other: Any) -> bool:
        return isinstance(other, Commit) and self.__dict__ == other.__dict__

    def __hash__(self):
        return hash(self.__dict__)

    def __repr__(self):
        return f"Commit(tree={self.tree}, parents={len(self.parents)}, msg='{self.message[:20]}...')"


def object_id(obj: Any) -> str:
    """Calculates the SHA-1 oid of a serialized object."""
    raw = serialize(obj)
    return hashlib.sha1(raw).hexdigest()

def serialize(obj: Any) -> bytes:
    """Serializes an object into a Git-like content-addressable format."""
    if isinstance(obj, Blob):
        type_str = "blob"
        body = obj.data
        length = len(body)
    elif isinstance(obj, Tree):
        type_str = "tree"
        body = b""
        for entry in obj.entries:
            # Format: f"{kind} {oid}\t{name}\n"
            line = f"{entry.kind} {entry.oid}\t{entry.name}\n".encode('utf-8')
            body += line
        length = len(body)
    elif isinstance(obj, Commit):
        type_str = "commit"
        body = io.BytesIO()

        # 1. Tree
        body.write(f"tree {obj.tree}\n".encode('utf-8'))

        # 2. Parents
        for parent in obj.parents:
            body.write(f"parent {parent}\n".encode('utf-8'))

        # 3. Author
        body.write(f"author {obj.author}\n".encode('utf-8'))

        # 4. Time
        body.write(f"time {obj.timestamp}\n".encode('utf-8'))

        # 5. Blank line
        body.write("\n".encode('utf-8'))

        # 6. Message
        body.write(obj.message.encode('utf-8'))

        body = body.getvalue()
        length = len(body)
    else:
        raise TypeError(f"Unknown object type: {type(obj)}")

    # Header format: TYPE LENGTH\0
    header = f"{type_str} {length}".encode('ascii')
    return header + b"\x00" + body

def parse_object(raw: bytes) -> Any:
    """Parses a raw bytes object into the corresponding structured object."""

    if len(raw) < 11:  # Minimum header size (e.g., 'blob 0\x00')
        raise CorruptObject("Object too short to contain header.")

    # Parse Header
    try:
        # Find the null byte separating header and body
        null_idx = raw.index(b'\x00')
        header_bytes = raw[:null_idx]
        header_parts = header_bytes.decode('ascii').split()

        if len(header_parts) != 2:
            raise CorruptObject("Malformed header: expected TYPE LENGTH.")

        obj_type = header_parts[0]
        length = int(header_parts[1])
    except (ValueError, IndexError, UnicodeDecodeError):
        raise CorruptObject("Malformed header or length field.")

    body = raw[null_idx + 1:]

    if len(body) != length:
        raise CorruptObject(f"Length mismatch. Expected {length} bytes, got {len(body)}.")

    if obj_type == 'blob':
        return Blob(body)

    elif obj_type == 'tree':
        entries = []
        try:
            # Iterate line by line in the body
            for line_bytes in body.splitlines():
                if not line_bytes:
                    continue

                parts = line_bytes.decode('utf-8').split('\t')
                if len(parts) != 3:
                    raise CorruptObject(f"Malformed tree entry line: {line_bytes.decode('utf-8')}")

                kind, oid, name = parts[0], parts[1], parts[2]
                entries.append(TreeEntry(name=name, kind=kind, oid=oid))

            # Tree constructor handles validation and sorting
            return Tree(entries)
        except Exception as e:
            raise CorruptObject(f"Failed to parse tree body: {e}")

    elif obj_type == 'commit':

        # Commit parsing is stateful and complex, needs careful line-by-line processing

        # Standard fields: tree, parent N times, author, time
        tree_oid = None
        parents = []
        author = None
        timestamp = None
        message_start_index = -1

        lines = body.splitlines(keepends=True)

        for i, line_bytes in enumerate(lines):
            line = line_bytes.decode('utf-8').strip()
            if not line:
                # Found the blank line separating metadata from message
                message_start_index = i + 1
                break

            parts = line.split(maxsplit=1)
            if not parts:
                continue

            key = parts[0]
            value = parts[1] if len(parts) > 1 else None

            if key == "tree":
                tree_oid = value
            elif key == "parent":
                parents.append(value)
            elif key == "author":
                author = value
            elif key == "time":
                try:
                    timestamp = int(value)
                except ValueError:
                    raise CorruptObject("Malformed commit time field.")
            else:
                raise CorruptObject(f"Unknown commit metadata field: {key}")

        if tree_oid is None or author is None or timestamp is None:
             raise CorruptObject("Commit body missing required fields (tree, author, time).")

        # Extract message
        message = b"".join(lines[message_start_index:]).decode('utf-8')

        return Commit(
            tree=tree_oid,
            parents=tuple(parents),
            author=author,
            timestamp=timestamp,
            message=message
        )

    else:
        raise CorruptObject(f"Unknown object type in header: {obj_type}")
