from typing import Dict, Any, Tuple, Optional, List
import time

from .objects import (
    Blob, Tree, TreeEntry, Commit, CorruptObject, 
    object_id, parse_object, TreeEntry, Commit
)

class ObjectNotFound(KeyError):
    """Raised when an object ID is not found in the store."""
    pass

class AmbiguousPrefix(ValueError):
    """Raised when a prefix resolves to multiple objects."""
    pass

class ObjectStore:
    """
    In-memory store for content-addressed objects.
    """
    def __init__(self):
        # {oid: object}
        self._store: Dict[str, Any] = {}

    def put(self, obj: Any) -> str:
        """Stores an object and returns its oid."""
        oid = object_id(obj)
        self._store[oid] = obj
        return oid

    def put_raw(self, raw: bytes) -> str:
        """Parses raw bytes and stores the resulting object."""
        try:
            obj = parse_object(raw)
            return self.put(obj)
        except CorruptObject as e:
            raise CorruptObject(f"Failed to put raw object: {e}")

    def get(self, oid: str) -> Any:
        """Returns the object corresponding to the oid."""
        if oid not in self._store:
            raise ObjectNotFound(f"Object not found for oid: {oid}")
        return self._store[oid]

    def get_raw(self, oid: str) -> bytes:
        """Returns the raw serialized bytes for the given oid."""
        if oid not in self._store:
            raise ObjectNotFound(f"Object not found for oid: {oid}")
        return self.serialize_object(self._store[oid])

    def serialize_object(self, obj: Any) -> bytes:
        """Helper to serialize an object."""
        # Requires the object to expose a serialize method or use the external one
        from .objects import serialize
        return serialize(obj)

    def __contains__(self, oid: str) -> bool:
        return oid in self._store

    def resolve(self, prefix: str) -> str:
        """
        Returns the one stored oid that starts with the prefix.
        """
        if not (4 <= len(prefix) <= 40) or not all(c in '0123456789abcdef' for c in prefix):
            raise ValueError("Prefix must be 4 to 40 lowercase hex characters.")

        matches = [
            oid for oid in self._store
            if oid.startswith(prefix) and len(oid) == 40
        ]

        if len(matches) == 0:
            raise ObjectNotFound(f"No object found starting with prefix: {prefix}")
        if len(matches) > 1:
            raise AmbiguousPrefix(f"Multiple objects found starting with prefix: {prefix}")

        return matches[0]

    def write_tree(self, files: Dict[str, bytes]) -> str:
        """
        Takes a dict of paths->bytes, stores blobs and trees, returns the root tree's oid.
        """
        if not files:
            # Empty tree
            empty_tree = Tree([])
            return self.put(empty_tree)

        # Step 1: Process files and identify necessary directories/blobs
        path_map: Dict[str, str] = {} # full_path -> blob_oid
        directories: Dict[str, None] = {} # directory_path -> None

        for path, data in files.items():
            # Validate path format
            if not path or path.startswith('/') or path.endswith('/') or any(c in path for c in ('\0', '\t', '\n')):
                 raise ValueError(f"Invalid path format: {path}")

            # Split path into components
            parts = path.split('/')

            current_dir = ''

            for i, part in enumerate(parts):
                if not part: # Handles cases like 'a//b' or leading/trailing slashes (already checked, but safe)
                    raise ValueError(f"Path '{path}' contains empty segment.")

                full_path_part = f"{current_dir}/{part}" if current_dir else part

                if i == len(parts) - 1:
                    # This is the file name
                    if full_path_part in directories:
                        raise ValueError(f"Path conflict: '{full_path_part}' is both a file and a directory.")

                    # Store blob
                    blob = Blob(data)
                    blob_oid = self.put(blob)
                    path_map[path] = blob_oid
                else:
                    # This is a directory segment
                    current_dir = full_path_part
                    directories[current_dir] = None

        # Step 2: Build the tree structure recursively

        # We need to identify all unique directories created by files
        dir_oids: Dict[str, str] = {} # full_path -> tree_oid

        # Process directories from smallest (deepest) to largest (shallowest)
        sorted_dirs = sorted(list(directories.keys()), key=len, reverse=True)

        for dir_path in sorted_dirs:
            entries: List[TreeEntry] = []

            # Find all files contained within this directory
            contained_files = [
                p for p in path_map if p.startswith(dir_path + '/')
            ]

            # Collect entries: files and subdirectories
            for file_path in contained_files:
                parts = file_path.split('/')

                # Determine the name relative to the current directory
                # e.g., dir_path='a/b', file_path='a/b/c.txt'. Name is 'c.txt'
                relative_name = parts[-1]

                # We need to find the immediate sub-directory name
                # Example: if dir_path is 'a/b', the file is in the root of 'a/b'.
                # The relative name is the last component of the full path.

                # Re-calculate relative path based on directory structure
                relative_path = file_path[len(dir_path) + 1:]

                if '/' not in relative_path:
                    # It's a file directly in this directory
                    blob_oid = path_map[file_path]
                    entries.append(TreeEntry(name=relative_path, kind='blob', oid=blob_oid))
                else:
                    # It contains subdirectories. We need to find the root subtree
                    # The first path component of the remaining relative path is the subdirectory name.
                    subdir_path = relative_path.split('/')[0]

                    # The full path of the subdirectory is dir_path + '/' + subdir_path
                    full_subdir_path = f"{dir_path}/{subdir_path}"

                    # Ensure this subdirectory has been processed (it should be, due to sorting)
                    if full_subdir_path not in dir_oids:
                         # This should not happen if sorting worked correctly
                         raise RuntimeError("Internal tree processing error: Subdirectory not processed.")

                    subdir_oid = dir_oids[full_subdir_path]
                    entries.append(TreeEntry(name=subdir_path, kind='tree', oid=subdir_oid))

            # Create and store the tree for the current directory
            new_tree = Tree(entries)
            tree_oid = self.put(new_tree)
            dir_oids[dir_path] = tree_oid

        # The root tree is the one for the current working directory (empty path)
        return dir_oids.get("", self.put(Tree([])))


    def read_tree(self, oid: str) -> Dict[str, bytes]:
        """
        Reads a tree and returns a dict mapping file path to its content (bytes).
        """
        tree = self.get(oid)
        if not isinstance(tree, Tree):
            raise ValueError("Object specified is not a Tree.")

        files_content: Dict[str, bytes] = {}

        # Helper function to recursively traverse entries
        def traverse(entries: Tuple[TreeEntry, ...], current_path: str = ""):
            for entry in entries:
                entry_path = f"{current_path}/{entry.name}" if current_path else entry.name

                if entry.kind == 'blob':
                    blob = self.get(entry.oid)
                    if not isinstance(blob, Blob):
                        raise CorruptObject(f"Tree entry {entry_path} points to a non-blob object.")
                    files_content[entry_path] = blob.data
                elif entry.kind == 'tree':
                    subtree = self.get(entry.oid)
                    if not isinstance(subtree, Tree):
                        raise CorruptObject(f"Tree entry {entry_path} points to a non-tree object.")
                    traverse(subtree.entries, entry_path)

        traverse(tree.entries)

        # Return sorted by path
        return dict(sorted(files_content.items()))

    def commit(self, tree: str, parents: Tuple[str, ...], author: str, timestamp: int, message: str) -> str:
        """Stores a Commit object and returns its oid."""

        # Basic validation
        if not all(len(oid) == 40 for oid in [tree] + list(parents)):
            raise ValueError("All OIDs must be 40 characters.")

        # Check existence and type
        try:
            root_tree = self.get(tree)
        except ObjectNotFound:
            raise ObjectNotFound(f"Tree OID {tree} not found.")

        if not isinstance(root_tree, Tree):
            raise ValueError(f"Object {tree} is not a Tree.")

        for p_oid in parents:
            try:
                parent_obj = self.get(p_oid)
            except ObjectNotFound:
                raise ObjectNotFound(f"Parent OID {p_oid} not found.")
            except Exception:
                # If it exists but is not a commit, the Commit constructor will fail, 
                # but we check upfront for safety
                if not isinstance(parent_obj, Commit):
                    raise ValueError(f"Parent object {p_oid} is not a Commit.")


        commit_obj = Commit(
            tree=tree,
            parents=parents,
            author=author,
            timestamp=timestamp,
            message=message
        )
        return self.put(commit_obj)

    def log(self, oid: str, first_parent: bool = False) -> List[str]:
        """
        Returns commit oids starting from oid, ordered by timestamp (newest first).
        If first_parent=True, walks ancestry chain.
        Otherwise, walks all ancestors.
        """

        commit_obj = self.get(oid)
        if not isinstance(commit_obj, Commit):
            raise ValueError(f"Object {oid} is not a Commit.")

        # Structure to hold commits discovered
        all_commits: Dict[str, Commit] = {}

        # Use a stack/queue for traversal
        stack: List[str] = [oid]
        visited: set[str] = set()

        # If walking all ancestors, start with the root commit
        if not first_parent:
            # Since we don't have a concept of 'repository root', we traverse everything
            # This implementation assumes a single connected component reachable from `oid`.
            pass
        else:
            # If walking single chain, we only care about the first parent
            pass


        while stack:
            current_oid = stack.pop()
            if current_oid in visited:
                continue

            try:
                commit = self.get(current_oid)
            except ObjectNotFound:
                continue # Should not happen if oid was added to stack

            if not isinstance(commit, Commit):
                continue

            visited.add(current_oid)
            all_commits[current_oid] = commit

            if first_parent:
                # Chain traversal
                if commit.parents:
                    next_parent_oid = commit.parents[0]
                    if next_parent_oid not in visited:
                        stack.append(next_parent_oid)
            else:
                # All ancestors traversal
                for parent_oid in commit.parents:
                    if parent_oid not in visited:
                        stack.append(parent_oid)

        # Order results: newest first (descending timestamp)
        sorted_commits = sorted(
            all_commits.values(),
            key=lambda c: c.timestamp,
            reverse=True
        )

        # Secondary sort: equal timestamps ordered by oid ascending
        # Since the commit object is immutable and its contents define its OID,
        # we can use the OID as a tiebreaker for timestamp.

        # Re-sort using OID as tiebreaker
        def sort_key(c: Commit):
            return (-c.timestamp, c.tree) # Use tree as proxy for stability, or calculate full oid

        # Since we only stored the Commit object, we must rely on the object identity/content hash for OID
        # To be rigorous, let's retrieve the OID based on the stored object

        def commit_sort_key(c: Commit):
            return (-c.timestamp, object_id(c))

        sorted_commits = sorted(all_commits.values(), key=commit_sort_key)


        return [object_id(c) for c in sorted_commits]
