class Change(NamedTuple):
    """Represents a detected change between two states."""
    status: str  # 'A' added, 'D' deleted, 'M' modified
    path: str
    old: Optional[str]  # Blob OID or None
    new: Optional[str]  # Blob OID or None

def diff_trees(store: ObjectStore, old_oid: Optional[str], new_oid: Optional[str]) -> List[Change]:
    """
    Compares two tree structures and returns a sorted list of changes.
    """

    # Helper to get content (dict[path] -> bytes) or empty dict
    def get_content(oid: Optional[str]) -> Dict[str, bytes]:
        if oid is None:
            return {}
        try:
            return store.read_tree(oid)
        except ObjectNotFound:
            # If the expected tree doesn't exist, treat it as empty.
            return {}
        except (ValueError, CorruptObject) as e:
            raise ValueError(f"Error reading tree at OID {oid}: {e}")


    old_content = get_content(old_oid)
    new_content = get_content(new_oid)

    changes: List[Change] = []
    all_paths = set(old_content.keys()) | set(new_content.keys())

    # Recursive traversal needed to handle directory/file type changes
    def _traverse_and_compare(old_entries: Optional[Tuple[TreeEntry, ...]], 
                               new_entries: Optional[Tuple[TreeEntry, ...]], 
                               current_path: str = ""):

        old_map: Dict[str, TreeEntry] = {e.name: e for e in (old_entries or tuple())}
        new_map: Dict[str, TreeEntry] = {e.name: e for e in (new_entries or tuple())}

        old_names = set(old_map.keys())
        new_names = set(new_map.keys())

        # Paths to check: added, deleted, or modified/present
        for name in old_names | new_names:

            old_entry = old_map.get(name)
            new_entry = new_map.get(name)

            path = f"{current_path}/{name}" if current_path else name

            if old_entry and new_entry:
                # Path exists in both
                if old_entry.kind == 'blob' and new_entry.kind == 'blob':
                    # File vs File
                    if old_entry.oid != new_entry.oid:
                        changes.append(Change('M', path, old_entry.oid, new_entry.oid))
                    # If OIDs match, skip (no change)

                elif old_entry.kind == 'tree' and new_entry.kind == 'tree':
                    # Directory vs Directory: Recurse
                    old_tree = store.get(old_entry.oid)
                    new_tree = store.get(new_entry.oid)
                    _traverse_and_compare(old_tree.entries, new_tree.entries, path)

                elif old_entry.kind == 'blob' and new_entry.kind == 'tree':
                    # File -> Directory (Deletion of file, Addition of directory)
                    # We treat this as a deletion of the file, followed by additions of everything in the new directory
                    # For simplicity, we mark the original file as deleted
                    changes.append(Change('D', path, old_entry.oid, None))

                    # Recursively list all contents of the new directory as 'A'
                    new_tree = store.get(new_entry.oid)
                    _list_tree_contents(new_tree.entries, path, changes)

                elif old_entry.kind == 'tree' and new_entry.kind == 'blob':
                    # Directory -> File (Deletion of directory, Addition of file)
                    changes.append(Change('D', path, old_entry.oid, None))

                    # Recursively list all contents of the old directory as 'D'
                    old_tree = store.get(old_entry.oid)
                    _list_tree_contents(old_tree.entries, path, changes, delete=True)

                else:
                    # Kind mismatch (e.g., blob -> tree)
                    # Handle as deletion/addition based on the type change
                    if old_entry.kind == 'blob' and new_entry.kind == 'tree':
                        changes.append(Change('D', path, old_entry.oid, None))
                        new_tree = store.get(new_entry.oid)
                        _list_tree_contents(new_tree.entries, path, changes)
                    elif old_entry.kind == 'tree' and new_entry.kind == 'blob':
                        changes.append(Change('D', path, old_entry.oid, None))
                        old_tree = store.get(old_entry.oid)
                        _list_tree_contents(old_tree.entries, path, changes, delete=True)

            elif old_entry and not new_entry:
                # Deleted (D)
                changes.append(Change('D', path, old_entry.oid, None))

            elif not old_entry and new_entry:
                # Added (A)
                changes.append(Change('A', path, None, new_entry.oid))

    # Helper to recursively list all files within a tree (used when a directory changes type)
    def _list_tree_contents(entries: Tuple[TreeEntry, ...], base_path: str, changes: List[Change], delete: bool = False):
        for entry in entries:
            entry_path = f"{base_path}/{entry.name}"
            if entry.kind == 'blob':
                status = 'D' if delete else 'A'
                changes.append(Change(status, entry_path, None if status == 'D' else entry.oid, entry.oid if status == 'A' else None))
            elif entry.kind == 'tree':
                subtree = store.get(entry.oid)
                _list_tree_contents(subtree.entries, entry_path, changes, delete)

    _traverse_and_compare(
        old_oid is not None and store.get(old_oid).entries or None, 
        new_oid is not None and store.get(new_oid).entries or None
    )

    # Sort by path as required
    return sorted(changes, key=lambda c: c.path)


def diff_commits(store: ObjectStore, old_oid: Optional[str], new_oid: Optional[str]) -> List[Change]:
    """Diffs the trees referenced by two commits."""
    if old_oid is None:
        old_tree_oid = None
    else:
        try:
            old_commit = store.get(old_oid)
            if not isinstance(old_commit, Commit):
                raise ValueError("Old OID is not a Commit.")
            old_tree_oid = old_commit.tree
        except ObjectNotFound:
            raise ObjectNotFound(f"Old commit OID {old_oid} not found.")

    if new_oid is None:
        new_tree_oid = None
    else:
        try:
            new_commit = store.get(new_oid)
            if not isinstance(new_commit, Commit):
                raise ValueError("New OID is not a Commit.")
            new_tree_oid = new_commit.tree
        except ObjectNotFound:
            raise ObjectNotFound(f"New commit OID {new_oid} not found.")

    return diff_trees(store, old_tree_oid, new_tree_oid)

def format_changes(changes: List[Change]) -> str:
    """Formats a list of Change objects into a single line per change."""
    return "\n".join(f"{c.status}\t{c.path}" for c in changes)
